function normalizeAdminAddUserDraft(draft = null) {
  const nextDraft = draft && typeof draft === "object" && !Array.isArray(draft) ? draft : {};
  return {
    name: String(nextDraft.name || ""),
    email: String(nextDraft.email || ""),
    password: String(nextDraft.password || ""),
    phone: String(nextDraft.phone || ""),
    role: String(nextDraft.role || "") === "admin" ? "admin" : "student",
    academicYear: String(sanitizeAcademicYear(nextDraft.academicYear || 1)),
    academicSemester: String(sanitizeAcademicSemester(nextDraft.academicSemester || 1)),
  };
}

function hasAdminAddUserDraftChanges(draft = null) {
  const normalizedDraft = normalizeAdminAddUserDraft(draft);
  return Boolean(
    normalizedDraft.name.trim()
    || normalizedDraft.email.trim()
    || normalizedDraft.password
    || normalizedDraft.phone.trim()
    || normalizedDraft.role !== "student"
    || normalizedDraft.academicYear !== "1"
    || normalizedDraft.academicSemester !== "1"
  );
}

function normalizeAdminUserEnrollmentDraft(draft = null) {
  const nextDraft = draft && typeof draft === "object" && !Array.isArray(draft) ? draft : {};
  return {
    name: String(nextDraft.name ?? ""),
    phone: String(nextDraft.phone ?? ""),
    academicYear: String(normalizeAcademicYearOrNull(nextDraft.academicYear) ?? ""),
    academicSemester: String(normalizeAcademicSemesterOrNull(nextDraft.academicSemester) ?? ""),
  };
}

function getAdminUserEnrollmentDraft(userId) {
  const normalizedUserId = String(userId || "").trim();
  if (!normalizedUserId) {
    return null;
  }
  const draft = state.adminUserEnrollmentDrafts?.[normalizedUserId];
  return draft && typeof draft === "object" && !Array.isArray(draft)
    ? normalizeAdminUserEnrollmentDraft(draft)
    : null;
}

function hasAdminUserEnrollmentDraftChanges(account, draft = null) {
  if (!account || !draft) {
    return false;
  }
  const normalizedDraft = normalizeAdminUserEnrollmentDraft(draft);
  const savedName = String(account.name || "").trim();
  const draftName = String(normalizedDraft.name || "").trim();
  const savedPhone = String(account.phone || "").trim();
  const draftPhone = String(normalizedDraft.phone || "").trim();
  const savedYear = account.role === "student"
    ? String(normalizeAcademicYearOrNull(account.academicYear) ?? "")
    : "";
  const savedSemester = account.role === "student"
    ? String(normalizeAcademicSemesterOrNull(account.academicSemester) ?? "")
    : "";
  return (
    draftName !== savedName
    || draftPhone !== savedPhone
    || normalizedDraft.academicYear !== savedYear
    || normalizedDraft.academicSemester !== savedSemester
  );
}

function setAdminUserEnrollmentDraft(userId, draft, account = null) {
  const normalizedUserId = String(userId || "").trim();
  if (!normalizedUserId) {
    return null;
  }
  const normalizedDraft = normalizeAdminUserEnrollmentDraft(draft);
  const targetAccount = account || getUsers().find((entry) => String(entry?.id || "").trim() === normalizedUserId) || null;
  if (!targetAccount || !hasAdminUserEnrollmentDraftChanges(targetAccount, normalizedDraft)) {
    if (state.adminUserEnrollmentDrafts && Object.prototype.hasOwnProperty.call(state.adminUserEnrollmentDrafts, normalizedUserId)) {
      delete state.adminUserEnrollmentDrafts[normalizedUserId];
    }
    return null;
  }
  state.adminUserEnrollmentDrafts[normalizedUserId] = normalizedDraft;
  return normalizedDraft;
}

function clearAdminUserEnrollmentDraft(userId) {
  const normalizedUserId = String(userId || "").trim();
  if (!normalizedUserId || !state.adminUserEnrollmentDrafts || !Object.prototype.hasOwnProperty.call(state.adminUserEnrollmentDrafts, normalizedUserId)) {
    return false;
  }
  delete state.adminUserEnrollmentDrafts[normalizedUserId];
  return true;
}

function hasAdminUserEnrollmentDrafts() {
  return Boolean(
    state.adminUserEnrollmentDrafts
    && Object.keys(state.adminUserEnrollmentDrafts).length,
  );
}

function getAdminUserEnrollmentSaveMode(userId) {
  const normalizedUserId = String(userId || "").trim();
  if (!normalizedUserId) {
    return "";
  }
  const mode = String(state.adminUserEnrollmentSaving?.[normalizedUserId] || "").trim();
  return mode === "auto" ? "auto" : (mode === "manual" ? "manual" : "");
}

function setAdminUserEnrollmentSaveMode(userId, mode = "") {
  const normalizedUserId = String(userId || "").trim();
  if (!normalizedUserId) {
    return "";
  }
  const normalizedMode = mode === "auto" ? "auto" : (mode === "manual" ? "manual" : "");
  if (!normalizedMode) {
    if (state.adminUserEnrollmentSaving && Object.prototype.hasOwnProperty.call(state.adminUserEnrollmentSaving, normalizedUserId)) {
      delete state.adminUserEnrollmentSaving[normalizedUserId];
    }
    return "";
  }
  state.adminUserEnrollmentSaving[normalizedUserId] = normalizedMode;
  return normalizedMode;
}

function hasActiveAdminUserEnrollmentSaves() {
  return Boolean(
    state.adminUserEnrollmentSaving
    && Object.keys(state.adminUserEnrollmentSaving).length,
  );
}

function getAdminUserEnrollmentBusyLabel(mode = "manual") {
  return mode === "auto" ? "Auto-saving..." : "Saving...";
}

function renderAdminUserEnrollmentSaveButtonContent(options = {}) {
  const busy = Boolean(options?.busy);
  const mode = options?.mode === "auto" ? "auto" : "manual";
  const baseLabel = String(options?.baseLabel || "Save details");
  return busy
    ? `<span class="inline-loader" aria-hidden="true"></span><span>${escapeHtml(getAdminUserEnrollmentBusyLabel(mode))}</span>`
    : escapeHtml(baseLabel);
}

function setAdminUserEnrollmentSaveButtonBusy(button, busy, options = {}) {
  if (!button) {
    return;
  }
  if (!button.dataset.baseLabel) {
    button.dataset.baseLabel = button.textContent || "Save details";
  }
  const mode = options?.mode === "auto" ? "auto" : "manual";
  button.disabled = busy;
  button.classList.toggle("is-loading", busy);
  button.innerHTML = renderAdminUserEnrollmentSaveButtonContent({
    busy,
    mode,
    baseLabel: button.dataset.baseLabel,
  });
}

function getAdminUserEnrollmentViewModel(account) {
  if (!account) {
    return {
      account,
      draft: null,
      hasUnsavedChanges: false,
    };
  }
  const accountId = String(account.id || "").trim();
  const draft = accountId ? getAdminUserEnrollmentDraft(accountId) : null;
  const hasUnsavedChanges = draft ? hasAdminUserEnrollmentDraftChanges(account, draft) : false;
  if (!hasUnsavedChanges || !draft) {
    return {
      account,
      draft: null,
      hasUnsavedChanges: false,
    };
  }
  const draftYear = account.role === "student" ? normalizeAcademicYearOrNull(draft.academicYear) : null;
  const draftSemester = account.role === "student" ? normalizeAcademicSemesterOrNull(draft.academicSemester) : null;
  return {
    account: {
      ...account,
      name: draft.name,
      phone: draft.phone,
      academicYear: draftYear,
      academicSemester: draftSemester,
      assignedCourses: account.role === "student"
        ? (draftYear !== null && draftSemester !== null ? getCurriculumCourses(draftYear, draftSemester) : [])
        : [...sanitizeCourseAssignments(account.assignedCourses || Object.keys(QBANK_COURSE_TOPICS))],
      enrolledCourses: account.role === "student"
        ? (draftYear !== null && draftSemester !== null ? getCurriculumCourses(draftYear, draftSemester) : [])
        : [],
    },
    draft,
    hasUnsavedChanges: true,
  };
}

function setAdminAddUserDraft(nextDraft) {
  state.adminAddUserDraft = normalizeAdminAddUserDraft(nextDraft);
  state.adminAddUserDraftDirty = hasAdminAddUserDraftChanges(state.adminAddUserDraft);
}

function resetAdminAddUserDraft() {
  state.adminAddUserDraft = createDefaultAdminAddUserDraft();
  state.adminAddUserDraftDirty = false;
}

function shouldDeferAdminUsersAutoRender() {
  if (state.route !== "admin" || String(state.adminPage || "").trim() !== "users") {
    return false;
  }
  return (
    (Boolean(state.adminAddUserPanelOpen) && Boolean(state.adminAddUserDraftDirty))
    || hasAdminUserEnrollmentDrafts()
    || hasActiveAdminUserEnrollmentSaves()
    || adminUserMutationActiveCount > 0
  );
}

