function wireContact() {
  const form = document.getElementById("support-form");
  if (!form) {
    return;
  }

  form.addEventListener("submit", (event) => {
    event.preventDefault();
    toast("MedBank support request captured (prototype mode).");
    form.reset();
  });
}

function wireLanding() {
  wireContact();

  const sections = Array.from(document.querySelectorAll(".landing-scroll-section[id]"));
  if (!sections.length) return;

  const navBtns = Array.from(document.querySelectorAll("#public-nav [data-nav]"));

  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        const sectionId = entry.target.id;
        const routePart = sectionId === "landing-home" ? "landing" : sectionId.replace("landing-", "");
        navBtns.forEach((btn) => {
          btn.classList.toggle("is-active", btn.getAttribute("data-nav") === routePart);
        });
      });
    },
    { rootMargin: "0px 0px -55% 0px", threshold: 0 },
  );

  sections.forEach((section) => observer.observe(section));

  document.querySelectorAll("[data-scroll-to]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const target = document.getElementById(btn.dataset.scrollTo);
      if (target) target.scrollIntoView({ behavior: isReducedMotionEnabled() ? "auto" : "smooth", block: "start" });
    });
  });
}

function normalizeConfiguredAuthRedirectUrl(rawUrl) {
  const configured = String(rawUrl || "").trim();
  if (configured) {
    try {
      const configuredUrl = new URL(configured, window.location.origin);
      configuredUrl.search = "";
      configuredUrl.hash = "";
      if (/^https?:$/i.test(configuredUrl.protocol)) {
        configuredUrl.pathname = configuredUrl.pathname.replace(/\/index\.html$/i, "/");
      }
      return configuredUrl.toString();
    } catch (error) {
      console.warn("Invalid Supabase auth redirect URL override.", error?.message || error);
    }
  }
  return "";
}

function shouldUseMobileAuthRedirect() {
  if (SUPABASE_CONFIG.forceMobileAuthRedirect || window.__MEDBANK_MOBILE_APP__ === true) {
    return true;
  }
  if (window.Capacitor?.isNativePlatform?.() || window.cordova || window.ReactNativeWebView) {
    return true;
  }
  return /^(capacitor|ionic|file):$/i.test(window.location.protocol);
}

function getAuthRedirectToUrl() {
  if (shouldUseMobileAuthRedirect()) {
    const mobileRedirect = normalizeConfiguredAuthRedirectUrl(SUPABASE_CONFIG.mobileAuthRedirectUrl);
    if (mobileRedirect) {
      return mobileRedirect;
    }
  }

  const configured = normalizeConfiguredAuthRedirectUrl(SUPABASE_CONFIG.authRedirectUrl);
  if (configured) {
    return configured;
  }

  if (!/^https?:$/i.test(window.location.protocol)) {
    return "";
  }

  const currentUrl = new URL(window.location.href);
  currentUrl.search = "";
  currentUrl.hash = "";
  currentUrl.pathname = currentUrl.pathname.replace(/\/index\.html$/i, "/");
  return currentUrl.toString();
}

async function getSupabaseAuthClientForInteractiveSignIn() {
  if (!SUPABASE_CONFIG.enabled || !SUPABASE_CONFIG.url || !SUPABASE_CONFIG.anonKey) {
    return {
      client: null,
      message: "Supabase auth is not configured. Google sign-in is unavailable.",
    };
  }
  if (isBrowserOffline()) {
    return {
      client: null,
      message: "You appear to be offline. Reconnect and try Google sign-in again.",
    };
  }

  if (!window.supabase?.createClient) {
    const sdkReady = await waitForSupabaseSdkReady(AUTH_SIGNIN_TIMEOUT_MS);
    if (!sdkReady) {
      return {
        client: null,
        message: "Could not load Google sign-in. Check your connection and try again.",
      };
    }
  }

  await initSupabaseAuth();
  const client = getSupabaseAuthClient();
  if (!client) {
    return {
      client: null,
      message: "Could not start Google sign-in. Check your connection and try again.",
    };
  }
  return { client, message: "" };
}

async function startGoogleOAuthSignIn(authClient) {
  if (!authClient) {
    return { ok: false, message: "Supabase auth is not configured. Google sign-in is unavailable." };
  }

  const redirectTo = getAuthRedirectToUrl();
  if (!redirectTo) {
    return {
      ok: false,
      message: "Google sign-in requires an http(s) app URL. Open the deployed site URL and try again.",
    };
  }

  const { data, error } = await queueSupabaseAuthRequest(
    authClient,
    () => authClient.auth.signInWithOAuth({
      provider: "google",
      options: {
        redirectTo,
        skipBrowserRedirect: true,
        queryParams: {
          prompt: "select_account",
        },
      },
    }),
    {
      timeoutMs: GOOGLE_OAUTH_START_TIMEOUT_MS,
      timeoutMessage: "Google sign-in redirect timed out. Please try again.",
    },
  );

  if (error) {
    return { ok: false, message: error.message || "Could not start Google sign-in." };
  }

  const providerUrl = String(data?.url || "").trim();
  if (!providerUrl) {
    return { ok: false, message: "Could not open Google sign-in. Please try again." };
  }

  try {
    window.location.assign(providerUrl);
  } catch (error) {
    return { ok: false, message: error?.message || "Could not open Google sign-in. Please try again." };
  }

  return { ok: true };
}

async function startAppleOAuthSignIn(authClient) {
  if (!authClient) {
    return { ok: false, message: "Supabase auth is not configured. Apple sign-in is unavailable." };
  }

  const redirectTo = getAuthRedirectToUrl();
  if (!redirectTo) {
    return {
      ok: false,
      message: "Apple sign-in requires an http(s) app URL. Open the deployed site URL and try again.",
    };
  }

  const { data, error } = await queueSupabaseAuthRequest(
    authClient,
    () => authClient.auth.signInWithOAuth({
      provider: "apple",
      options: {
        redirectTo,
        skipBrowserRedirect: true,
        scopes: "name email",
      },
    }),
    {
      timeoutMs: GOOGLE_OAUTH_START_TIMEOUT_MS,
      timeoutMessage: "Apple sign-in redirect timed out. Please try again.",
    },
  );

  if (error) {
    return { ok: false, message: error.message || "Could not start Apple sign-in." };
  }

  const providerUrl = String(data?.url || "").trim();
  if (!providerUrl) {
    return { ok: false, message: "Could not open Apple sign-in. Please try again." };
  }

  try {
    window.location.assign(providerUrl);
  } catch (error) {
    return { ok: false, message: error?.message || "Could not open Apple sign-in. Please try again." };
  }

  return { ok: true };
}

