function wireAuth(mode) {
  const lockAuthForm = (form, submitting, busyLabel = "Please wait...") => {
    if (!form) return;
    form.dataset.submitting = submitting ? "1" : "0";
    const submitButton = form.querySelector('button[type="submit"]');
    if (!submitButton) return;
    if (!submitButton.dataset.baseLabel) {
      submitButton.dataset.baseLabel = submitButton.textContent || "";
    }
    submitButton.disabled = submitting;
    submitButton.textContent = submitting ? busyLabel : submitButton.dataset.baseLabel;
  };
  const lockAuthActionButton = (button, busy, busyLabel = "Please wait...") => {
    if (!button) return;
    if (!button.dataset.baseLabel) {
      button.dataset.baseLabel = button.textContent || "";
    }
    button.disabled = busy;
    button.textContent = busy ? busyLabel : button.dataset.baseLabel;
  };

  if (mode === "login") {
    const form = document.getElementById("login-form");
    const googleButton = document.getElementById("login-google-btn");
    googleButton?.addEventListener("click", async () => {
      if (form?.dataset.submitting === "1" || googleButton.dataset.submitting === "1") {
        return;
      }
      googleButton.dataset.submitting = "1";
      lockAuthActionButton(googleButton, true, "Checking...");
      try {
        const authReady = await getSupabaseAuthClientForInteractiveSignIn();
        const authClient = authReady.client;
        if (!authClient) {
          googleButton.dataset.submitting = "0";
          lockAuthActionButton(googleButton, false);
          toast(authReady.message || "Google login is unavailable. Please try again.");
          return;
        }
        lockAuthActionButton(googleButton, true, "Redirecting...");
        setGoogleOAuthPendingState(true);
        const outcome = await startGoogleOAuthSignIn(authClient);
        if (!outcome.ok) {
          setGoogleOAuthPendingState(false);
          googleButton.dataset.submitting = "0";
          lockAuthActionButton(googleButton, false);
          toast(outcome.message || "Google login failed. Please try again.");
        }
      } catch (error) {
        setGoogleOAuthPendingState(false);
        googleButton.dataset.submitting = "0";
        lockAuthActionButton(googleButton, false);
        toast(error?.message || "Google login failed. Please try again.");
      }
    });

    const appleButton = document.getElementById("login-apple-btn");
    appleButton?.addEventListener("click", async () => {
      if (form?.dataset.submitting === "1" || appleButton.dataset.submitting === "1") {
        return;
      }
      appleButton.dataset.submitting = "1";
      lockAuthActionButton(appleButton, true, "Checking...");
      try {
        const authReady = await getSupabaseAuthClientForInteractiveSignIn();
        const authClient = authReady.client;
        if (!authClient) {
          appleButton.dataset.submitting = "0";
          lockAuthActionButton(appleButton, false);
          toast(authReady.message || "Apple login is unavailable. Please try again.");
          return;
        }
        lockAuthActionButton(appleButton, true, "Redirecting...");
        setGoogleOAuthPendingState(true);
        const outcome = await startAppleOAuthSignIn(authClient);
        if (!outcome.ok) {
          setGoogleOAuthPendingState(false);
          appleButton.dataset.submitting = "0";
          lockAuthActionButton(appleButton, false);
          toast(outcome.message || "Apple login failed. Please try again.");
        }
      } catch (error) {
        setGoogleOAuthPendingState(false);
        appleButton.dataset.submitting = "0";
        lockAuthActionButton(appleButton, false);
        toast(error?.message || "Apple login failed. Please try again.");
      }
    });

    form?.addEventListener("submit", async (event) => {
      event.preventDefault();
      if (form.dataset.submitting === "1") {
        return;
      }
      lockAuthForm(form, true, "Logging in...");
      const formData = new FormData(form);
      const email = String(formData.get("email") || "").trim().toLowerCase();
      const password = String(formData.get("password") || "");
      const authClient = getSupabaseAuthClient();
      const routeUserToProfileCompletion = (candidateUser) => {
        const completionRoute = getStudentProfileCompletionRoute(candidateUser);
        if (!completionRoute) {
          return false;
        }
        if (candidateUser?.id) {
          save(STORAGE_KEYS.currentUserId, candidateUser.id);
        }
        toast("Complete your profile to activate your account.");
        navigate(completionRoute);
        return true;
      };
      try {
        if (authClient) {
          const { data, error } = await runSupabaseAuthRequestWithTimeout(
            authClient,
            () => authClient.auth.signInWithPassword({ email, password }),
            AUTH_SIGNIN_TIMEOUT_MS,
            "Login request timed out. Check your internet and try again.",
          );
          if (!error && data?.user) {
            let user = upsertLocalUserFromAuth(data.user, {}, {
              persistLocalOnly: true,
            });
            const profileSync = await refreshLocalUserFromRelationalProfile(data.user, user);
            user = profileSync.user;
            if (!user) {
              const fallbackUser = getUsers().find((candidate) => candidate.email.toLowerCase() === email);
              if (fallbackUser) {
                user = fallbackUser;
              } else {
                toast("Could not map account profile after login.");
                return;
              }
            }
            if (user.role === "student") {
              await ensureFreshStudentDataAfterAuth(user, {
                reason: "password sign-in",
              }).catch((warmupError) => {
                console.warn("Student password login refresh failed.", warmupError?.message || warmupError);
              });
              user = getCurrentUser() || user;
            }
            if (routeUserToProfileCompletion(user)) {
              return;
            }
            if (profileSync.approvalChecked && !isUserAccessApproved(user)) {
              if (canRevalidateApprovedStudentAccess(user)) {
                await revalidateApprovedStudentAccess(user, {
                  rerender: false,
                  refreshSnapshot: true,
                }).catch(() => false);
                user = getCurrentUser() || user;
              }
            }
            if (profileSync.approvalChecked && !isUserAccessApproved(user)) {
              removeStorageKey(STORAGE_KEYS.currentUserId);
              await queueSupabaseAuthRequest(authClient, () => authClient.auth.signOut()).catch(() => { });
              toast("Your account is pending admin approval.");
              return;
            }
            if (await shouldForceRefreshForUpdates(user)) {
              return;
            }
            if (!(user.role === "student" && hasSupabaseManagedIdentity(user))) {
              resetStudentLoginRefreshState(user);
            }
            state.studentMcqBankEntered = false;
            navigate(user.role === "admin" ? "admin" : "app-launcher");
            toast(`Welcome back, ${user.name}.`);
            return;
          }

          const localDemoUser = getUsers().find(
            (candidate) => candidate.email.toLowerCase() === email && candidate.password === password,
          );
          if (localDemoUser) {
            const canUseCachedFallback = canUseLocalPasswordFallback(localDemoUser)
              || shouldAllowSupabaseManagedLocalFallback(error);
            if (!canUseCachedFallback) {
              toast(getFriendlyAuthErrorMessage(error, "Supabase sign-in is required for this account. Check your credentials and try again."));
              return;
            }
            if (routeUserToProfileCompletion(localDemoUser)) {
              return;
            }
            if (!isUserAccessApproved(localDemoUser)) {
              toast("Your account is pending admin approval.");
              return;
            }
            save(STORAGE_KEYS.currentUserId, localDemoUser.id);
            resetStudentLoginRefreshState(localDemoUser);
            if (await shouldForceRefreshForUpdates(localDemoUser)) {
              return;
            }
            state.studentMcqBankEntered = false;
            navigate(localDemoUser.role === "admin" ? "admin" : "app-launcher");
            toast(
              shouldAllowSupabaseManagedLocalFallback(error)
                ? `Supabase is unavailable. Signed in with local access for ${localDemoUser.name}.`
                : `Welcome back, ${localDemoUser.name}.`,
            );
            return;
          }

          const knownProvider = getKnownAuthProviderByEmail(email);
          if (knownProvider === "google") {
            toast("This account uses Google sign-in. Use Continue with Google.");
            return;
          }
          toast(getFriendlyAuthErrorMessage(error, getInvalidLoginCredentialsMessage()));
          return;
        }

        const user = getUsers().find((candidate) => candidate.email.toLowerCase() === email && candidate.password === password);
        if (!user) {
          const knownProvider = getKnownAuthProviderByEmail(email);
          if (knownProvider === "google") {
            toast("This account uses Google sign-in. Use Continue with Google.");
            return;
          }
          toast(getInvalidLoginCredentialsMessage());
          return;
        }
        if (routeUserToProfileCompletion(user)) {
          return;
        }
        if (!isUserAccessApproved(user)) {
          toast("Your account is pending admin approval.");
          return;
        }
        save(STORAGE_KEYS.currentUserId, user.id);
        resetStudentLoginRefreshState(user);
        if (await shouldForceRefreshForUpdates(user)) {
          return;
        }
        state.studentMcqBankEntered = false;
        navigate(user.role === "admin" ? "admin" : "app-launcher");
        toast(`Welcome back, ${user.name}.`);
      } catch (error) {
        toast(getFriendlyAuthErrorMessage(error, "Login failed. Please try again."));
      } finally {
        lockAuthForm(form, false);
      }
    });
    return;
  }

  if (mode === "signup") {
    const form = document.getElementById("signup-form");
    if (!form) {
      return;
    }
    const onboardingUser = getCurrentUser();
    const isGoogleOnboardingFlow = isGoogleSignupCompletionFlow(onboardingUser);
    const googleButton = document.getElementById("signup-google-btn");
    const phoneInput = form.querySelector("input[name='phone']");
    const yearSelect = document.getElementById("signup-academic-year");
    const semesterSelect = document.getElementById("signup-academic-semester");
    const courseOptionsEl = document.getElementById("signup-course-options");
    const courseHelpEl = document.getElementById("signup-course-help");
    const selectAllCoursesBtn = document.getElementById("signup-select-all-courses");
    const clearCoursesBtn = document.getElementById("signup-clear-courses");
    if (!isGoogleOnboardingFlow) {
      googleButton?.addEventListener("click", async () => {
        if (form?.dataset.submitting === "1" || googleButton.dataset.submitting === "1") {
          return;
        }
        googleButton.dataset.submitting = "1";
        lockAuthActionButton(googleButton, true, "Checking...");
        try {
          const authReady = await getSupabaseAuthClientForInteractiveSignIn();
          const authClient = authReady.client;
          if (!authClient) {
            googleButton.dataset.submitting = "0";
            lockAuthActionButton(googleButton, false);
            toast(authReady.message || "Google signup is unavailable. Please try again.");
            return;
          }
          lockAuthActionButton(googleButton, true, "Redirecting...");
          setGoogleOAuthPendingState(true);
          const outcome = await startGoogleOAuthSignIn(authClient);
          if (!outcome.ok) {
            setGoogleOAuthPendingState(false);
            googleButton.dataset.submitting = "0";
            lockAuthActionButton(googleButton, false);
            toast(outcome.message || "Google signup failed. Please try again.");
          }
        } catch (error) {
          setGoogleOAuthPendingState(false);
          googleButton.dataset.submitting = "0";
          lockAuthActionButton(googleButton, false);
          toast(error?.message || "Google signup failed. Please try again.");
        }
      });

      const appleButton = document.getElementById("signup-apple-btn");
      appleButton?.addEventListener("click", async () => {
        if (form?.dataset.submitting === "1" || appleButton.dataset.submitting === "1") {
          return;
        }
        appleButton.dataset.submitting = "1";
        lockAuthActionButton(appleButton, true, "Checking...");
        try {
          const authReady = await getSupabaseAuthClientForInteractiveSignIn();
          const authClient = authReady.client;
          if (!authClient) {
            appleButton.dataset.submitting = "0";
            lockAuthActionButton(appleButton, false);
            toast(authReady.message || "Apple signup is unavailable. Please try again.");
            return;
          }
          lockAuthActionButton(appleButton, true, "Redirecting...");
          setGoogleOAuthPendingState(true);
          const outcome = await startAppleOAuthSignIn(authClient);
          if (!outcome.ok) {
            setGoogleOAuthPendingState(false);
            appleButton.dataset.submitting = "0";
            lockAuthActionButton(appleButton, false);
            toast(outcome.message || "Apple signup failed. Please try again.");
          }
        } catch (error) {
          setGoogleOAuthPendingState(false);
          appleButton.dataset.submitting = "0";
          lockAuthActionButton(appleButton, false);
          toast(error?.message || "Apple signup failed. Please try again.");
        }
      });
    }

    const getSelectedSignupCourses = () =>
      Array.from(form?.querySelectorAll("input[name='signupCourses']:checked") || []).map((input) => input.value);

    const persistSignupDraft = () => {
      if (!isGoogleOnboardingFlow) {
        return;
      }
      saveStudentOnboardingDraft({
        phone: phoneInput?.value || "",
        academicYear: yearSelect?.value,
        academicSemester: semesterSelect?.value,
        selectedCourses: getSelectedSignupCourses(),
      }, onboardingUser, "signup");
    };

    const renderSignupCourseOptions = (preferred = [], options = {}) => {
      if (!courseOptionsEl) return;
      const year = normalizeAcademicYearOrNull(yearSelect?.value);
      const semester = normalizeAcademicSemesterOrNull(semesterSelect?.value);
      if (year === null || semester === null) {
        courseOptionsEl.innerHTML = "";
        if (courseHelpEl) {
          courseHelpEl.textContent = "Choose year and semester first.";
        }
        persistSignupDraft();
        return;
      }
      const courses = getCurriculumCourses(year, semester);
      const selectedSet = new Set(preferred.filter((course) => courses.includes(course)));
      const selectAllByDefault = !options.explicitSelection && selectedSet.size === 0;

      courseOptionsEl.innerHTML = courses
        .map(
          (course) => `
            <label class="admin-course-check">
              <input type="checkbox" name="signupCourses" value="${escapeHtml(course)}" ${selectAllByDefault || selectedSet.has(course) ? "checked" : ""} />
              <span>${escapeHtml(course)}</span>
            </label>
          `,
        )
        .join("");

      if (courseHelpEl) {
        courseHelpEl.textContent = courses.length
          ? `${courses.length} course(s) available for this year/semester. Choose one or more.`
          : "No courses available for this year/semester.";
      }
      persistSignupDraft();
    };

    phoneInput?.addEventListener("input", persistSignupDraft);
    yearSelect?.addEventListener("change", () => {
      const preferredCourses = getSelectedSignupCourses();
      const hasExplicitSelection = Boolean(courseOptionsEl?.querySelector("input[name='signupCourses']"));
      renderSignupCourseOptions(preferredCourses, { explicitSelection: hasExplicitSelection });
    });
    semesterSelect?.addEventListener("change", () => {
      const preferredCourses = getSelectedSignupCourses();
      const hasExplicitSelection = Boolean(courseOptionsEl?.querySelector("input[name='signupCourses']"));
      renderSignupCourseOptions(preferredCourses, { explicitSelection: hasExplicitSelection });
    });
    courseOptionsEl?.addEventListener("change", persistSignupDraft);

    selectAllCoursesBtn?.addEventListener("click", () => {
      courseOptionsEl?.querySelectorAll("input[name='signupCourses']").forEach((input) => {
        input.checked = true;
      });
      persistSignupDraft();
    });

    clearCoursesBtn?.addEventListener("click", () => {
      courseOptionsEl?.querySelectorAll("input[name='signupCourses']").forEach((input) => {
        input.checked = false;
      });
      persistSignupDraft();
    });

    const savedDraft = isGoogleOnboardingFlow ? loadStudentOnboardingDraft(onboardingUser, "signup") : null;
    const preferredCourses = Array.isArray(savedDraft?.selectedCourses)
      ? sanitizeCourseAssignments(savedDraft.selectedCourses)
      : (isGoogleOnboardingFlow && Array.isArray(onboardingUser?.assignedCourses)
        ? onboardingUser.assignedCourses
        : []);
    renderSignupCourseOptions(preferredCourses, {
      explicitSelection: Array.isArray(savedDraft?.selectedCourses),
    });

    form?.addEventListener("submit", async (event) => {
      event.preventDefault();
      if (form.dataset.submitting === "1") {
        return;
      }
      if (typeof form.reportValidity === "function" && !form.reportValidity()) {
        return;
      }
      const data = new FormData(form);
      let users = getUsers();
      const name = String(data.get("name") || "").trim();
      const email = String(data.get("email") || "").trim().toLowerCase();
      const phone = String(data.get("phone") || "").trim();
      const phoneValidation = validateAndNormalizePhoneNumber(phone);
      const normalizedPhone = phoneValidation.number;
      const academicYear = normalizeAcademicYearOrNull(data.get("academicYear"));
      const academicSemester = normalizeAcademicSemesterOrNull(data.get("academicSemester"));
      if (academicYear === null || academicSemester === null) {
        toast("You need to choose the year and semester.");
        return;
      }
      const availableCourses = getCurriculumCourses(academicYear, academicSemester);
      if (!availableCourses.length) {
        toast("No courses are available for the selected year and semester.");
        return;
      }
      const selectedCourses = getSelectedSignupCourses().filter((course) => availableCourses.includes(course));
      const emailIsValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
      if (!selectedCourses.length) {
        toast("Select at least one course for your enrollment.");
        return;
      }

      if (isGoogleOnboardingFlow) {
        if (!name || !email || !phone) {
          toast("Name, email, and phone number are required.");
          return;
        }
        if (!emailIsValid) {
          toast("Please enter a valid email address.");
          return;
        }
        if (!phoneValidation.ok) {
          toast(phoneValidation.message || "Phone number is invalid.");
          return;
        }
        let idx = users.findIndex(
          (entry) =>
            entry.id === onboardingUser?.id
            || (onboardingUser?.supabaseAuthId && entry.supabaseAuthId === onboardingUser.supabaseAuthId)
            || entry.email.toLowerCase() === email,
        );
        if (idx === -1) {
          toast("Google account profile was not found. Please sign in again.");
          navigate("login");
          return;
        }

        lockAuthForm(form, true, "Creating account...");
        try {
          const autoApproved = shouldAutoApproveStudentAccess({
            role: "student",
            phone: normalizedPhone,
            academicYear,
            academicSemester,
            assignedCourses: selectedCourses,
          });
          const previousUser = {
            ...users[idx],
            assignedCourses: [...sanitizeCourseAssignments(users[idx].assignedCourses || [])],
          };
          const wasApproved = previousUser.isApproved === true;
          let nextApproved = wasApproved || autoApproved;
          users[idx].name = onboardingUser?.name || name;
          users[idx].email = onboardingUser?.email || email;
          users[idx].phone = normalizedPhone;
          users[idx].role = "student";
          users[idx].academicYear = academicYear;
          users[idx].academicSemester = academicSemester;
          users[idx].assignedCourses = selectedCourses;
          users[idx].isApproved = nextApproved;
          users[idx].approvedAt = nextApproved ? users[idx].approvedAt || nowISO() : null;
          users[idx].approvedBy = nextApproved ? users[idx].approvedBy || AUTO_APPROVAL_ACTOR : null;
          users[idx].profileCompleted = true;
          users[idx].authProvider = "google";

          archiveSessionsForChangedUserEnrollments([previousUser], [users[idx]], {
            reason: "enrollment_change",
            includeCompleted: true,
          });
          save(STORAGE_KEYS.users, users, {
            userSyncScope: USER_RELATIONAL_SYNC_SCOPE_STUDENT_PROFILE,
          });
          save(STORAGE_KEYS.currentUserId, users[idx].id);
          await syncUsersBackupState(users).catch(() => { });
          const metadataAuthClient = getSupabaseAuthClient();
          if (metadataAuthClient) {
            await syncCurrentAuthUserEnrollmentMetadata(metadataAuthClient, users[idx]).catch((metadataError) => {
              console.warn("Could not update Google signup enrollment metadata.", metadataError?.message || metadataError);
            });
          }
          await ensureRelationalSyncReady().catch(() => { });
          if (nextApproved && !wasApproved) {
            const profileId = getUserProfileId(users[idx]);
            if (isUuidValue(profileId)) {
              const approvalResult = await updateRelationalProfileApproval([profileId], true).catch(() => ({ ok: false }));
              if (!approvalResult.ok) {
                nextApproved = false;
                users = getUsers();
                idx = users.findIndex((entry) => entry.email.toLowerCase() === email);
                if (idx >= 0) {
                  users[idx].isApproved = false;
                  users[idx].approvedAt = null;
                  users[idx].approvedBy = null;
                  saveLocalOnly(STORAGE_KEYS.users, users);
                }
              }
            }
          }
          await flushPendingSyncNow();
          clearStudentOnboardingDraft(users[idx], "signup");

          if (nextApproved) {
            save(STORAGE_KEYS.currentUserId, users[idx].id);
            state.studentMcqBankEntered = false;
            toast(wasApproved ? "Account details updated." : "Account created and approved. You can start now.");
            navigate("app-launcher");
          } else {
            const authClient = getSupabaseAuthClient();
            if (authClient) {
              await queueSupabaseAuthRequest(authClient, () => authClient.auth.signOut()).catch(() => { });
            }
            removeStorageKey(STORAGE_KEYS.currentUserId);
            toast("Account created. Await admin approval before first login.");
            navigate("login");
          }
        } catch (error) {
          console.warn("Google signup profile sync failed.", error?.message || error);
          toast("Could not sync your profile to the admin dashboard. Please try again.");
        } finally {
          lockAuthForm(form, false);
        }
        return;
      }

      const password = String(data.get("password") || "");
      const confirmPassword = String(data.get("confirmPassword") || "");
      const inviteCode = String(data.get("inviteCode") || "").trim();

      if (!name || !email || !password || !phone) {
        toast("Name, email, password, and phone number are required.");
        return;
      }
      if (!emailIsValid) {
        toast("Please enter a valid email address.");
        return;
      }
      if (!phoneValidation.ok) {
        toast(phoneValidation.message || "Phone number is invalid.");
        return;
      }
      if (password !== confirmPassword) {
        toast("Password and confirm password must match.");
        return;
      }

      if (users.some((user) => user.email.toLowerCase() === email)) {
        toast("Email already exists.");
        return;
      }

      if (inviteCode) {
        const validCodes = load(STORAGE_KEYS.invites, []);
        if (!validCodes.includes(inviteCode)) {
          toast("Invalid invite code.");
          return;
        }
      }

      lockAuthForm(form, true, "Creating account...");
      const authClient = getSupabaseAuthClient();
      try {
        let autoApproved = shouldAutoApproveStudentAccess({
          role: "student",
          phone: normalizedPhone,
          academicYear,
          academicSemester,
          assignedCourses: selectedCourses,
        });
        if (authClient) {
          const emailRedirectTo = getAuthRedirectToUrl();
          const { data: authData, error } = await queueSupabaseAuthRequest(authClient, () => authClient.auth.signUp({
            email,
            password,
            options: {
              emailRedirectTo,
              data: buildStudentEnrollmentAuthMetadata({
                name,
                phone: normalizedPhone,
                role: "student",
                academicYear,
                academicSemester,
                assignedCourses: selectedCourses,
                authProvider: "email",
              }),
            },
          }));
          if (error) {
            toast(error.message || "Could not create Supabase account.");
            return;
          }

          if (!authData?.user) {
            toast("Signup failed. Please try again.");
            return;
          }

          let effectiveAuthData = authData;
          if (!effectiveAuthData?.session) {
            const signInResult = await queueSupabaseAuthRequest(authClient, () => authClient.auth.signInWithPassword({
              email,
              password,
            }));
            if (!signInResult?.error && signInResult?.data?.user) {
              effectiveAuthData = {
                ...authData,
                user: signInResult.data.user,
                session: signInResult.data.session || null,
              };
            }
          }

          const user = upsertLocalUserFromAuth(effectiveAuthData.user, {
            name,
            role: "student",
            academicYear,
            academicSemester,
            assignedCourses: selectedCourses,
            phone: normalizedPhone,
            verified: Boolean(effectiveAuthData.session),
            isApproved: autoApproved,
            approvedAt: autoApproved ? nowISO() : null,
            approvedBy: autoApproved ? AUTO_APPROVAL_ACTOR : null,
          }, {
            userSyncScope: USER_RELATIONAL_SYNC_SCOPE_STUDENT_PROFILE,
          });
          if (!user) {
            toast("Account created but profile mapping failed.");
            return;
          }

          save(STORAGE_KEYS.currentUserId, user.id);
          await syncUsersBackupState(getUsers()).catch(() => { });
          await ensureRelationalSyncReady().catch(() => { });
          if (autoApproved) {
            const profileId = getUserProfileId(user);
            if (isUuidValue(profileId)) {
              const approvalResult = await updateRelationalProfileApproval([profileId], true).catch(() => ({ ok: false }));
              if (!approvalResult.ok) {
                autoApproved = false;
                const updatedUsers = getUsers();
                const updatedIdx = updatedUsers.findIndex((entry) => entry.email.toLowerCase() === user.email);
                if (updatedIdx >= 0) {
                  updatedUsers[updatedIdx].isApproved = false;
                  updatedUsers[updatedIdx].approvedAt = null;
                  updatedUsers[updatedIdx].approvedBy = null;
                  saveLocalOnly(STORAGE_KEYS.users, updatedUsers);
                }
              }
            }
          }
          await flushPendingSyncNow();

          if (effectiveAuthData.session && !autoApproved) {
            await queueSupabaseAuthRequest(authClient, () => authClient.auth.signOut()).catch(() => { });
          }
          if (autoApproved && effectiveAuthData.session) {
            save(STORAGE_KEYS.currentUserId, user.id);
            state.studentMcqBankEntered = false;
            navigate(user.role === "admin" ? "admin" : "app-launcher");
            toast("Account created and approved. Welcome.");
            return;
          }
          removeStorageKey(STORAGE_KEYS.currentUserId);
          toast(autoApproved ? "Account created and approved. Please log in." : "Account created. Await admin approval before first login.");
          navigate("login");
          return;
        }

        const user = {
          id: makeId("u"),
          name,
          email,
          password,
          phone: normalizedPhone,
          role: "student",
          verified: true,
          isApproved: autoApproved,
          approvedAt: autoApproved ? nowISO() : null,
          approvedBy: autoApproved ? AUTO_APPROVAL_ACTOR : null,
          assignedCourses: selectedCourses,
          academicYear,
          academicSemester,
          createdAt: nowISO(),
        };

        users.push(user);
        save(STORAGE_KEYS.users, users, {
          userSyncScope: USER_RELATIONAL_SYNC_SCOPE_STUDENT_PROFILE,
        });
        if (autoApproved) {
          save(STORAGE_KEYS.currentUserId, user.id);
          state.studentMcqBankEntered = false;
          navigate("app-launcher");
          toast("Account created and approved. Welcome.");
        } else {
          removeStorageKey(STORAGE_KEYS.currentUserId);
          toast("Account created. Await admin approval before first login.");
          navigate("login");
        }
      } catch (error) {
        console.warn("Signup profile sync failed.", error?.message || error);
        toast("Could not sync your profile to the admin dashboard. Please try again.");
      } finally {
        lockAuthForm(form, false);
      }
    });
    return;
  }

  const form = document.getElementById("forgot-form");
  form?.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (form.dataset.submitting === "1") {
      return;
    }
    lockAuthForm(form, true, "Sending...");
    const data = new FormData(form);
    const email = String(data.get("email") || "").trim().toLowerCase();
    const authClient = getSupabaseAuthClient();
    try {
      if (authClient) {
        const redirectTo = getAuthRedirectToUrl();
        const { error } = await queueSupabaseAuthRequest(authClient, () => authClient.auth.resetPasswordForEmail(email, { redirectTo }));
        if (error) {
          toast(error.message || "Could not send reset email.");
          return;
        }
        toast("Password reset email sent.");
        navigate("login");
        return;
      }

      toast("Supabase auth is not configured. Password reset email is unavailable.");
    } finally {
      lockAuthForm(form, false);
    }
  });
}

function renderPasswordReset() {
  const hasRecoverySession = isPasswordRecoveryPendingState();
  if (!hasRecoverySession) {
    return `
      <section class="panel" style="max-width: 560px; margin-inline: auto;">
        <h2 class="title">Reset Password</h2>
        <p class="subtle">Your password reset session is not active. Request a new reset link and try again.</p>
        <div class="auth-inline">
          <button class="btn" data-nav="forgot" type="button">Request reset link</button>
          <button class="btn ghost" data-nav="login" type="button">Back to login</button>
        </div>
      </section>
    `;
  }

  return `
    <section class="panel" style="max-width: 560px; margin-inline: auto;">
      <h2 class="title">Set New Password</h2>
      <p class="subtle">Enter your new password to complete account recovery.</p>
      <form id="reset-password-form" class="auth-form" style="margin-top: 1rem;" method="post" autocomplete="on">
        <label>New password <input type="password" name="password" minlength="6" autocomplete="new-password" required /></label>
        <label>Confirm new password <input type="password" name="confirmPassword" minlength="6" autocomplete="new-password" required /></label>
        <button class="btn" type="submit">Update password</button>
      </form>
      <div class="auth-inline">
        <button class="btn ghost" data-nav="login" type="button">Cancel</button>
      </div>
    </section>
  `;
}

function wirePasswordReset() {
  const form = document.getElementById("reset-password-form");
  if (!form) {
    return;
  }

  const lockForm = (isSubmitting) => {
    form.dataset.submitting = isSubmitting ? "1" : "0";
    const submit = form.querySelector('button[type="submit"]');
    if (!submit) {
      return;
    }
    if (!submit.dataset.baseLabel) {
      submit.dataset.baseLabel = submit.textContent || "Update password";
    }
    submit.disabled = isSubmitting;
    submit.textContent = isSubmitting ? "Updating..." : submit.dataset.baseLabel;
  };

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (form.dataset.submitting === "1") {
      return;
    }
    if (!isPasswordRecoveryPendingState()) {
      toast("Reset session expired. Request a new reset link.");
      navigate("forgot");
      return;
    }

    const data = new FormData(form);
    const password = String(data.get("password") || "");
    const confirmPassword = String(data.get("confirmPassword") || "");
    if (!password || password.length < 6) {
      toast("Password must be at least 6 characters.");
      return;
    }
    if (password !== confirmPassword) {
      toast("Password and confirm password must match.");
      return;
    }

    const authClient = getSupabaseAuthClient();
    if (!authClient) {
      toast("Supabase auth is not configured. Password reset is unavailable.");
      return;
    }

    lockForm(true);
    try {
      const { data: sessionData } = await runSupabaseAuthRequestWithTimeout(
        authClient,
        () => authClient.auth.getSession().catch(() => ({ data: { session: null } })),
        SUPABASE_SESSION_TIMEOUT_MS,
        "Supabase session check timed out.",
      );
      if (!sessionData?.session?.user) {
        setPasswordRecoveryPendingState(false);
        toast("Reset session expired. Request a new reset link.");
        navigate("forgot");
        return;
      }
      const { error } = await queueSupabaseAuthRequest(authClient, () => authClient.auth.updateUser({ password }));
      if (error) {
        toast(error.message || "Could not update password.");
        return;
      }
      setPasswordRecoveryPendingState(false);
      removeStorageKey(STORAGE_KEYS.currentUserId);
      await queueSupabaseAuthRequest(authClient, () => authClient.auth.signOut()).catch(() => { });
      toast("Password updated. Log in with your new password.");
      navigate("login");
    } finally {
      lockForm(false);
    }
  });
}

function renderCompleteProfile() {
  const user = getCurrentUser();
  const onboardingDraft = loadStudentOnboardingDraft(user, "complete-profile");
  const shouldForceEmptyEnrollment = isGoogleOnboardingRequired(user);
  const draftYear = normalizeAcademicYearOrNull(onboardingDraft?.academicYear);
  const draftSemester = normalizeAcademicSemesterOrNull(onboardingDraft?.academicSemester);
  const year = draftYear !== null
    ? draftYear
    : (shouldForceEmptyEnrollment ? null : normalizeAcademicYearOrNull(user?.academicYear));
  const semester = draftSemester !== null
    ? draftSemester
    : (shouldForceEmptyEnrollment ? null : normalizeAcademicSemesterOrNull(user?.academicSemester));
  const courses = year !== null && semester !== null ? getCurriculumCourses(year, semester) : [];
  const hasDraftSelectedCourses = Array.isArray(onboardingDraft?.selectedCourses);
  const draftSelectedCourses = hasDraftSelectedCourses
    ? sanitizeCourseAssignments(onboardingDraft.selectedCourses).filter((course) => courses.includes(course))
    : [];
  const existingSelectedCourses = sanitizeCourseAssignments(user?.assignedCourses || []).filter((course) => courses.includes(course));
  const initiallyCheckedCourses = hasDraftSelectedCourses
    ? draftSelectedCourses
    : (existingSelectedCourses.length ? existingSelectedCourses : courses);
  const defaultPhone = typeof onboardingDraft?.phone === "string"
    ? onboardingDraft.phone
    : String(user?.phone || "");

  return `
    <section class="panel" style="max-width: 680px; margin-inline: auto;">
      <h2 class="title">Complete Your Account</h2>
      <p class="subtle">Add your phone number, choose your year and semester, and pick one or more courses first. Your account stays pending until an admin approves it. Use 01XXXXXXXXX, +20XXXXXXXXXX, 0020XXXXXXXXXX, or +countrycode.</p>
      <form id="complete-profile-form" class="auth-form" style="margin-top: 1rem;" method="post" autocomplete="on">
        <label>Phone number <input type="tel" name="phone" value="${escapeHtml(defaultPhone)}" autocomplete="tel" inputmode="tel" placeholder="+20 10 0000 0000" required minlength="8" maxlength="20" /></label>
        <div class="form-row">
          <label>Year
            <select name="academicYear" id="complete-profile-year" required aria-required="true">
              <option value="" ${year === null ? "selected" : ""}>Select year</option>
              ${[1, 2, 3, 4, 5]
      .map((entry) => `<option value="${entry}" ${year === entry ? "selected" : ""}>Year ${entry}</option>`)
      .join("")}
            </select>
          </label>
          <label>Semester
            <select name="academicSemester" id="complete-profile-semester" required aria-required="true">
              <option value="" ${semester === null ? "selected" : ""}>Select semester</option>
              <option value="1" ${semester === 1 ? "selected" : ""}>Semester 1</option>
              <option value="2" ${semester === 2 ? "selected" : ""}>Semester 2</option>
            </select>
          </label>
        </div>
        <div class="signup-course-field">
          <p class="signup-course-label">MCQ Subjects for selected year/semester</p>
          <div id="complete-profile-course-options" class="signup-course-grid">
            ${courses
              .map(
                (course) => `
                  <label class="admin-course-check">
                    <input type="checkbox" name="completeProfileCourses" value="${escapeHtml(course)}" ${initiallyCheckedCourses.includes(course) ? "checked" : ""} />
                    <span>${escapeHtml(course)}</span>
                  </label>
                `,
              )
              .join("")}
          </div>
          <small id="complete-profile-course-help" class="subtle">${escapeHtml(courses.length ? `${courses.length} course(s) available for this year/semester. Choose one or more.` : "Choose year and semester first.")}</small>
        </div>
        <div class="stack">
          <button class="btn ghost" type="button" id="complete-profile-select-all-courses">Select all</button>
          <button class="btn ghost" type="button" id="complete-profile-clear-courses">Clear</button>
        </div>
        <div class="stack">
          <button class="btn" type="submit">Submit Profile</button>
          <button class="btn ghost" type="button" data-action="logout">Cancel</button>
        </div>
      </form>
    </section>
  `;
}

function wireCompleteProfile() {
  const form = document.getElementById("complete-profile-form");
  if (!form) {
    return;
  }

  const currentUser = getCurrentUser();
  const phoneInput = form.querySelector("input[name='phone']");
  const yearSelect = document.getElementById("complete-profile-year");
  const semesterSelect = document.getElementById("complete-profile-semester");
  const courseOptionsEl = document.getElementById("complete-profile-course-options");
  const courseHelpEl = document.getElementById("complete-profile-course-help");
  const selectAllCoursesBtn = document.getElementById("complete-profile-select-all-courses");
  const clearCoursesBtn = document.getElementById("complete-profile-clear-courses");
  const submitButton = form.querySelector('button[type="submit"]');
  const setSubmitting = (submitting) => {
    form.dataset.submitting = submitting ? "1" : "0";
    if (!submitButton) {
      return;
    }
    if (!submitButton.dataset.baseLabel) {
      submitButton.dataset.baseLabel = submitButton.textContent || "";
    }
    submitButton.disabled = submitting;
    submitButton.textContent = submitting ? "Submitting..." : submitButton.dataset.baseLabel;
  };

  const getSelectedCompleteProfileCourses = () =>
    Array.from(form.querySelectorAll("input[name='completeProfileCourses']:checked")).map((input) => input.value);

  const persistCompleteProfileDraft = () => {
    saveStudentOnboardingDraft({
      phone: phoneInput?.value || "",
      academicYear: yearSelect?.value,
      academicSemester: semesterSelect?.value,
      selectedCourses: getSelectedCompleteProfileCourses(),
    }, currentUser, "complete-profile");
  };

  const renderCompleteProfileCourseOptions = (preferred = [], options = {}) => {
    const year = normalizeAcademicYearOrNull(yearSelect?.value);
    const semester = normalizeAcademicSemesterOrNull(semesterSelect?.value);
    const courses = year !== null && semester !== null ? getCurriculumCourses(year, semester) : [];
    if (courseOptionsEl) {
      if (year === null || semester === null) {
        courseOptionsEl.innerHTML = "";
      } else {
        const selectedSet = new Set(preferred.filter((course) => courses.includes(course)));
        const selectAllByDefault = !options.explicitSelection && selectedSet.size === 0;
        courseOptionsEl.innerHTML = courses
          .map(
            (course) => `
              <label class="admin-course-check">
                <input type="checkbox" name="completeProfileCourses" value="${escapeHtml(course)}" ${selectAllByDefault || selectedSet.has(course) ? "checked" : ""} />
                <span>${escapeHtml(course)}</span>
              </label>
            `,
          )
          .join("");
      }
    }
    if (courseHelpEl) {
      courseHelpEl.textContent = year !== null && semester !== null
        ? (courses.length ? `${courses.length} course(s) available for this year/semester. Choose one or more.` : "No courses available for this selection.")
        : "Choose year and semester first.";
    }
    persistCompleteProfileDraft();
  };

  phoneInput?.addEventListener("input", persistCompleteProfileDraft);
  yearSelect?.addEventListener("change", () => {
    const preferredCourses = getSelectedCompleteProfileCourses();
    const hasExplicitSelection = Boolean(courseOptionsEl?.querySelector("input[name='completeProfileCourses']"));
    renderCompleteProfileCourseOptions(preferredCourses, { explicitSelection: hasExplicitSelection });
  });
  semesterSelect?.addEventListener("change", () => {
    const preferredCourses = getSelectedCompleteProfileCourses();
    const hasExplicitSelection = Boolean(courseOptionsEl?.querySelector("input[name='completeProfileCourses']"));
    renderCompleteProfileCourseOptions(preferredCourses, { explicitSelection: hasExplicitSelection });
  });
  courseOptionsEl?.addEventListener("change", persistCompleteProfileDraft);

  selectAllCoursesBtn?.addEventListener("click", () => {
    courseOptionsEl?.querySelectorAll("input[name='completeProfileCourses']").forEach((input) => {
      input.checked = true;
    });
    persistCompleteProfileDraft();
  });

  clearCoursesBtn?.addEventListener("click", () => {
    courseOptionsEl?.querySelectorAll("input[name='completeProfileCourses']").forEach((input) => {
      input.checked = false;
    });
    persistCompleteProfileDraft();
  });

  const savedDraft = loadStudentOnboardingDraft(currentUser, "complete-profile");
  const preferredCourses = Array.isArray(savedDraft?.selectedCourses)
    ? sanitizeCourseAssignments(savedDraft.selectedCourses)
    : sanitizeCourseAssignments(currentUser?.assignedCourses || []);
  renderCompleteProfileCourseOptions(preferredCourses, {
    explicitSelection: Array.isArray(savedDraft?.selectedCourses),
  });

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (form.dataset.submitting === "1") {
      return;
    }

    const current = getCurrentUser();
    if (!current) {
      navigate("login");
      return;
    }

    const data = new FormData(form);
    const phone = String(data.get("phone") || "").trim();
    const phoneValidation = validateAndNormalizePhoneNumber(phone);
    const normalizedPhone = phoneValidation.number;
    const academicYear = normalizeAcademicYearOrNull(data.get("academicYear"));
    const academicSemester = normalizeAcademicSemesterOrNull(data.get("academicSemester"));
    if (academicYear === null || academicSemester === null) {
      toast("You need to choose the year and semester.");
      return;
    }
    const availableCourses = getCurriculumCourses(academicYear, academicSemester);
    const assignedCourses = getSelectedCompleteProfileCourses().filter((course) => availableCourses.includes(course));

    if (!phoneValidation.ok) {
      toast(phoneValidation.message || "Please enter a valid phone number.");
      return;
    }
    if (!availableCourses.length) {
      toast("No courses are available for this year and semester.");
      return;
    }
    if (!assignedCourses.length) {
      toast("Choose at least one course for your enrollment.");
      return;
    }

    const users = getUsers();
    const idx = users.findIndex((entry) => entry.id === current.id);
    if (idx === -1) {
      toast("Account not found. Please log in again.");
      navigate("login");
      return;
    }

    setSubmitting(true);
    try {
      const autoApproved = shouldAutoApproveStudentAccess({
        role: "student",
        phone: normalizedPhone,
        academicYear,
        academicSemester,
        assignedCourses,
      });
      const previousUser = {
        ...users[idx],
        assignedCourses: [...sanitizeCourseAssignments(users[idx].assignedCourses || [])],
      };
      const wasApproved = previousUser.isApproved === true;
      let nextApproved = wasApproved || autoApproved;
      users[idx].phone = normalizedPhone;
      users[idx].role = "student";
      users[idx].academicYear = academicYear;
      users[idx].academicSemester = academicSemester;
      users[idx].assignedCourses = assignedCourses;
      users[idx].isApproved = nextApproved;
      users[idx].approvedAt = nextApproved ? users[idx].approvedAt || nowISO() : null;
      users[idx].approvedBy = nextApproved ? users[idx].approvedBy || AUTO_APPROVAL_ACTOR : null;
      users[idx].profileCompleted = true;
      users[idx].authProvider = normalizeAuthProvider(users[idx].authProvider || getAuthProviderFromUser(current));

      archiveSessionsForChangedUserEnrollments([previousUser], [users[idx]], {
        reason: "enrollment_change",
        includeCompleted: true,
      });
      save(STORAGE_KEYS.users, users, {
        userSyncScope: USER_RELATIONAL_SYNC_SCOPE_STUDENT_PROFILE,
      });
      save(STORAGE_KEYS.currentUserId, users[idx].id);
      await syncUsersBackupState(users).catch(() => { });
      const metadataAuthClient = getSupabaseAuthClient();
      if (metadataAuthClient) {
        await syncCurrentAuthUserEnrollmentMetadata(metadataAuthClient, users[idx]).catch((metadataError) => {
          console.warn("Could not update completed profile enrollment metadata.", metadataError?.message || metadataError);
        });
      }
      await ensureRelationalSyncReady().catch(() => { });
      if (nextApproved && !wasApproved) {
        const profileId = getUserProfileId(users[idx]);
        if (isUuidValue(profileId)) {
          const approvalResult = await updateRelationalProfileApproval([profileId], true).catch(() => ({ ok: false }));
          if (!approvalResult.ok) {
            nextApproved = false;
            const updatedUsers = getUsers();
            const updatedIdx = updatedUsers.findIndex((entry) => entry.email.toLowerCase() === users[idx].email);
            if (updatedIdx >= 0) {
              updatedUsers[updatedIdx].isApproved = false;
              updatedUsers[updatedIdx].approvedAt = null;
              updatedUsers[updatedIdx].approvedBy = null;
              saveLocalOnly(STORAGE_KEYS.users, updatedUsers);
            }
          }
        }
      }
      await flushPendingSyncNow();
      clearStudentOnboardingDraft(users[idx], "complete-profile");

      if (nextApproved) {
        save(STORAGE_KEYS.currentUserId, users[idx].id);
        toast(wasApproved ? "Profile updated." : "Profile submitted and approved. Welcome.");
        navigate("app-launcher");
      } else {
        const authClient = getSupabaseAuthClient();
        if (authClient) {
          await queueSupabaseAuthRequest(authClient, () => authClient.auth.signOut()).catch(() => { });
        }
        removeStorageKey(STORAGE_KEYS.currentUserId);
        toast("Profile submitted. Your account is waiting admin approval.");
        navigate("login");
      }
    } catch (error) {
      console.warn("Profile completion sync failed.", error?.message || error);
      toast("Could not sync your profile to the admin dashboard. Please try again.");
    } finally {
      setSubmitting(false);
    }
  });
}

function renderNotifications() {
  const user = getCurrentUser();
  if (!user || user.role !== "student") {
    return `
      <section class="panel">
        <h2 class="title">Notifications unavailable</h2>
        <p class="subtle">Student role required for this page.</p>
      </section>
    `;
  }

  const notifications = getVisibleNotificationsForUser(user);
  const unreadCount = notifications.filter((notification) => !isNotificationReadByUser(notification, user)).length;
  const listMarkup = notifications
    .map((notification) => {
      const isRead = isNotificationReadByUser(notification, user);
      const bodyHtml = escapeHtml(notification.body || "").replaceAll("\n", "<br />");
      const timeAgo = getNotificationTimeAgo(notification.createdAt);
      const destinationRoute = normalizeNotificationDestinationRoute(notification.targetRoute);
      const notificationContent = `
        <div class="notification-card-head">
          <div class="notification-card-title-group">
            <h3 class="notification-card-title">${escapeHtml(notification.title || "Notification")}</h3>
            ${timeAgo ? `<span class="notification-card-time">${escapeHtml(timeAgo)}</span>` : ""}
          </div>
          <span class="badge ${isRead ? "neutral" : "good"}">${isRead ? "Read" : "New"}</span>
        </div>
        <p class="notification-card-body">${bodyHtml || "-"}</p>
        ${destinationRoute
    ? `<span class="notification-card-destination">Open ${escapeHtml(getNotificationDestinationLabelForRecord(notification))} <span aria-hidden="true">→</span></span>`
    : ""
  }
      `;
      return `
        <article class="card notification-card ${isRead ? "is-read" : "is-unread"}" data-notification-id="${escapeHtml(notification.id)}">
          ${destinationRoute
    ? `<button class="notification-card-open" type="button" data-action="notification-open" data-notification-id="${escapeHtml(notification.id)}" aria-label="Open ${escapeHtml(getNotificationDestinationLabelForRecord(notification))}">${notificationContent}</button>`
    : `<div class="notification-card-content">${notificationContent}</div>`
  }
          ${isRead
          ? ""
          : `<div class="notification-card-actions">
                  <button class="btn ghost admin-btn-sm notification-card-read-btn" type="button" data-action="notification-mark-read" data-notification-id="${escapeHtml(notification.id)}">
                    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false" style="width: 12px; height: 12px; margin-right: 4px; display: inline-block; vertical-align: middle;">
                      <path d="M3 8.5L6.2 11.7 13 4.9" />
                    </svg>
                    Mark as read
                  </button>
                </div>`
        }
        </article>
      `;
    })
    .join("");

  return `
    <section class="panel notifications-page-panel" id="student-notifications-section">
      <button class="btn ghost notifications-back-btn" type="button" data-nav="dashboard">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false" style="width: 14px; height: 14px; margin-right: 4px; vertical-align: middle;">
          <line x1="19" y1="12" x2="5" y2="12"></line>
          <polyline points="12 19 5 12 12 5"></polyline>
        </svg>
        <span>Back</span>
      </button>
      <div class="notifications-page-head">
        <div>
          <p class="kicker">Updates</p>
          <h2 class="title">Notifications</h2>
          <p class="subtle">Messages from admin will appear here.</p>
        </div>
        <div class="notifications-page-actions">
          <p class="subtle notifications-unread-count">Unread: <b>${unreadCount}</b></p>
          <button class="btn ghost notifications-mark-all-btn" type="button" data-action="notifications-mark-all-read" ${unreadCount ? "" : "disabled"}>
            Mark all read
          </button>
        </div>
      </div>
      <p class="subtle notifications-sync-note">Live updates are enabled. ${escapeHtml(getStudentDataSyncStatusText())}</p>
      <div class="notifications-list">
        ${listMarkup || `<article class="card"><p class="subtle" style="margin:0;">No notifications yet.</p></article>`}
      </div>
    </section>
  `;
}

async function markNotificationsReadForUser(user, notificationIds) {
  const currentUser = user || getCurrentUser();
  if (!currentUser || currentUser.role !== "student") {
    return { changed: false, syncWarning: "", syncDeferred: false };
  }
  const result = markNotificationsReadLocallyForUser(currentUser, notificationIds);
  if (!result.changed) {
    return { changed: false, syncWarning: "", syncDeferred: false };
  }
  if (!result.syncedDbIds.length) {
    return { changed: true, syncWarning: "", syncDeferred: false };
  }
  queueNotificationReadSync(currentUser, result.syncedDbIds);
  const flushResult = await flushPendingNotificationReadSync({ user: currentUser });
  if (!flushResult.ok) {
    return {
      changed: true,
      syncWarning: flushResult.message || "Notification read sync is queued.",
      syncDeferred: true,
    };
  }
  return { changed: true, syncWarning: "", syncDeferred: false };
}

function wireNotifications() {
  const user = getCurrentUser();
  if (!user || user.role !== "student") {
    return;
  }

  const markAsRead = async (notificationIds) => {
    const result = await markNotificationsReadForUser(user, notificationIds);
    if (result.syncDeferred) {
      toast("Marked as read locally. Cloud sync is queued and will retry automatically.");
    } else if (result.syncWarning) {
      toast(`Marked as read locally, but cloud sync failed: ${result.syncWarning}`);
    }
    if (!result.changed) {
      return false;
    }
    return true;
  };

  appEl.querySelectorAll("[data-action='notification-mark-read']").forEach((button) => {
    button.addEventListener("click", async () => {
      const notificationId = String(button.getAttribute("data-notification-id") || "").trim();
      if (!notificationId) {
        return;
      }
      const changed = await markAsRead([notificationId]);
      if (changed) {
        state.skipNextRouteAnimation = true;
        render();
      }
    });
  });

  appEl.querySelector("[data-action='notifications-mark-all-read']")?.addEventListener("click", async () => {
    const unreadNotifications = getVisibleNotificationsForUser(user)
      .filter((notification) => !isNotificationReadByUser(notification, user))
      .map((notification) => notification.id);
    if (!unreadNotifications.length) {
      return;
    }
    const changed = await markAsRead(unreadNotifications);
    if (changed) {
      toast("All notifications marked as read.");
      state.skipNextRouteAnimation = true;
      render();
    }
  });

}

function studentSvgIcon(name) {
  const lucideIcons = {
    accuracy: "target",
    time: "timer-reset",
    solved: "list-checks",
    bank: "database-zap",
    create: "plus-circle",
    review: "rotate-ccw",
    chart: "chart-no-axes-combined",
    flag: "flag",
    streak: "flame",
  };
  const lucideName = lucideIcons[name];
  if (lucideName && window.lucide?.createIcons) {
    return `<i class="student-lucide-icon" data-lucide="${lucideName}" aria-hidden="true"></i>`;
  }
  const paths = {
    accuracy: '<circle cx="12" cy="12" r="9"/><path d="M8.5 12.5l2.5 2.5 4.5-5"/>',
    time: '<circle cx="12" cy="12" r="9"/><path d="M12 7.5V12l3 1.8"/>',
    solved: '<path d="M4 12.5l2.5 2.5L11 10"/><path d="M14 8h6"/><path d="M14 12h6"/><path d="M14 16h6"/>',
    bank: '<path d="M4 7c0-1.7 3.6-3 8-3s8 1.3 8 3-3.6 3-8 3-8-1.3-8-3Z"/><path d="M4 7v10c0 1.7 3.6 3 8 3s8-1.3 8-3V7"/><path d="M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3"/>',
    create: '<path d="M12 5v14"/><path d="M5 12h14"/>',
    review: '<path d="M21 12a9 9 0 1 1-3-6.7"/><path d="M21 4v5h-5"/>',
    chart: '<path d="M4 19V5"/><path d="M4 19h16"/><path d="M8 16v-4"/><path d="M12 16V8"/><path d="M16 16v-6"/>',
    flag: '<path d="M5 21V4"/><path d="M5 4h11l-2 3 2 3H5"/>',
    streak: '<path d="M12 3s5 4 5 9a5 5 0 0 1-10 0c0-2 1-3 1-3s.5 1.5 2 2c0-3 2-5 2-8Z"/>',
  };
  const inner = paths[name] || paths.chart;
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${inner}</svg>`;
}

function renderLucideIcons() {
  if (!window.lucide?.createIcons) {
    return;
  }
  try {
    window.lucide.createIcons({
      attrs: {
        "aria-hidden": "true",
        "stroke-width": "2",
      },
    });
  } catch (error) {
    console.warn("Lucide icon rendering failed.", error?.message || error);
  }
}

function renderStudentStatCard(icon, value, label, tone = "") {
  return `
    <article class="card student-stat${tone ? ` is-${tone}` : ""}">
      <span class="student-stat-icon">${studentSvgIcon(icon)}</span>
      <span class="student-stat-body">
        <b class="student-stat-value">${value}</b>
        <span class="student-stat-label">${escapeHtml(label)}</span>
      </span>
    </article>
  `;
}

function getStudentIncorrectQueueCount(userId) {
  const queue = load(STORAGE_KEYS.incorrectQueue, {})[userId];
  return Array.isArray(queue) ? queue.length : 0;
}

function renderDashboard() {
  const user = getCurrentUser();
  const availableCourses = getAvailableCoursesForUser(user);
  const contentReadiness = getStudentContentReadiness(user, { availableCourses });
  const dashboardSyncingContent = Boolean(contentReadiness.loading);
  if (contentReadiness.loading) {
    logStudentContentAccessDecision(user, {
      reason: "dashboard_rendering_during_content_sync",
      surface: "dashboard",
      availableCourses,
    });
  }
  if (contentReadiness.issue) {
    recordStudentAccessIssue(contentReadiness.issue, user, { surface: "dashboard" });
    return `
      <section class="panel">
        <h2 class="title">Course Access Needs Attention</h2>
        <p class="subtle">${escapeHtml(contentReadiness.issue.message)}</p>
        <div class="stack">
          <button class="btn ghost ${state.studentDataRefreshing ? "is-loading" : ""}" type="button" data-action="refresh-student-analytics" ${state.studentDataRefreshing ? "disabled" : ""}>
            ${renderStudentRefreshButtonContent()}
          </button>
          <button class="btn" data-nav="profile">View profile</button>
        </div>
      </section>
    `;
  }
  const questions = getPublishedQuestionsForUser(user);
  if (contentReadiness.error && !questions.length) {
    logStudentContentAccessDecision(user, {
      reason: "dashboard_question_query_error",
      surface: "dashboard",
      availableCourses,
      details: { message: contentReadiness.error },
    });
    return renderStudentContentErrorPanel("Question Bank Could Not Load", contentReadiness.error);
  }
  const analytics = getStudentAnalyticsSnapshot(user.id);
  const stats = analytics.stats;
  const solvedQuestionsCount = Number.isFinite(stats?.totalAnswered) ? stats.totalAnswered : 0;
  const incorrectQueueCount = getStudentIncorrectQueueCount(user.id);
  const syncStatusText = getStudentDataSyncStatusText();
  const questionBankStatValue = dashboardSyncingContent && !questions.length
    ? `<span class="inline-loader" aria-hidden="true"></span>`
    : questions.length;

  return `
    <section class="panel">
      <button class="btn ghost dashboard-back-to-apps" data-nav="app-launcher" style="margin-bottom: 0.5rem;">← Back to Apps</button>
      <p class="kicker">Welcome back</p>
      <div class="flex-between">
        <h2 class="title">Dr. ${escapeHtml(user.name)}'s Dashboard</h2>
        <div class="stack">
          <button class="btn" data-nav="create-test">Create a Test</button>
          <button class="btn ghost ${state.studentDataRefreshing ? "is-loading" : ""}" type="button" data-action="refresh-student-analytics" ${state.studentDataRefreshing ? "disabled" : ""}>
            ${renderStudentRefreshButtonContent()}
          </button>
        </div>
      </div>
      <p class="subtle">${escapeHtml(syncStatusText)}</p>
      <div class="student-stats-grid">
        ${renderStudentStatCard("accuracy", `${stats.accuracy}%`, "Overall accuracy", "brand")}
        ${renderStudentStatCard("time", `${stats.timePerQuestion}s`, "Avg time / question", "accent")}
        ${renderStudentStatCard("solved", solvedQuestionsCount, "Questions solved", "good")}
        ${renderStudentStatCard("bank", questionBankStatValue, dashboardSyncingContent && !questions.length ? "Syncing bank" : "Questions in bank")}
      </div>
    </section>

    <section class="panel dashboard-next">
      <div class="dash-next-grid">
        <article class="card dash-resume-card">
          <h3>Resume Practice</h3>
          ${renderResumeCard(user.id)}
        </article>
        <article class="card dash-coach-card">
          <h3>Study Coach</h3>
          ${renderDashboardCoach(analytics)}
        </article>
      </div>
      <div class="dash-quick-actions">
        <button class="dash-action" type="button" data-nav="create-test">
          <span class="dash-action-icon is-brand">${studentSvgIcon("create")}</span>
          <span class="dash-action-copy"><b>Create a test</b><small>Build a custom block by course &amp; topic</small></span>
        </button>
        <button class="dash-action" type="button" data-action="dash-review-incorrect" ${incorrectQueueCount ? "" : "disabled"}>
          <span class="dash-action-icon is-accent">${studentSvgIcon("review")}</span>
          <span class="dash-action-copy"><b>Review incorrect</b><small>${incorrectQueueCount ? `${incorrectQueueCount} saved to retry` : "Nothing saved yet"}</small></span>
        </button>
        <button class="dash-action" type="button" data-nav="analytics">
          <span class="dash-action-icon is-good">${studentSvgIcon("chart")}</span>
          <span class="dash-action-copy"><b>Open analytics</b><small>See trends &amp; what to study next</small></span>
        </button>
      </div>
    </section>

    ${renderPreviousTestsSection(user)}
  `;
}

function renderResumeCard(userId) {
  const inProgress = getNormalizedActiveSessionForDisplay(userId, state.sessionId);
  if (!inProgress) {
    return `<p class="subtle">No active block.</p>`;
  }

  const totalQuestions = Array.isArray(inProgress.questionIds) ? inProgress.questionIds.length : 0;
  if (!totalQuestions) {
    return `<p class="subtle">No active block.</p>`;
  }

  const currentQuestion = Math.max(1, Math.min(totalQuestions, Number(inProgress.currentIndex || 0) + 1));
  const progress = `${currentQuestion}/${totalQuestions}`;
  return `
    <p style="margin-bottom: 0.35rem;"><b>${escapeHtml(getSessionDisplayName(inProgress))}</b></p>
    <p class="subtle" style="margin-top: 0;">${escapeHtml(getSessionDisplayId(inProgress))} • ${escapeHtml(formatSessionModeLabel(inProgress.mode))} • Progress: <b>${progress}</b></p>
    <button class="btn" data-nav="session">Resume session</button>
  `;
}

function getStudentDataSyncStatusText() {
  const cloudModel = getCloudSyncStatusModel(getCurrentUser());
  if (cloudModel && ["offline", "pending", "syncing", "warning"].includes(String(cloudModel.tone || ""))) {
    return `Cloud status: ${cloudModel.label}.`;
  }
  if (state.studentDataRefreshing) {
    return "Syncing latest results...";
  }
  if (!state.studentDataLastSyncAt) {
    return "Cloud sync is idle. Local analytics are shown.";
  }
  const syncedAt = new Date(state.studentDataLastSyncAt).toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
  });
  return `Last synced at ${syncedAt}.`;
}

function renderStudentRefreshButtonContent() {
  return state.studentDataRefreshing
    ? `<span class="inline-loader" aria-hidden="true"></span><span>Getting updates...</span>`
    : "Get Updates";
}

function setStudentRefreshButtonBusy(button, busy) {
  if (!button) {
    return;
  }
  button.disabled = busy;
  button.classList.toggle("is-loading", busy);
  button.innerHTML = busy
    ? `<span class="inline-loader" aria-hidden="true"></span><span>Getting updates...</span>`
    : "Get Updates";
}

function wireStudentRefreshButtons() {
  appEl.querySelectorAll("[data-action='refresh-student-analytics']").forEach((refreshButton) => {
    refreshButton.addEventListener("click", async () => {
      if (state.studentDataRefreshing || refreshButton.disabled) {
        return;
      }
      setStudentRefreshButtonBusy(refreshButton, true);
      try {
        await refreshStudentAnalyticsNow();
      } finally {
        if (!state.studentDataRefreshing && appEl.contains(refreshButton)) {
          setStudentRefreshButtonBusy(refreshButton, false);
        }
      }
    });
  });
}

function renderDashboardCoach(snapshot) {
  const insights = snapshot?.insights;
  if (!insights) {
    return `<p class="subtle">Complete more blocks to get personalized recommendations.</p>`;
  }

  return `
    <p><b>${escapeHtml(insights.summary)}</b></p>
    <p class="subtle">${escapeHtml(insights.trendMessage)}</p>
    <p class="subtle">${escapeHtml(insights.paceMessage)}</p>
    <p class="subtle"><b>Next step:</b> ${escapeHtml(insights.nextBlockRecommendation)}</p>
  `;
}

function getPreviousTestFilters() {
  const current = state.previousTestFilters && typeof state.previousTestFilters === "object"
    ? state.previousTestFilters
    : {};
  const allowedSorts = new Set(["newest", "oldest", "best", "most-wrong"]);
  const sort = allowedSorts.has(String(current.sort || "")) ? String(current.sort) : "newest";
  state.previousTestFilters = {
    dateKey: String(current.dateKey || "").trim(),
    course: String(current.course || "").trim(),
    topic: String(current.topic || "").trim(),
    sort,
  };
  return state.previousTestFilters;
}

function getPreviousTestCompletedDate(session) {
  const candidates = [session?.completedAt, session?.updatedAt, session?.createdAt];
  for (const value of candidates) {
    const date = new Date(value || "");
    if (!Number.isNaN(date.getTime())) {
      return date;
    }
  }
  return new Date(0);
}

function getPreviousTestDateKey(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    return "";
  }
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function formatPreviousTestDateLabel(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    return "Unknown date";
  }
  return date.toLocaleDateString(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

function formatPreviousTestTimeLabel(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) {
    return "";
  }
  return date.toLocaleTimeString(undefined, {
    hour: "numeric",
    minute: "2-digit",
  });
}

function getSessionTopicList(session, questionStore = null, questionMetaById = null) {
  if (!session || typeof session !== "object") {
    return [];
  }
  const store = questionStore || getQuestionStore();
  const map = questionMetaById instanceof Map ? questionMetaById : getAnalyticsQuestionMetaById();
  const topics = [];
  const seenTopics = new Set();
  (Array.isArray(session.questionIds) ? session.questionIds : []).forEach((qid) => {
    const resolvedQuestionId = resolveSessionQuestionId(qid, store);
    const question = getQuestionForSession(session, qid, store)
      || map.get(qid)?.question
      || map.get(resolvedQuestionId)?.question;
    const fallbackMeta = map.get(qid) || map.get(resolvedQuestionId);
    const meta = question ? getQbankCourseTopicMeta(question) : fallbackMeta;
    if (!meta) {
      return;
    }
    const topic = String(meta.topic || question?.qbankTopic || question?.topic || "").trim();
    if (!topic || seenTopics.has(topic)) {
      return;
    }
    seenTopics.add(topic);
    topics.push(topic);
  });
  return topics;
}

function renderPreviousTestMiniChips(values, fallback = "Unsorted") {
  const list = Array.isArray(values) ? values.filter(Boolean) : [];
  if (!list.length) {
    return `<span class="previous-test-chip is-muted">${escapeHtml(fallback)}</span>`;
  }
  const visible = list.slice(0, 2);
  const overflow = list.length - visible.length;
  return `
    ${visible.map((value) => `<span class="previous-test-chip">${escapeHtml(value)}</span>`).join("")}
    ${overflow ? `<span class="previous-test-chip is-muted">+${overflow}</span>` : ""}
  `;
}

function buildPreviousTestRecord(session, questionStore, questionMetaById = null) {
  normalizeSession(session, { questionStore });
  const completedDate = getPreviousTestCompletedDate(session);
  const summary = getSessionPerformanceSummary(session, questionStore.byId);
  const courses = getSessionCourseList(session, questionMetaById).filter(Boolean);
  const topics = getSessionTopicList(session, questionStore, questionMetaById);
  const questionCount = Math.max(
    summary.total,
    Number(session?.questionCount || 0) || 0,
    Array.isArray(session?.questionIds) ? session.questionIds.length : 0,
  );
  return {
    session,
    summary,
    completedDate,
    completedMs: completedDate.getTime(),
    dateKey: getPreviousTestDateKey(completedDate),
    dateLabel: formatPreviousTestDateLabel(completedDate),
    timeLabel: formatPreviousTestTimeLabel(completedDate),
    courses,
    topics,
    questionCount,
    sourceLabel: getCreateTestSourceLabel(session?.source || "all"),
    modeLabel: formatSessionModeLabel(session?.mode),
    name: getSessionDisplayName(session),
    displayId: getSessionDisplayId(session),
  };
}

function getCountMap(values) {
  const map = new Map();
  (Array.isArray(values) ? values : []).forEach((value) => {
    const key = String(value || "").trim();
    if (!key) {
      return;
    }
    map.set(key, (map.get(key) || 0) + 1);
  });
  return map;
}

function renderPreviousTestOptions(values, selectedValue, placeholder, countMap = null) {
  const options = [`<option value="">${escapeHtml(placeholder)}</option>`];
  values.forEach((value) => {
    const count = countMap instanceof Map ? Number(countMap.get(value) || 0) : 0;
    const label = count ? `${value} (${count})` : value;
    options.push(`<option value="${escapeHtml(value)}" ${value === selectedValue ? "selected" : ""}>${escapeHtml(label)}</option>`);
  });
  return options.join("");
}

function applyPreviousTestFilters(records, filters) {
  const filtered = records.filter((record) => {
    if (filters.dateKey && record.dateKey !== filters.dateKey) {
      return false;
    }
    if (filters.course && !record.courses.includes(filters.course)) {
      return false;
    }
    if (filters.topic && !record.topics.includes(filters.topic)) {
      return false;
    }
    return true;
  });

  return filtered.sort((a, b) => {
    if (filters.sort === "oldest") {
      return a.completedMs - b.completedMs;
    }
    if (filters.sort === "best") {
      return b.summary.accuracy - a.summary.accuracy || b.completedMs - a.completedMs;
    }
    if (filters.sort === "most-wrong") {
      return b.summary.wrongCount - a.summary.wrongCount || b.completedMs - a.completedMs;
    }
    return b.completedMs - a.completedMs;
  });
}

function renderPreviousTestsSection(userOrId) {
  const user = userOrId && typeof userOrId === "object" ? userOrId : null;
  const userId = String((user?.id) || userOrId || "").trim();
  const questionMetaById = getAnalyticsQuestionMetaById();
  const completed = getReviewableCompletedSessionsForUser(user || userId, {
    userOverride: user,
    questionMetaById,
    fallbackToAllTerms: true,
  });
  if (!completed.length) {
    return `
      <section class="panel">
        <h3 style="margin-top: 0;">Previous Tests</h3>
        <p class="subtle">Previous tests are kept for ${PREVIOUS_TEST_RETENTION_DAYS} days. Older test history is automatically deleted.</p>
        <p class="subtle">No completed tests yet for this year/semester.</p>
      </section>
    `;
  }

  const questionStore = getQuestionStore();
  const completedForAnalysis = completed.slice(0, PREVIOUS_TEST_ANALYSIS_LIMIT);
  const hiddenCompletedAnalysisCount = Math.max(0, completed.length - completedForAnalysis.length);
  const records = completedForAnalysis.map((session) => buildPreviousTestRecord(session, questionStore, questionMetaById));
  const filters = getPreviousTestFilters();
  const dateCountMap = getCountMap(records.map((record) => record.dateKey));
  const courseCountMap = getCountMap(records.flatMap((record) => record.courses));
  const dateOptions = [...dateCountMap.keys()]
    .sort((a, b) => b.localeCompare(a))
    .map((dateKey) => ({
      key: dateKey,
      label: records.find((record) => record.dateKey === dateKey)?.dateLabel || dateKey,
      count: dateCountMap.get(dateKey) || 0,
    }));
  const courseOptions = [...courseCountMap.keys()].sort((a, b) => a.localeCompare(b));

  if (filters.dateKey && !dateCountMap.has(filters.dateKey)) {
    filters.dateKey = "";
  }
  if (filters.course && !courseCountMap.has(filters.course)) {
    filters.course = "";
    filters.topic = "";
  }

  const topicSourceRecords = filters.course
    ? records.filter((record) => record.courses.includes(filters.course))
    : records;
  const topicCountMap = getCountMap(topicSourceRecords.flatMap((record) => record.topics));
  const topicOptions = [...topicCountMap.keys()].sort((a, b) => a.localeCompare(b));

  if (filters.topic && !topicCountMap.has(filters.topic)) {
    filters.topic = "";
  }

  const filteredRecords = applyPreviousTestFilters(records, filters);
  const filteredQuestionCount = filteredRecords.reduce((sum, record) => sum + record.questionCount, 0);
  const filteredCorrect = filteredRecords.reduce((sum, record) => sum + record.summary.correct, 0);
  const filteredAnswered = filteredRecords.reduce((sum, record) => sum + record.summary.total, 0);
  const filteredAccuracy = filteredAnswered ? Math.round((filteredCorrect / filteredAnswered) * 100) : 0;
  const selectedDateLabel = dateOptions.find((option) => option.key === filters.dateKey)?.label || "";
  const sortLabels = {
    newest: "Newest first",
    oldest: "Oldest first",
    best: "Best score",
    "most-wrong": "Most wrong",
  };
  const activeFilterText = [
    selectedDateLabel,
    filters.course,
    filters.topic,
    filters.sort !== "newest" ? sortLabels[filters.sort] : "",
  ].filter(Boolean).join(" • ");
  const hasActivePreviousTestFilters = Boolean(activeFilterText);

  const renderedRecords = filteredRecords.slice(0, PREVIOUS_TEST_RENDER_LIMIT);
  const hiddenFilteredRecordCount = Math.max(0, filteredRecords.length - renderedRecords.length);
  const rows = renderedRecords.length
    ? renderedRecords
      .map((record) => {
        const { session, summary } = record;
      return `
        <tr class="previous-test-row">
          <td class="previous-test-title-cell">
            <div class="previous-test-name">${escapeHtml(record.name)}</div>
            <div class="previous-test-meta-line">
              <span>${escapeHtml(record.displayId)}</span>
              <span>${escapeHtml(record.sourceLabel)}</span>
              <span>${record.questionCount} q</span>
            </div>
          </td>
          <td class="previous-test-date-cell">
            <span class="previous-test-date-main">${escapeHtml(record.dateLabel)}</span>
            <small>${escapeHtml(record.timeLabel)}</small>
          </td>
          <td>
            <div class="previous-test-chip-row">${renderPreviousTestMiniChips(record.courses, "No course")}</div>
          </td>
          <td>
            <div class="previous-test-chip-row">${renderPreviousTestMiniChips(record.topics, "No topic")}</div>
          </td>
          <td>${escapeHtml(record.modeLabel)}</td>
          <td>${summary.correct}/${summary.total} (${summary.accuracy}%)</td>
          <td>${summary.wrongCount}</td>
          <td>
            <div class="previous-test-actions">
              <button class="btn ghost admin-btn-sm" type="button" data-action="open-previous-review" data-session-id="${escapeHtml(session.id)}">Review</button>
              <button class="btn admin-btn-sm" type="button" data-action="retry-wrong-session" data-session-id="${escapeHtml(session.id)}" ${summary.wrongCount ? "" : "disabled"}>
                Retry wrong
              </button>
            </div>
          </td>
        </tr>
      `;
      })
      .join("")
    : `
      <tr>
        <td colspan="8">
          <div class="previous-tests-empty">
            <b>No previous tests match these filters.</b>
            <span>${escapeHtml(activeFilterText || "Try another date, course, or topic.")}</span>
          </div>
        </td>
      </tr>
    `;

  return `
    <section class="panel previous-tests-panel">
      <div class="previous-tests-head">
        <div>
          <h3>Previous Tests</h3>
          <p class="subtle">Review completed blocks or generate a new test from questions you got wrong.</p>
          <p class="subtle">Previous tests are kept for ${PREVIOUS_TEST_RETENTION_DAYS} days. Older test history is automatically deleted.</p>
        </div>
        <button class="btn ghost admin-btn-sm" type="button" data-action="reset-previous-test-filters" ${hasActivePreviousTestFilters ? "" : "disabled"}>Reset filters</button>
      </div>

      <div class="previous-tests-summary-strip" aria-label="Previous tests summary">
        <span><b>${filteredRecords.length}</b><small>shown</small></span>
        <span><b>${records.length}</b><small>recent total</small></span>
        <span><b>${filteredQuestionCount}</b><small>questions</small></span>
        <span><b>${filteredAccuracy}%</b><small>accuracy</small></span>
      </div>
      ${hiddenCompletedAnalysisCount || hiddenFilteredRecordCount
      ? `<p class="subtle" style="margin: 0.75rem 0 0;">Showing recent test history in batches for stability${hiddenCompletedAnalysisCount ? `; ${hiddenCompletedAnalysisCount} retained test(s) are outside this quick analysis batch` : ""}${hiddenFilteredRecordCount ? `; narrow filters to see the ${hiddenFilteredRecordCount} hidden matching row(s)` : ""}.</p>`
      : ""
    }

      <div class="previous-tests-filter-grid">
        <label>
          Date solved
          <select id="previous-test-filter-date" name="previousTestDate" data-role="previous-test-filter" data-filter="dateKey">
            <option value="">All dates</option>
            ${dateOptions.map((option) => `<option value="${escapeHtml(option.key)}" ${filters.dateKey === option.key ? "selected" : ""}>${escapeHtml(`${option.label} (${option.count})`)}</option>`).join("")}
          </select>
        </label>
        <label>
          Course
          <select id="previous-test-filter-course" name="previousTestCourse" data-role="previous-test-filter" data-filter="course">
            ${renderPreviousTestOptions(courseOptions, filters.course, "All courses", courseCountMap)}
          </select>
        </label>
        <label>
          Topic
          <select id="previous-test-filter-topic" name="previousTestTopic" data-role="previous-test-filter" data-filter="topic">
            ${renderPreviousTestOptions(topicOptions, filters.topic, filters.course ? "All topics in course" : "All topics", topicCountMap)}
          </select>
        </label>
        <label>
          Sort
          <select id="previous-test-filter-sort" name="previousTestSort" data-role="previous-test-filter" data-filter="sort">
            <option value="newest" ${filters.sort === "newest" ? "selected" : ""}>Newest first</option>
            <option value="oldest" ${filters.sort === "oldest" ? "selected" : ""}>Oldest first</option>
            <option value="best" ${filters.sort === "best" ? "selected" : ""}>Best score</option>
            <option value="most-wrong" ${filters.sort === "most-wrong" ? "selected" : ""}>Most wrong</option>
          </select>
        </label>
      </div>

      <div class="table-wrap previous-tests-table-wrap">
        <table class="previous-tests-table">
          <thead>
            <tr>
              <th>Test</th>
              <th>Solved</th>
              <th>Course</th>
              <th>Topic</th>
              <th>Mode</th>
              <th>Score</th>
              <th>Wrong</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
      </div>
    </section>
  `;
}

function wireDashboard() {
  appEl.querySelector("[data-action='dash-review-incorrect']")?.addEventListener("click", () => {
    state.createTestSource = "incorrect";
    state.skipNextRouteAnimation = true;
    navigate("create-test");
  });

  wireStudentRefreshButtons();

  appEl.querySelectorAll("[data-role='previous-test-filter']").forEach((control) => {
    control.addEventListener("change", () => {
      const filterKey = String(control.getAttribute("data-filter") || "").trim();
      if (!["dateKey", "course", "topic", "sort"].includes(filterKey)) {
        return;
      }
      const filters = getPreviousTestFilters();
      filters[filterKey] = String(control.value || "").trim();
      if (filterKey === "course") {
        filters.topic = "";
      }
      state.previousTestFilters = filters;
      state.skipNextRouteAnimation = true;
      render();
    });
  });

  appEl.querySelector("[data-action='reset-previous-test-filters']")?.addEventListener("click", () => {
    state.previousTestFilters = {
      dateKey: "",
      course: "",
      topic: "",
      sort: "newest",
    };
    state.skipNextRouteAnimation = true;
    render();
  });

  appEl.querySelectorAll("[data-action='open-previous-review']").forEach((button) => {
    button.addEventListener("click", () => {
      const sessionId = button.getAttribute("data-session-id");
      if (!sessionId) return;
      state.reviewSessionId = sessionId;
      state.reviewIndex = 0;
      navigate("review");
    });
  });

  appEl.querySelectorAll("[data-action='retry-wrong-session']").forEach((button) => {
    button.addEventListener("click", () => {
      const sessionId = button.getAttribute("data-session-id");
      const user = getCurrentUser();
      if (!sessionId || !user) return;
      const session = getReviewableCompletedSessionsForUser(user, {
        userOverride: user,
        fallbackToAllTerms: true,
      }).find((entry) => entry.id === sessionId);
      if (!session) {
        toast("Previous test not found.");
        return;
      }

      const questionStore = getQuestionStore();
      const publishedMap = buildQuestionIdentityLookup(getPublishedQuestionsForUser(user), questionStore);
      const retryMeta = getRetryQuestionMetaForSession(session);
      const pool = retryMeta.questionIds
        .map((id) => getQuestionFromIdentityLookup(publishedMap, id, questionStore))
        .filter(Boolean);
      if (!pool.length) {
        toast("No available wrong/unsolved questions to retry for this test.");
        return;
      }

      const autoFinalizedIds = finalizeActiveSessionsForUser(user.id);
      const created = createSessionFromQuestions(pool, {
        mode: "tutor",
        source: "previous-incorrect",
        duration: 20,
        originSessionId: session.id,
      });
      if (!created) {
        toast("No questions match this test setup.");
        return;
      }

      state.sessionId = created.id;
      navigate("session", { sessionId: created.id });
      toast(
        autoFinalizedIds.length
          ? `Retry test created: ${retryMeta.wrongSubmitted} wrong + ${retryMeta.unsolved} unsolved. ${autoFinalizedIds.length} previous active block(s) were ended automatically.`
          : `Retry test created: ${retryMeta.wrongSubmitted} wrong + ${retryMeta.unsolved} unsolved.`,
      );
    });
  });
}

async function refreshStudentAnalyticsNow(options = {}) {
  const user = getCurrentUser();
  if (!user || user.role !== "student") {
    return false;
  }
  if (state.studentDataRefreshing) {
    if (!options?.silent) {
      toast("Analytics sync already in progress.");
    }
    return false;
  }

  const ok = await refreshStudentDataSnapshot(user, {
    force: true,
    rerender: true,
    requireFreshContent: true,
  });
  if (!options?.silent) {
    if (ok) {
      toast("Updates received.");
    } else {
      const readyError = String(relationalSync.lastReadyError || "").trim().toLowerCase();
      const noSession = readyError.includes("no active supabase session");
      toast(
        noSession
          ? "Supabase session expired. Log out and log in again, then refresh analytics."
          : "Could not refresh the latest cloud questions and topics. Please retry.",
      );
    }
  }
  return ok;
}

function getCreateTestSourceLabel(source) {
  const labels = {
    all: "All matching",
    unused: "Unused only",
    incorrect: "Wrong only",
    flagged: "Flagged only",
    "previous-incorrect": "Retry wrong",
  };
  return labels[source] || labels.all;
}

function formatSessionModeLabel(mode) {
  return mode === "timed" ? "Timed" : "Tutor";
}

function normalizeSessionName(value, fallback = "") {
  const normalized = String(value || "").replace(/\s+/g, " ").trim();
  if (normalized) {
    return normalized.slice(0, 80);
  }
  return String(fallback || "").replace(/\s+/g, " ").trim().slice(0, 80);
}

function buildSessionDisplayId(sessionId) {
  const normalized = String(sessionId || "")
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  if (!normalized) {
    return "TEST-UNKNOWN";
  }

  let parts = normalized.split("-").filter(Boolean);
  if (parts[0] === "S" && parts.length > 1) {
    parts = parts.slice(1);
  }
  if (parts.length > 3) {
    parts = [parts[0], ...parts.slice(-2)];
  }
  return `TEST-${parts.join("-")}`;
}

function normalizeSessionTestId(value, sessionId) {
  const normalized = String(value || "").replace(/\s+/g, " ").trim().toUpperCase();
  return normalized || buildSessionDisplayId(sessionId);
}

function buildAutoSessionName(options = {}) {
  const normalizedCourses = [...new Set(
    (Array.isArray(options.courses) ? options.courses : [])
      .map((course) => String(course || "").trim())
      .filter(Boolean),
  )];
  const courseLabel = normalizedCourses.length > 1
    ? "Mixed courses"
    : (normalizedCourses[0] || String(options.courseLabel || "").trim() || "General test");
  const sourceLabel = getCreateTestSourceLabel(options.source || "all");
  const questionCount = Math.max(0, Math.floor(Number(options.questionCount || 0)));
  const countLabel = questionCount
    ? `${questionCount} question${questionCount === 1 ? "" : "s"}`
    : "";
  return [courseLabel, formatSessionModeLabel(options.mode), sourceLabel, countLabel]
    .filter(Boolean)
    .join(" • ");
}

function buildAutoSessionNameFromSession(session) {
  return buildAutoSessionName({
    courses: getSessionCourseList(session),
    mode: session?.mode,
    source: session?.source,
    questionCount: Array.isArray(session?.questionIds) ? session.questionIds.length : 0,
  });
}

function getSessionDisplayName(session) {
  return normalizeSessionName(session?.name, buildAutoSessionNameFromSession(session));
}

function getSessionDisplayId(session) {
  return normalizeSessionTestId(session?.testId, session?.id);
}

function getSessionTopicSummary(session) {
  if (!session || typeof session !== "object") {
    return "";
  }

  const questionStore = getQuestionStore();
  const topics = [];
  const seenTopics = new Set();
  (Array.isArray(session.questionIds) ? session.questionIds : []).forEach((qid) => {
    const question = getQuestionForSession(session, qid, questionStore);
    if (!question) {
      return;
    }
    const topic = String(getQbankCourseTopicMeta(question).topic || question.qbankTopic || question.topic || "").trim();
    if (!topic || seenTopics.has(topic)) {
      return;
    }
    seenTopics.add(topic);
    topics.push(topic);
  });

  if (!topics.length) {
    return "";
  }
  return formatTopicFilterSummary(topics);
}

function getCreateTestEmptyTopicMessage(user, course, questions = []) {
  const selectedCourse = String(course || "").trim();
  const availableCourses = getAvailableCoursesForUser(user);
  if (user?.role === "student" && selectedCourse && !availableCourses.includes(selectedCourse)) {
    return "This course is not part of your active enrollment. Ask an admin to check your year and semester.";
  }
  const configuredTopics = (QBANK_COURSE_TOPICS[selectedCourse] || []).filter((topic) => !isRemovedTopicName(topic));
  if (!configuredTopics.length) {
    return "Your enrollment is active, but this course has no active topics configured yet. Ask an admin to check the course setup.";
  }
  const hasPublishedQuestionsForCourse = (questions || []).some((question) => {
    const meta = getQbankCourseTopicMeta(question);
    return doCourseNamesMatch(meta.course, selectedCourse);
  });
  if (!hasPublishedQuestionsForCourse) {
    return "This course is active for your enrollment, but no published questions are available yet.";
  }
  return "No published topics are available for this course yet.";
}

function recordCreateTestZeroQuestionDiagnostic(user, context = {}) {
  const profileId = String(getCurrentSessionProfileId(user) || getUserProfileId(user) || user?.id || "").trim();
  const course = String(context?.course || "").trim();
  const selectedTopics = Array.isArray(context?.selectedTopics) ? context.selectedTopics : [];
  const signature = `${profileId || "unknown"}:${course}:${selectedTopics.map((topic) => normalizeTopicLookupKey(topic) || topic).join("|")}:${context?.source || ""}`;
  const nowMs = Date.now();
  const lastAt = Number(studentQuestionAvailabilityLogTimes.get(signature) || 0);
  if (lastAt && nowMs - lastAt < STUDENT_ACCESS_LOG_THROTTLE_MS) {
    return;
  }
  studentQuestionAvailabilityLogTimes.set(signature, nowMs);

  const allQuestions = getQuestions();
  const publishedUsableQuestions = Array.isArray(context?.questions) ? context.questions : getPublishedQuestionsForUser(user);
  const rawPublishedForCourse = allQuestions.filter((question) => {
    const meta = getQbankCourseTopicMeta(question);
    return question?.status === "published" && doCourseNamesMatch(meta.course, course);
  });
  const usableForCourse = publishedUsableQuestions.filter((question) => doCourseNamesMatch(getQbankCourseTopicMeta(question).course, course));
  const topicMatches = selectedTopics.map((topic) => ({
    topic,
    publishedUsableCount: usableForCourse.filter((question) => doTopicNamesMatch(getQbankCourseTopicMeta(question).topic, topic)).length,
    rawPublishedCount: rawPublishedForCourse.filter((question) => doTopicNamesMatch(getQbankCourseTopicMeta(question).topic, topic)).length,
  }));
  const reason = (() => {
    if (context?.accessIssue?.code) return context.accessIssue.code;
    if (!isUserAccessApproved(user)) return "not_approved";
    if (!profileId) return "missing_profile";
    if (!Array.isArray(context?.availableCourses) || !context.availableCourses.length) return "missing_enrollment";
    if (!publishedUsableQuestions.length && allQuestions.some((question) => question?.status === "published")) return "query_or_rls_or_usability_failure";
    if (!rawPublishedForCourse.length) return "no_published_questions_for_course";
    if (!usableForCourse.length) return "course_questions_unusable_or_enrollment_filtered";
    if (selectedTopics.length && topicMatches.every((entry) => entry.publishedUsableCount === 0)) return "topic_mismatch";
    if (Array.isArray(context?.courseTopicFiltered) && context.courseTopicFiltered.length && !context?.sourceFiltered?.length) return "source_filter_empty";
    return "unknown_zero_question_state";
  })();

  console.warn("Create-test zero-question diagnostic:", {
    reason,
    userId: String(user?.id || "").trim(),
    profileId,
    email: String(user?.email || "").trim().toLowerCase(),
    course,
    source: String(context?.source || "").trim(),
    selectedTopics,
    availableCourses: Array.isArray(context?.availableCourses) ? context.availableCourses : [],
    topicOptions: Array.isArray(context?.topicOptions) ? context.topicOptions : [],
    totalLocalQuestions: allQuestions.length,
    totalPublishedUsableQuestions: publishedUsableQuestions.length,
    rawPublishedForCourse: rawPublishedForCourse.length,
    usableForCourse: usableForCourse.length,
    courseTopicFiltered: Array.isArray(context?.courseTopicFiltered) ? context.courseTopicFiltered.length : 0,
    sourceFiltered: Array.isArray(context?.sourceFiltered) ? context.sourceFiltered.length : 0,
    topicMatches,
  });
}

function getCreateTestStartHelpMessage(options = {}) {
  const selectedTopics = Array.isArray(options.selectedTopics) ? options.selectedTopics : [];
  const sourceFiltered = Array.isArray(options.sourceFiltered) ? options.sourceFiltered : [];
  const hasTopicSources = Boolean(options.hasTopicSources);
  const selectedTopicSource = String(options.selectedTopicSource || "").trim();
  const topicOptions = Array.isArray(options.topicOptions) ? options.topicOptions : [];

  if (hasTopicSources && !selectedTopicSource) {
    return "Choose a source before starting a test.";
  }
  if (!selectedTopics.length) {
    return topicOptions.length
      ? "Select at least one topic to start a test."
      : "Topics must be available before a test can start.";
  }
  if (!sourceFiltered.length) {
    return "No published questions match this setup yet.";
  }
  return "";
}

function renderCreateTest() {
  const user = getCurrentUser();
  const availableCourses = getAvailableCoursesForUser(user);
  const contentReadiness = getStudentContentReadiness(user, { availableCourses });
  if (contentReadiness.loading) {
    logStudentContentAccessDecision(user, {
      reason: "create_test_waiting_for_content",
      surface: "create-test",
      availableCourses,
    });
    return renderStudentContentLoadingPanel("Checking Question Bank");
  }
  if (contentReadiness.error) {
    logStudentContentAccessDecision(user, {
      reason: "create_test_question_query_error",
      surface: "create-test",
      availableCourses,
      details: { message: contentReadiness.error },
    });
    return renderStudentContentErrorPanel("Question Bank Could Not Load", contentReadiness.error);
  }
  const accessIssue = contentReadiness.issue || getStudentAccessIssue(user, { availableCourses });
  const shouldRevalidateApprovedAccess = accessIssue?.code === "not_approved" && canRevalidateApprovedStudentAccess(user, accessIssue);
  if (shouldRevalidateApprovedAccess) {
    revalidateApprovedStudentAccess(user, {
      rerender: true,
      refreshSnapshot: true,
    }).catch((error) => {
      console.warn("Create-test approval revalidation failed.", error?.message || error);
    });
  }
  if (shouldRevalidateApprovedAccess && isApprovedStudentAccessRevalidationInFlight(user)) {
    return `
      <section class="panel">
        <h2 class="title">Checking Course Access</h2>
        <p class="subtle">Syncing your latest approval status from the database. This should only take a moment.</p>
        <div class="stack">
          <button class="btn" data-nav="dashboard">Back to dashboard</button>
          <button class="btn ghost" data-nav="profile">View profile</button>
        </div>
      </section>
    `;
  }
  if (accessIssue) {
    recordStudentAccessIssue(accessIssue, user, { surface: "create-test" });
    return `
      <section class="panel">
        <h2 class="title">Course Access Needs Attention</h2>
        <p class="subtle">${escapeHtml(accessIssue.message)}</p>
        <div class="stack">
          <button class="btn" data-nav="dashboard">Back to dashboard</button>
          <button class="btn ghost" data-nav="profile">View profile</button>
        </div>
      </section>
    `;
  }
  if (!availableCourses.length) {
    return `
      <section class="panel">
        <h2 class="title">Create a Test</h2>
        <p class="subtle">No active course enrollment is linked to this account. Ask an admin to save your year and semester again.</p>
      </section>
    `;
  }

  const questions = getPublishedQuestionsForUser(user);
  if (!Array.isArray(state.qbankFilters.topics)) {
    state.qbankFilters.topics = state.qbankFilters.topic ? [state.qbankFilters.topic] : [];
  }
  if (!availableCourses.includes(state.qbankFilters.course)) {
    state.qbankFilters.course = availableCourses[0];
    state.qbankFilters.topics = [];
    state.qbankFilters.topicSource = "";
  }
  const selectedCourse = state.qbankFilters.course;
  const topicSourceOptions = getAvailableTopicSourceOptionsForCourse(selectedCourse, questions);
  const hasTopicSources = topicSourceOptions.length > 0;
  let selectedTopicSource = String(state.qbankFilters.topicSource || "").trim();
  if (hasTopicSources) {
    if (!topicSourceOptions.some((option) => option.value === selectedTopicSource)) {
      const selectedTopicKeys = new Set((state.qbankFilters.topics || []).map((topic) => normalizeTopicLookupKey(topic) || String(topic || "").trim().toLowerCase()).filter(Boolean));
      const inferredSource = selectedTopicKeys.size
        ? topicSourceOptions.find((option) => option.topics.some((topic) => selectedTopicKeys.has(normalizeTopicLookupKey(topic) || String(topic || "").trim().toLowerCase())))
        : null;
      selectedTopicSource = inferredSource?.value || "";
      state.qbankFilters.topicSource = selectedTopicSource;
    }
  } else {
    selectedTopicSource = "";
    state.qbankFilters.topicSource = "";
  }
  const topicSections = getAvailableTopicSectionsForCourse(selectedCourse, questions, {
    topicSource: selectedTopicSource,
    includeConfigured: true,
  });
  const emptyTopicMessage = getCreateTestEmptyTopicMessage(user, selectedCourse, questions);
  const topicOptions = topicSections.flatMap((section) => section.topics || []);
  const selectedTopics = (state.qbankFilters.topics || [])
    .map((topic) => findMatchingTopicNameInList(topicOptions, topic) || String(topic || "").trim())
    .filter((topic) => topic && topicOptions.some((option) => doTopicNamesMatch(option, topic)));
  if (selectedTopics.length !== (state.qbankFilters.topics || []).length) {
    state.qbankFilters.topics = selectedTopics;
  }
  const filtered = applyQbankFilters(questions, {
    course: selectedCourse,
    topics: selectedTopics,
  }, {
    strictEmptyTopics: true,
  });
  const inProgress = getNormalizedActiveSessionForDisplay(user.id, state.sessionId);
  const allTopicsSelected = topicOptions.length > 0 && selectedTopics.length === topicOptions.length;
  const singleFlatTopicSection = (
    topicSections.length === 1
    && (!topicSections[0]?.name || String(topicSections[0]?.kind || "") === "flat")
  );
  const selectedTopicLabel = hasTopicSources && !selectedTopicSource
    ? "Choose a source first"
    : selectedTopics.length === 0
      ? "0 topics selected"
      : allTopicsSelected
        ? "All topics"
        : formatTopicFilterSummary(selectedTopics);
  const selectedSourceLabel = hasTopicSources
    ? (selectedTopicSource || "No source selected")
    : "Direct topics";
  const allowedSources = ["all", "unused", "incorrect", "flagged"];
  if (!allowedSources.includes(state.createTestSource)) {
    state.createTestSource = "all";
  }
  const sourceLabelMap = {
    all: "All matching",
    unused: "Unused only",
    incorrect: "Wrong only",
    flagged: "Flagged only",
  };
  let sourceFiltered = applySourceFilter(filtered, state.createTestSource, user.id);
  if (filtered.length && !sourceFiltered.length && state.createTestSource !== "all") {
    state.createTestSource = "all";
    sourceFiltered = filtered;
  }
  const defaultQuestionCount = Math.max(0, sourceFiltered.length || 0);
  const canStartTest = Boolean(selectedTopics.length) && sourceFiltered.length > 0 && (!hasTopicSources || Boolean(selectedTopicSource));
  const inProgressName = inProgress ? getSessionDisplayName(inProgress) : "";
  const inProgressTopicSummary = inProgress ? getSessionTopicSummary(inProgress) : "";
  if (selectedTopics.length && !sourceFiltered.length) {
    recordCreateTestZeroQuestionDiagnostic(user, {
      course: selectedCourse,
      selectedTopics,
      availableCourses,
      topicOptions,
      questions,
      courseTopicFiltered: filtered,
      sourceFiltered,
      source: state.createTestSource,
      accessIssue,
    });
  }
  const noMatchingQuestionsNotice = selectedTopics.length && !sourceFiltered.length
    ? "The selected topics are visible, but no published questions match this setup yet."
    : "";
  const startHelpMessage = getCreateTestStartHelpMessage({
    selectedTopics,
    sourceFiltered,
    hasTopicSources,
    selectedTopicSource,
    topicOptions,
  });

  return `
    <section class="panel">
      <h2 class="title">Create a Test</h2>
      <p class="subtle">Choose course and topics, then generate a test block.</p>
      ${inProgress
      ? `
        <div class="card create-test-active-block">
          <div>
            <span><b>Active block detected</b></span>
            <small class="subtle create-test-active-block-meta">${escapeHtml([inProgressName, inProgressTopicSummary].filter(Boolean).join(" • "))}</small>
          </div>
          <div class="create-test-active-block-actions">
            <button class="btn" data-nav="session">Resume</button>
            <button class="btn ghost" type="button" data-action="end-active-block" data-session-id="${escapeHtml(inProgress.id)}">End block</button>
          </div>
        </div>
      `
      : ""
    }

      <div class="create-test-filter-layout">
        <div class="create-test-filter-card">
          <div class="create-test-primary-filters">
            <label>
              Course
              <select name="course" id="create-test-course-select">
                ${availableCourses
      .map((course) => `<option value="${course}" ${selectedCourse === course ? "selected" : ""}>${course}</option>`)
      .join("")}
              </select>
            </label>
            ${hasTopicSources
      ? `
              <label>
                Source
                <select name="topicSource" id="create-test-topic-source-select">
                  <option value="" ${selectedTopicSource ? "" : "selected"}>Choose a source</option>
                  ${topicSourceOptions
        .map((option) => `<option value="${escapeHtml(option.value)}" ${selectedTopicSource === option.value ? "selected" : ""}>${escapeHtml(option.label)}</option>`)
        .join("")}
                </select>
              </label>
            `
      : ""}
          </div>
        </div>
        <div class="create-test-filter-card create-test-topics-group">
          ${hasTopicSources && !selectedTopicSource
      ? '<p class="subtle create-test-topic-empty">Choose a source to see the topics inside it.</p>'
      : topicSections.length
      ? `
              <div class="create-test-topic-actions">
                <button
                  type="button"
                  class="btn ghost admin-btn-sm"
                  data-action="create-test-select-all-topics"
                  ${allTopicsSelected ? "disabled" : ""}
                >
                  Select all topics
                </button>
                <button
                  type="button"
                  class="btn ghost admin-btn-sm"
                  data-action="create-test-clear-topic-selection"
                  ${selectedTopics.length ? "" : "disabled"}
                >
                  Clear
                </button>
              </div>
              ${singleFlatTopicSection
      ? `
                  <div class="create-test-topic-list">
                    ${(topicSections[0]?.topics || [])
        .map((topic) => {
          const isNewTopic = isTopicNewForUser(selectedCourse, topic, user);
          return `
                            <label class="admin-course-check create-test-topic-chip is-list-item">
                              <input type="checkbox" name="createTestTopics" data-role="create-test-topic" value="${escapeHtml(topic)}" ${(allTopicsSelected || selectedTopics.includes(topic)) ? "checked" : ""} />
                              <span class="create-test-topic-chip-copy">${escapeHtml(topic)}</span>
                              ${isNewTopic ? '<span class="create-test-topic-new-dot" title="New topic" aria-label="New topic"></span>' : ""}
                            </label>
                          `;
        })
        .join("")}
                  </div>
                `
      : `
                  <div class="create-test-topic-sections">
                    ${topicSections
        .map((section) => `
                          <section class="create-test-topic-section">
                            ${section.name ? `<p class="create-test-topic-section-title">${escapeHtml(section.name)}</p>` : ""}
                            <div class="create-test-topic-grid">
                              ${section.topics
            .map((topic) => {
              const isNewTopic = isTopicNewForUser(selectedCourse, topic, user);
              return `
                                    <label class="admin-course-check create-test-topic-chip">
                                      <input type="checkbox" name="createTestTopics" data-role="create-test-topic" value="${escapeHtml(topic)}" ${(allTopicsSelected || selectedTopics.includes(topic)) ? "checked" : ""} />
                                      <span class="create-test-topic-chip-copy">${escapeHtml(topic)}</span>
                                      ${isNewTopic ? '<span class="create-test-topic-new-dot" title="New topic" aria-label="New topic"></span>' : ""}
                                    </label>
                                  `;
            })
            .join("")}
                            </div>
                          </section>
                        `)
        .join("")}
                  </div>
                `}
            `
      : `<p class="subtle create-test-topic-empty">${escapeHtml(emptyTopicMessage)}</p>`}
        </div>
      </div>
    </section>

    <section class="panel">
      <h3 style="margin-top: 0;">Test Setup</h3>
      <form id="create-test-block-form" class="create-test-setup-form" autocomplete="off">
        <div class="create-test-setup-grid">
          <label class="create-test-setup-field">Number of questions
            <input name="count" type="number" min="0" max="${defaultQuestionCount}" step="1" value="${defaultQuestionCount}" />
          </label>
          <label class="create-test-setup-field">Test name (optional)
            <input
              name="testName"
              type="text"
              maxlength="80"
              placeholder="Leave blank for an automatic name"
              value="${escapeHtml(state.createTestNameDraft)}"
            />
          </label>
          <label class="create-test-setup-field">Mode
            <select name="mode" id="create-test-mode-select">
              <option value="tutor">Tutor</option>
              <option value="timed">Timed</option>
            </select>
          </label>
          <label class="create-test-setup-field">Question source
            <select name="source" id="create-test-source-select">
              <option value="all" ${state.createTestSource === "all" ? "selected" : ""}>All matching</option>
              <option value="unused" ${state.createTestSource === "unused" ? "selected" : ""}>Unused only</option>
              <option value="incorrect" ${state.createTestSource === "incorrect" ? "selected" : ""}>Wrong only</option>
              <option value="flagged" ${state.createTestSource === "flagged" ? "selected" : ""}>Flagged only</option>
            </select>
          </label>
          <label class="create-test-setup-field">Timer (minutes, timed mode)
            <input name="duration" id="create-test-duration-input" type="number" min="5" max="180" value="20" disabled />
          </label>
        </div>

        <label class="create-test-randomize">
          <input type="checkbox" name="randomize" />
          <span class="create-test-randomize-switch" aria-hidden="true"></span>
          <span class="create-test-randomize-copy">
            <b>Randomize questions</b>
            <small>Shuffle question order before starting the test.</small>
          </span>
        </label>

        <small id="create-test-filter-summary">Current filter: <b>${escapeHtml(selectedCourse)}</b> • Source: <b>${escapeHtml(selectedSourceLabel)}</b> • ${escapeHtml(selectedTopicLabel)} • Question source: <b>${escapeHtml(sourceLabelMap[state.createTestSource])}</b> (${sourceFiltered.length} questions)</small>
        <small id="create-test-start-help" class="subtle create-test-start-help" aria-live="polite" ${startHelpMessage ? "" : "hidden"}>${escapeHtml(startHelpMessage)}</small>
        ${noMatchingQuestionsNotice ? `<p class="subtle">${escapeHtml(noMatchingQuestionsNotice)}</p>` : ""}
        <div class="stack">
          <button type="submit" class="btn" aria-describedby="create-test-filter-summary create-test-start-help" ${canStartTest ? "" : "disabled"}>Start test</button>
        </div>
      </form>
    </section>
  `;
}

function wireCreateTest() {
  wireStudentRefreshButtons();

  const courseSelect = document.getElementById("create-test-course-select");
  const topicSourceSelect = document.getElementById("create-test-topic-source-select");
  const sourceSelect = document.getElementById("create-test-source-select");
  const endActiveBlockBtn = appEl.querySelector("[data-action='end-active-block']");
  const topicInputs = Array.from(document.querySelectorAll("input[data-role='create-test-topic']"));
  const selectAllTopicsBtn = appEl.querySelector("[data-action='create-test-select-all-topics']");
  const clearTopicsBtn = appEl.querySelector("[data-action='create-test-clear-topic-selection']");
  const summaryEl = document.getElementById("create-test-filter-summary");
  const startHelpEl = document.getElementById("create-test-start-help");
  const blockForm = document.getElementById("create-test-block-form");
  const countInput = blockForm?.querySelector("input[name='count']");
  const nameInput = blockForm?.querySelector("input[name='testName']");
  const submitButton = blockForm?.querySelector("button[type='submit']");
  const modeSelect = document.getElementById("create-test-mode-select");
  const durationInput = document.getElementById("create-test-duration-input");

  const syncDurationInputState = () => {
    if (!(modeSelect instanceof HTMLSelectElement) || !(durationInput instanceof HTMLInputElement)) {
      return;
    }
    const isTimed = String(modeSelect.value || "tutor") === "timed";
    durationInput.disabled = !isTimed;
  };
  syncDurationInputState();

  const syncTopicSelectionUi = () => {
    const selectedSet = new Set((state.qbankFilters.topics || []).map((topic) => String(topic || "").trim()));
    const totalTopics = topicInputs.length;
    const allTopicsMode = totalTopics > 0 && selectedSet.size === totalTopics;
    topicInputs.forEach((entry) => {
      entry.checked = allTopicsMode || selectedSet.has(String(entry.value || "").trim());
    });
    if (selectAllTopicsBtn) {
      selectAllTopicsBtn.disabled = totalTopics === 0 || allTopicsMode;
    }
    if (clearTopicsBtn) {
      clearTopicsBtn.disabled = selectedSet.size === 0;
    }
  };
  syncTopicSelectionUi();

  const updateCreateTestSummary = () => {
    const user = getCurrentUser();
    const availableCourses = getAvailableCoursesForUser(user);
    const fallbackCourse = availableCourses[0] || Object.keys(QBANK_COURSE_TOPICS)[0] || "";
    const selectedCourse = state.qbankFilters.course || fallbackCourse;
    const questions = getPublishedQuestionsForUser(user);
    const topicSourceOptions = getAvailableTopicSourceOptionsForCourse(selectedCourse, questions);
    const hasTopicSources = topicSourceOptions.length > 0;
    let selectedTopicSource = String(state.qbankFilters.topicSource || "").trim();
    if (hasTopicSources) {
      if (!topicSourceOptions.some((option) => option.value === selectedTopicSource)) {
        selectedTopicSource = "";
        state.qbankFilters.topicSource = "";
        state.qbankFilters.topics = [];
      }
    } else {
      selectedTopicSource = "";
      state.qbankFilters.topicSource = "";
    }
    const topicSections = getAvailableTopicSectionsForCourse(selectedCourse, questions, {
      topicSource: selectedTopicSource,
      includeConfigured: true,
    });
    const topicOptions = topicSections.flatMap((section) => section.topics || []);
    const selectedTopics = (state.qbankFilters.topics || [])
      .map((topic) => findMatchingTopicNameInList(topicOptions, topic) || String(topic || "").trim())
      .filter((topic) => topic && topicOptions.some((option) => doTopicNamesMatch(option, topic)));
    if (selectedTopics.length !== (state.qbankFilters.topics || []).length) {
      state.qbankFilters.topics = selectedTopics;
    }
    const allTopicsSelected = topicOptions.length > 0 && selectedTopics.length === topicOptions.length;
    const selectedTopicLabel = hasTopicSources && !selectedTopicSource
      ? "Choose a source first"
      : selectedTopics.length === 0
        ? "0 topics selected"
        : allTopicsSelected
          ? "All topics"
          : formatTopicFilterSummary(selectedTopics);
    const selectedSourceLabel = hasTopicSources
      ? (selectedTopicSource || "No source selected")
      : "Direct topics";
    const filteredByCourseTopic = applyQbankFilters(questions, {
      course: selectedCourse,
      topics: selectedTopics,
    }, {
      strictEmptyTopics: true,
    });
    const allowedSources = ["all", "unused", "incorrect", "flagged"];
    if (!allowedSources.includes(state.createTestSource)) {
      state.createTestSource = "all";
    }
    const sourceLabelMap = {
      all: "All matching",
      unused: "Unused only",
      incorrect: "Wrong only",
      flagged: "Flagged only",
    };
    let filtered = applySourceFilter(filteredByCourseTopic, state.createTestSource, user.id);
    if (filteredByCourseTopic.length && !filtered.length && state.createTestSource !== "all") {
      state.createTestSource = "all";
      filtered = filteredByCourseTopic;
      if (sourceSelect) {
        sourceSelect.value = "all";
      }
    }
    syncTopicSelectionUi();
    if (summaryEl) {
      summaryEl.innerHTML = `Current filter: <b>${escapeHtml(selectedCourse)}</b> • Source: <b>${escapeHtml(selectedSourceLabel)}</b> • ${escapeHtml(selectedTopicLabel)} • Question source: <b>${escapeHtml(sourceLabelMap[state.createTestSource])}</b> (${filtered.length} questions)`;
    }
    if (startHelpEl) {
      const startHelpMessage = getCreateTestStartHelpMessage({
        selectedTopics,
        sourceFiltered: filtered,
        hasTopicSources,
        selectedTopicSource,
        topicOptions,
      });
      startHelpEl.textContent = startHelpMessage;
      startHelpEl.hidden = !startHelpMessage;
    }
    if (countInput) {
      const suggestedCount = Math.max(0, filtered.length || 0);
      countInput.max = String(suggestedCount);
      countInput.value = String(suggestedCount);
    }
    if (submitButton) {
      submitButton.disabled = !(selectedTopics.length && filtered.length > 0 && (!hasTopicSources || selectedTopicSource));
    }
  };

  courseSelect?.addEventListener("change", () => {
    const fallbackCourse = getAvailableCoursesForUser(getCurrentUser())[0] || Object.keys(QBANK_COURSE_TOPICS)[0] || "";
    state.qbankFilters.course = courseSelect.value || fallbackCourse;
    state.qbankFilters.topics = [];
    state.qbankFilters.topicSource = "";
    state.skipNextRouteAnimation = true;
    render();
  });

  topicSourceSelect?.addEventListener("change", () => {
    const selectedCourse = String(state.qbankFilters.course || courseSelect?.value || "").trim();
    const questions = getPublishedQuestionsForUser(getCurrentUser());
    const topicSourceOptions = getAvailableTopicSourceOptionsForCourse(selectedCourse, questions);
    const nextSource = String(topicSourceSelect.value || "").trim();
    const selectedOption = topicSourceOptions.find((option) => option.value === nextSource);
    state.qbankFilters.topicSource = selectedOption?.value || "";
    state.qbankFilters.topics = [];
    state.skipNextRouteAnimation = true;
    render();
  });

  topicInputs.forEach((input) => {
    input.addEventListener("change", () => {
      const selected = topicInputs.filter((entry) => entry.checked).map((entry) => entry.value);
      state.qbankFilters.topics = selected;
      updateCreateTestSummary();
    });
  });

  selectAllTopicsBtn?.addEventListener("click", () => {
    state.qbankFilters.topics = topicInputs.map((entry) => String(entry.value || "").trim()).filter(Boolean);
    updateCreateTestSummary();
  });

  clearTopicsBtn?.addEventListener("click", () => {
    state.qbankFilters.topics = [];
    updateCreateTestSummary();
  });

  sourceSelect?.addEventListener("change", () => {
    state.createTestSource = String(sourceSelect.value || "all");
    updateCreateTestSummary();
  });

  modeSelect?.addEventListener("change", () => {
    syncDurationInputState();
  });

  nameInput?.addEventListener("input", () => {
    state.createTestNameDraft = String(nameInput.value || "");
  });

  endActiveBlockBtn?.addEventListener("click", () => {
    const user = getCurrentUser();
    const sessionId = String(endActiveBlockBtn.getAttribute("data-session-id") || "").trim();
    if (!user || !sessionId) {
      return;
    }

    const session = getSessionById(sessionId);
    if (!session || !doesSessionBelongToUser(session, user) || session.status !== "in_progress") {
      toast("Active block not found.");
      state.skipNextRouteAnimation = true;
      render();
      return;
    }

    finalizeSession(session.id);
    if (state.sessionId === session.id) {
      state.sessionId = null;
    }
    toast("Block ended and moved to previous tests.");
    state.skipNextRouteAnimation = true;
    render();
  });

  blockForm?.addEventListener("submit", (event) => {
    event.preventDefault();
    const user = getCurrentUser();
    const data = new FormData(blockForm);

    const mode = String(data.get("mode") || "tutor");
	    let source = String(data.get("source") || state.createTestSource || "all");
    state.createTestSource = source;
    const requestedTestNameRaw = String(data.get("testName") || state.createTestNameDraft || "");
    const requestedTestName = normalizeSessionName(requestedTestNameRaw);
    state.createTestNameDraft = requestedTestNameRaw;
    const duration = Math.max(5, Number(data.get("duration") || 20));
    const randomize = data.get("randomize") === "on";

    const availableCourses = getAvailableCoursesForUser(user);
    if (!availableCourses.includes(state.qbankFilters.course)) {
      state.qbankFilters.course = availableCourses[0] || "";
      state.qbankFilters.topics = [];
      state.qbankFilters.topicSource = "";
    }
    const topicSourceOptions = getAvailableTopicSourceOptionsForCourse(state.qbankFilters.course, getPublishedQuestionsForUser(user));
    const hasTopicSources = topicSourceOptions.length > 0;
    if (hasTopicSources && !String(state.qbankFilters.topicSource || "").trim()) {
      toast("Choose a source first.");
      return;
    }
    if (!(state.qbankFilters.topics || []).length) {
      toast("Choose at least one topic.");
      return;
    }
	    let pool = applyQbankFilters(getPublishedQuestionsForUser(user), state.qbankFilters, {
	      strictEmptyTopics: true,
	    });
	    const allMatchingPool = pool;
	    pool = applySourceFilter(pool, source, user.id);
	    if (allMatchingPool.length && !pool.length && source !== "all") {
	      state.createTestSource = "all";
	      source = "all";
	      pool = allMatchingPool;
	      toast("No questions matched that source filter, so all matching questions were used.");
	    }
    const fallbackCount = Math.max(0, pool.length || 0);
    const requestedCount = Math.floor(Number(data.get("count")));
    const count = Math.min(
      pool.length,
      Math.max(0, Number.isFinite(requestedCount) ? requestedCount : fallbackCount),
    );
    if (count <= 0) {
      toast("Choose at least one topic first.");
      return;
    }

    if (randomize) {
      pool = shuffle(pool);
    }

    const autoFinalizedIds = finalizeActiveSessionsForUser(user.id);
    const session = createSessionFromQuestions(pool, {
      count,
      mode,
      source,
      name: requestedTestName,
      courseLabel: state.qbankFilters.course,
      duration,
      originSessionId: null,
    });
    if (!session) {
      toast("No questions match this test setup.");
      return;
    }

    state.createTestNameDraft = "";
    state.sessionId = session.id;
    navigate("session", { sessionId: session.id });
    toast(
      autoFinalizedIds.length
        ? `Test created. ${autoFinalizedIds.length} previous active block(s) were ended automatically and moved to previous tests.`
        : "Test created.",
    );
  });

  const currentUser = getCurrentUser();
  const visibleCourse = String(state.qbankFilters.course || courseSelect?.value || "").trim();
  const visibleTopics = topicInputs.map((input) => String(input.value || "").trim()).filter(Boolean);
  if (currentUser?.role === "student" && visibleCourse && visibleTopics.length) {
    markTopicListAsSeen(visibleCourse, visibleTopics, currentUser);
  }
}

function getSessionFontScaleCssValue() {
  const normalized = normalizeSessionFontScalePercent(state.sessionFontScalePercent, SESSION_FONT_SCALE_DEFAULT);
  return (normalized / 100).toFixed(2);
}

function setSessionFontScalePercent(nextPercent, options = {}) {
  const normalized = normalizeSessionFontScalePercent(nextPercent, state.sessionFontScalePercent);
  if (state.sessionFontScalePercent === normalized && !options.force) {
    return false;
  }
  state.sessionFontScalePercent = normalized;
  state.sessionFontScale = getSessionFontScaleBucket(normalized);
  persistSessionUiPreferences();
  return true;
}

function renderSessionNavSettings() {
  const markerToneClass = state.sessionMarkerEnabled ? "is-active" : "";
  const markerLabel = state.sessionMarkerEnabled ? "Highlighter on" : "Highlighter off";
  const markerButtonText = state.sessionMarkerEnabled ? "Disable highlighter" : "Enable highlighter";
  const fontPercent = normalizeSessionFontScalePercent(state.sessionFontScalePercent, SESSION_FONT_SCALE_DEFAULT);

  return `
    <div class="exam-nav-settings">
      <div class="exam-nav-setting-row">
        <span class="exam-nav-setting-label">Font size</span>
        <div class="exam-nav-font-controls">
          <button
            type="button"
            class="btn ghost exam-nav-step-btn"
            data-action="decrease-session-font"
            aria-label="Decrease font size"
            title="Decrease font size"
          >−</button>
          <input
            id="session-font-scale-slider"
            class="exam-nav-font-slider"
            type="range"
            min="${SESSION_FONT_SCALE_MIN}"
            max="${SESSION_FONT_SCALE_MAX}"
            step="${SESSION_FONT_SCALE_STEP}"
            value="${fontPercent}"
            aria-label="Session font size"
          />
          <button
            type="button"
            class="btn ghost exam-nav-step-btn"
            data-action="increase-session-font"
            aria-label="Increase font size"
            title="Increase font size"
          >+</button>
          <span class="exam-nav-font-value" data-role="session-font-scale-value">${fontPercent}%</span>
        </div>
      </div>
      <div class="exam-nav-setting-row">
        <span class="exam-nav-setting-label">Highlighter</span>
        <button
          type="button"
          class="btn ghost exam-nav-marker-toggle ${markerToneClass}"
          data-action="toggle-marker-mode"
          aria-pressed="${state.sessionMarkerEnabled ? "true" : "false"}"
        >${markerButtonText}</button>
      </div>
      <div class="exam-nav-setting-row">
        <span class="exam-nav-setting-label">${markerLabel}</span>
        <div class="exam-nav-highlight-palette" role="group" aria-label="Highlighter colors">
          ${["yellow", "red", "green"]
      .map((color) => `
              <button
                type="button"
                class="exam-nav-color-btn ${state.sessionHighlighterColor === color ? "is-selected" : ""}"
                data-action="set-highlighter-color"
                data-color="${color}"
                aria-label="${color[0].toUpperCase()}${color.slice(1)} highlighter"
                aria-pressed="${state.sessionHighlighterColor === color ? "true" : "false"}"
              ><span class="swatch is-${color}" aria-hidden="true"></span></button>
            `)
      .join("")}
        </div>
      </div>
      <button type="button" class="btn ghost exam-nav-reset-btn" data-action="reset-session-ui-settings">Reset settings</button>
    </div>
  `;
}

function syncSessionUiControlsInDom() {
  const shell = appEl.querySelector(".exam-shell");
  if (shell) {
    shell.style.setProperty("--exam-font-scale", getSessionFontScaleCssValue());
    shell.classList.toggle("marker-on", Boolean(state.sessionMarkerEnabled));
    const normalizedColor = normalizeSessionHighlightColor(state.sessionHighlighterColor);
    shell.classList.remove("marker-yellow", "marker-red", "marker-green");
    shell.classList.add(`marker-${normalizedColor}`);
  }

  const slider = document.getElementById("session-font-scale-slider");
  const fontPercent = normalizeSessionFontScalePercent(state.sessionFontScalePercent, SESSION_FONT_SCALE_DEFAULT);
  if (slider && String(slider.value) !== String(fontPercent)) {
    slider.value = String(fontPercent);
  }
  const valueEl = appEl.querySelector("[data-role='session-font-scale-value']");
  if (valueEl) {
    valueEl.textContent = `${fontPercent}%`;
  }
}

function buildEmptyTextHighlightStore() {
  return {
    lines: {},
    choices: {},
  };
}

function ensureResponseTextHighlightStore(response) {
  if (!response || typeof response !== "object") {
    return buildEmptyTextHighlightStore();
  }
  if (!response.textHighlights || typeof response.textHighlights !== "object" || Array.isArray(response.textHighlights)) {
    response.textHighlights = buildEmptyTextHighlightStore();
    return response.textHighlights;
  }
  if (!response.textHighlights.lines || typeof response.textHighlights.lines !== "object" || Array.isArray(response.textHighlights.lines)) {
    response.textHighlights.lines = {};
  }
  if (!response.textHighlights.choices || typeof response.textHighlights.choices !== "object" || Array.isArray(response.textHighlights.choices)) {
    response.textHighlights.choices = {};
  }
  return response.textHighlights;
}

function normalizeTextHighlightRanges(ranges, maxLength = null) {
  if (!Array.isArray(ranges)) {
    return [];
  }
  const hasBound = Number.isFinite(maxLength);
  const lengthBound = hasBound ? Math.max(0, Math.floor(Number(maxLength))) : null;
  const normalized = [];
  ranges.forEach((entry) => {
    const color = normalizeSessionHighlightColor(entry?.color, "");
    if (!color) {
      return;
    }
    let start = Math.floor(Number(entry?.start));
    let end = Math.floor(Number(entry?.end));
    if (!Number.isFinite(start) || !Number.isFinite(end)) {
      return;
    }
    if (hasBound) {
      start = Math.min(lengthBound, Math.max(0, start));
      end = Math.min(lengthBound, Math.max(0, end));
    } else {
      start = Math.max(0, start);
      end = Math.max(0, end);
    }
    if (end <= start) {
      return;
    }
    normalized.push({ start, end, color });
  });
  normalized.sort((a, b) => a.start - b.start || a.end - b.end);
  const merged = [];
  normalized.forEach((range) => {
    const previous = merged[merged.length - 1];
    if (previous && previous.color === range.color && range.start <= previous.end) {
      previous.end = Math.max(previous.end, range.end);
      return;
    }
    merged.push({ ...range });
  });
  return merged;
}

function resolveTextHighlightRanges(ranges, textLength) {
  const safeLength = Math.max(0, Math.floor(Number(textLength) || 0));
  if (!safeLength) {
    return [];
  }
  const resolvedRanges = normalizeTextHighlightRanges(ranges, safeLength);
  if (!resolvedRanges.length) {
    return [];
  }
  const charColors = new Array(safeLength).fill("");
  resolvedRanges.forEach((range) => {
    for (let index = range.start; index < range.end; index += 1) {
      charColors[index] = range.color;
    }
  });
  const compressed = [];
  let activeColor = "";
  let activeStart = -1;
  for (let index = 0; index <= safeLength; index += 1) {
    const current = index < safeLength ? charColors[index] : "";
    if (current === activeColor) {
      continue;
    }
    if (activeColor) {
      compressed.push({ start: activeStart, end: index, color: activeColor });
    }
    activeColor = current;
    activeStart = current ? index : -1;
  }
  return compressed;
}

function getPrimaryHighlightColorFromRanges(ranges) {
  if (!Array.isArray(ranges) || !ranges.length) {
    return "";
  }
  const firstColor = normalizeSessionHighlightColor(ranges[0]?.color, "");
  return firstColor || "";
}

function renderTextWithInlineHighlights(text, ranges) {
  const content = String(text || "");
  if (!content) {
    return "";
  }
  const resolvedRanges = resolveTextHighlightRanges(ranges, content.length);
  if (!resolvedRanges.length) {
    return escapeHtml(content);
  }
  const parts = [];
  let cursor = 0;
  resolvedRanges.forEach((range) => {
    if (range.start > cursor) {
      parts.push(escapeHtml(content.slice(cursor, range.start)));
    }
    const highlightedChunk = escapeHtml(content.slice(range.start, range.end));
    parts.push(`<span class="exam-inline-highlight is-text-highlighted is-highlight-${range.color}">${highlightedChunk}</span>`);
    cursor = range.end;
  });
  if (cursor < content.length) {
    parts.push(escapeHtml(content.slice(cursor)));
  }
  return parts.join("");
}

function updateHighlightRangesWithSelection(ranges, selectionStart, selectionEnd, color, textLength) {
  const safeLength = Math.max(0, Math.floor(Number(textLength) || 0));
  if (!safeLength) {
    return [];
  }
  const normalizedColor = normalizeSessionHighlightColor(color);
  const start = Math.max(0, Math.min(safeLength, Math.floor(Number(selectionStart) || 0)));
  const end = Math.max(0, Math.min(safeLength, Math.floor(Number(selectionEnd) || 0)));
  if (end <= start) {
    return resolveTextHighlightRanges(ranges, safeLength);
  }
  const charColors = new Array(safeLength).fill("");
  resolveTextHighlightRanges(ranges, safeLength).forEach((range) => {
    for (let index = range.start; index < range.end; index += 1) {
      charColors[index] = range.color;
    }
  });
  let alreadyHighlighted = true;
  for (let index = start; index < end; index += 1) {
    if (charColors[index] !== normalizedColor) {
      alreadyHighlighted = false;
      break;
    }
  }
  const nextColor = alreadyHighlighted ? "" : normalizedColor;
  for (let index = start; index < end; index += 1) {
    charColors[index] = nextColor;
  }
  const compressed = [];
  let activeColor = "";
  let activeStart = -1;
  for (let index = 0; index <= safeLength; index += 1) {
    const current = index < safeLength ? charColors[index] : "";
    if (current === activeColor) {
      continue;
    }
    if (activeColor) {
      compressed.push({ start: activeStart, end: index, color: activeColor });
    }
    activeColor = current;
    activeStart = current ? index : -1;
  }
  return compressed;
}

function getHighlightTargetFromNode(node) {
  const sourceElement = node && node.nodeType === 1 ? node : node?.parentElement;
  const target = sourceElement?.closest?.("[data-highlight-kind]");
  if (!target) {
    return null;
  }
  const kind = String(target.getAttribute("data-highlight-kind") || "").trim().toLowerCase();
  if (kind === "line") {
    const lineIndex = Math.floor(Number(target.getAttribute("data-line-index")));
    if (!Number.isFinite(lineIndex) || lineIndex < 0) {
      return null;
    }
    return { kind: "line", key: String(lineIndex), element: target };
  }
  if (kind === "choice") {
    const choiceId = normalizeQuestionChoiceLabel(target.getAttribute("data-choice-id"));
    if (!choiceId) {
      return null;
    }
    return { kind: "choice", key: choiceId, element: target };
  }
  return null;
}

function getSelectionOffsetsWithinElement(range, element) {
  if (!range || !element) {
    return null;
  }
  try {
    const beforeRange = range.cloneRange();
    beforeRange.selectNodeContents(element);
    beforeRange.setEnd(range.startContainer, range.startOffset);
    const start = beforeRange.toString().length;
    const length = range.toString().length;
    const end = start + length;
    if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) {
      return null;
    }
    return { start, end };
  } catch {
    return null;
  }
}

function getSessionHighlightUndoKey(sessionId, questionId) {
  return `${String(sessionId || "").trim()}::${String(questionId || "").trim()}`;
}

function shouldSuppressStrikeClick(sessionId, questionId, choiceId) {
  const pending = state.sessionPendingHighlightSelection;
  if (!pending) {
    return false;
  }
  const expired = Number(pending.expiresAt || 0) < Date.now();
  const matches = pending.kind === "choice"
    && pending.sessionId === sessionId
    && pending.questionId === questionId
    && pending.choiceId === choiceId;
  if (!matches || expired) {
    if (expired) {
      state.sessionPendingHighlightSelection = null;
    }
    return false;
  }
  state.sessionPendingHighlightSelection = null;
  return true;
}

function normalizeResponseHighlightSnapshot(snapshot) {
  const safeSnapshot = snapshot && typeof snapshot === "object" ? snapshot : {};
  const normalizedLineColors = {};
  if (safeSnapshot.highlightedLineColors && typeof safeSnapshot.highlightedLineColors === "object") {
    Object.entries(safeSnapshot.highlightedLineColors).forEach(([lineKey, color]) => {
      const lineIndex = Math.floor(Number(lineKey));
      const normalizedColor = normalizeSessionHighlightColor(color, "");
      if (!Number.isFinite(lineIndex) || lineIndex < 0 || !normalizedColor) {
        return;
      }
      normalizedLineColors[lineIndex] = normalizedColor;
    });
  }
  const normalizedChoiceColors = {};
  if (safeSnapshot.highlightedChoices && typeof safeSnapshot.highlightedChoices === "object") {
    Object.entries(safeSnapshot.highlightedChoices).forEach(([choiceKey, color]) => {
      const choiceId = normalizeQuestionChoiceLabel(choiceKey);
      const normalizedColor = normalizeSessionHighlightColor(color, "");
      if (!choiceId || !normalizedColor) {
        return;
      }
      normalizedChoiceColors[choiceId] = normalizedColor;
    });
  }
  const textHighlights = buildEmptyTextHighlightStore();
  if (safeSnapshot.textHighlights && typeof safeSnapshot.textHighlights === "object") {
    if (safeSnapshot.textHighlights.lines && typeof safeSnapshot.textHighlights.lines === "object") {
      Object.entries(safeSnapshot.textHighlights.lines).forEach(([lineKey, ranges]) => {
        const lineIndex = Math.floor(Number(lineKey));
        if (!Number.isFinite(lineIndex) || lineIndex < 0) {
          return;
        }
        const normalizedRanges = normalizeTextHighlightRanges(ranges);
        if (normalizedRanges.length) {
          textHighlights.lines[lineIndex] = normalizedRanges;
        }
      });
    }
    if (safeSnapshot.textHighlights.choices && typeof safeSnapshot.textHighlights.choices === "object") {
      Object.entries(safeSnapshot.textHighlights.choices).forEach(([choiceKey, ranges]) => {
        const choiceId = normalizeQuestionChoiceLabel(choiceKey);
        if (!choiceId) {
          return;
        }
        const normalizedRanges = normalizeTextHighlightRanges(ranges);
        if (normalizedRanges.length) {
          textHighlights.choices[choiceId] = normalizedRanges;
        }
      });
    }
  }
  const normalizedLines = Array.isArray(safeSnapshot.highlightedLines)
    ? [...new Set(safeSnapshot.highlightedLines
      .map((entry) => Math.floor(Number(entry)))
      .filter((entry) => Number.isFinite(entry) && entry >= 0))]
      .sort((a, b) => a - b)
    : [];
  Object.keys(normalizedLineColors).forEach((lineKey) => {
    const lineIndex = Math.floor(Number(lineKey));
    if (Number.isFinite(lineIndex) && lineIndex >= 0 && !normalizedLines.includes(lineIndex)) {
      normalizedLines.push(lineIndex);
    }
  });
  normalizedLines.sort((a, b) => a - b);
  return {
    highlightedLines: normalizedLines,
    highlightedLineColors: normalizedLineColors,
    highlightedChoices: normalizedChoiceColors,
    textHighlights,
  };
}

function captureResponseHighlightSnapshot(response) {
  ensureResponseTextHighlightStore(response);
  return normalizeResponseHighlightSnapshot({
    highlightedLines: response.highlightedLines,
    highlightedLineColors: response.highlightedLineColors,
    highlightedChoices: response.highlightedChoices,
    textHighlights: response.textHighlights,
  });
}

function applyResponseHighlightSnapshot(response, snapshot) {
  const normalized = normalizeResponseHighlightSnapshot(snapshot);
  response.highlightedLines = [...normalized.highlightedLines];
  response.highlightedLineColors = { ...normalized.highlightedLineColors };
  response.highlightedChoices = { ...normalized.highlightedChoices };
  response.textHighlights = {
    lines: { ...normalized.textHighlights.lines },
    choices: { ...normalized.textHighlights.choices },
  };
}

function pushSessionHighlightUndoSnapshot(sessionId, questionId, response) {
  const key = getSessionHighlightUndoKey(sessionId, questionId);
  if (!key || key === "::") {
    return;
  }
  const snapshot = captureResponseHighlightSnapshot(response);
  if (!state.sessionHighlightUndo[key]) {
    state.sessionHighlightUndo[key] = [];
  }
  const stack = state.sessionHighlightUndo[key];
  const lastSnapshot = stack[stack.length - 1];
  if (lastSnapshot && JSON.stringify(lastSnapshot) === JSON.stringify(snapshot)) {
    return;
  }
  stack.push(snapshot);
  const MAX_HIGHLIGHT_UNDO_STEPS = 60;
  if (stack.length > MAX_HIGHLIGHT_UNDO_STEPS) {
    stack.splice(0, stack.length - MAX_HIGHLIGHT_UNDO_STEPS);
  }
}

function undoSessionHighlightChange(session, questionId) {
  const key = getSessionHighlightUndoKey(session?.id, questionId);
  const stack = state.sessionHighlightUndo[key];
  if (!stack || !stack.length) {
    return false;
  }
  const response = session.responses?.[questionId];
  if (!response) {
    return false;
  }
  const snapshot = stack.pop();
  if (!stack.length) {
    delete state.sessionHighlightUndo[key];
  }
  applyResponseHighlightSnapshot(response, snapshot);
  session.updatedAt = nowISO();
  upsertSession(session);
  return true;
}

function renderSession() {
  const user = getCurrentUser();
  if (!user) {
    return `
      <section class="panel">
        <h2 class="title">Session unavailable</h2>
        <p class="subtle">Your account is reconnecting. Please wait a moment.</p>
      </section>
    `;
  }
  const session = getActiveSession(user.id, state.sessionId);

  if (!session) {
    return `
      <section class="panel">
        <h2 class="title">No active session</h2>
        <p class="subtle">Create a new test or review completed blocks.</p>
        <div class="stack">
          <button class="btn" data-nav="create-test">Create a test</button>
          <button class="btn ghost" data-nav="review">Review blocks</button>
        </div>
      </section>
    `;
  }

  state.sessionId = session.id;
  persistActiveSessionId(session.id);
  const questionStore = getQuestionStore();
  normalizeSession(session, { questionStore });
  const sessionSnapshot = syncSessionSnapshot(session, {
    questionStore,
    persistOptions: { immediate: true },
  });
  if (sessionSnapshot.finalized) {
    window.setTimeout(() => {
      if (state.route !== "session") {
        return;
      }
      clearTimer();
      toast("Time is up. Session submitted automatically.");
      state.reviewSessionId = session.id;
      state.reviewIndex = 0;
      state.sessionPanel = null;
      navigate("review");
      flushPendingSyncInBackground();
    }, 0);
    return `
      <section class="panel">
        <h2 class="title">Submitting your session...</h2>
        <p class="subtle">Time expired, so we are saving your latest answers and opening review.</p>
      </section>
    `;
  }

  const total = session.questionIds.length;
  if (!total) {
    return `
      <section class="panel">
        <h2 class="title">Session unavailable</h2>
        <p class="subtle">This session no longer has available questions. Create a new test.</p>
        <button class="btn" data-nav="create-test">Create a test</button>
      </section>
    `;
  }
  const currentQid = session.questionIds[session.currentIndex];
  const question = getQuestionForSession(session, currentQid, questionStore);
  const resolvedCurrentQid = resolveSessionQuestionId(currentQid, questionStore);
  const response = session.responses[currentQid] || session.responses[resolvedCurrentQid];
  if (!question || !response) {
    if (user?.role === "student") {
      scheduleStudentBootRefresh(user, {
        rerender: true,
        reason: "session recovery",
        criticalOnly: true,
      }).catch(() => { });
    }
    if (!questionStore.list.length || user?.role === "student") {
      return `
        <section class="panel">
          <h2 class="title">Restoring your saved session...</h2>
          <p class="subtle">Your exam is still stored locally. We are reloading the question bank so you can resume exactly where you left off.</p>
        </section>
      `;
    }
    return `
      <section class="panel">
        <h2 class="title">Session unavailable</h2>
        <p class="subtle">This session could not be recovered. Create a new test.</p>
        <button class="btn" data-nav="create-test">Create a test</button>
      </section>
    `;
  }

  const stemLines = splitStemLines(question.stem);
  const correctChoiceIds = getNormalizedQuestionCorrectChoiceIds(question);
  const choiceType = correctChoiceIds.length > 1 ? "checkbox" : "radio";
  const isSubmitted = response.submitted;
  const isLastQuestion = session.currentIndex >= total - 1;
  const hasAnswer = response.selected.length > 0;
  const isCorrect = isSubmittedResponseCorrect(question, response);
  const markText = isSubmitted && isCorrect ? "1.00" : "0.00";
  const statusText = isSubmitted
    ? "Answer submitted"
    : (hasAnswer ? "Answer saved" : "Not yet answered");
  const markLineText = isSubmitted
    ? `Marked ${markText} out of 1.00`
    : "Marked out of 1.00";
  const normalizedHighlighterColor = normalizeSessionHighlightColor(state.sessionHighlighterColor);
  const shellClassNames = [
    "exam-shell",
    "exam-shell-moodle",
    `font-${state.sessionFontScale}`,
    state.sessionHighContrast ? "high-contrast" : "",
    state.sessionMarkerEnabled ? "marker-on" : "",
    `marker-${normalizedHighlighterColor}`,
  ].filter(Boolean).join(" ");
  const shellStyleAttr = `--exam-font-scale:${getSessionFontScaleCssValue()};`;
  const mappedCourse = getQbankCourseTopicMeta(question).course;
  const questionCourse = String(question.qbankCourse || question.course || "").trim();
  const currentCourse = mappedCourse || questionCourse;
  const askAiUrl = resolveAskAiNotebookUrlForQuestion(question);
  const hasAskAiLink = Boolean(askAiUrl);
  const nativeApp = isNativeAppUi();
  if (nativeApp && state.nativeSessionNavigatorId !== session.id) {
    state.nativeSessionNavigatorId = session.id;
    state.sessionNavCollapsed = true;
  }
  const navCollapsed = Boolean(state.sessionNavCollapsed);
  const answerAction = isSubmitted && isLastQuestion ? "submit-session" : (isSubmitted ? "next-question" : "submit-answer");
  const answerActionLabel = isSubmitted && isLastQuestion ? "Finish and submit" : (isSubmitted ? "Next" : "Check");

  const sideRows = session.questionIds
    .map((qid, index) => {
      const resolvedQuestionId = resolveSessionQuestionId(qid, questionStore);
      const entry = session.responses[qid] || session.responses[resolvedQuestionId];
      const navQuestion = getQuestionForSession(session, qid, questionStore);
      const isSubmittedEntry = Boolean(entry?.submitted);
      const isCorrectEntry = isSubmittedEntry && isSubmittedResponseCorrect(navQuestion, entry);
      const isWrongEntry = isSubmittedEntry && !isCorrectEntry;
      const currentClass = index === session.currentIndex ? "is-current" : "";
      const flaggedClass = entry.flagged ? "is-flagged" : "";
      const answeredClass = entry.selected.length > 0 ? "is-answered" : "";
      const unansweredClass = entry.selected.length === 0 ? "is-unanswered" : "";
      const correctnessClass = isCorrectEntry ? "is-correct" : (isWrongEntry ? "is-wrong" : "");
      const statusLabel = entry.flagged
        ? "flagged"
        : isCorrectEntry
          ? "correct"
          : isWrongEntry
            ? "incorrect"
            : entry.selected.length > 0
              ? "answered"
              : "unanswered";
      return `
        <button
          type="button"
          class="exam-nav-item ${currentClass} ${flaggedClass} ${answeredClass} ${unansweredClass} ${correctnessClass}"
          data-action="jump-question"
          data-index="${index}"
          aria-label="Go to question ${index + 1}, ${statusLabel}"
        >
          <span class="num">${index + 1}</span>
        </button>
      `;
    })
    .join("");

  const choicesHtml = question.choices
    .map((choice) => {
      const selected = response.selected.includes(choice.id);
      const struck = response.struck.includes(choice.id);
      const choiceText = String(choice.text || "");
      const choiceLegacyHighlightColor = normalizeSessionHighlightColor(response.highlightedChoices?.[choice.id], "");
      let choiceHighlightRanges = resolveTextHighlightRanges(response.textHighlights?.choices?.[choice.id], choiceText.length);
      if (!choiceHighlightRanges.length && choiceLegacyHighlightColor && choiceText.length) {
        choiceHighlightRanges = [{ start: 0, end: choiceText.length, color: choiceLegacyHighlightColor }];
      }
      const renderedChoiceText = renderTextWithInlineHighlights(choiceText, choiceHighlightRanges);
      const correctChoice = correctChoiceIds.includes(choice.id);
      const wrongSelected = isSubmitted && selected && !correctChoice;
      const showCorrect = isSubmitted && correctChoice;
      const statusClass = `${showCorrect ? "is-correct" : ""} ${wrongSelected ? "is-user-wrong" : ""}`;
      const statusIndicator = showCorrect
        ? `<span class="exam-choice-indicator good">✓</span>`
        : wrongSelected
          ? `<span class="exam-choice-indicator bad">✕</span>`
          : `<span class="exam-choice-indicator neutral"></span>`;
      const inlineFeedback = isSubmitted && isCorrect && selected && correctChoice
        ? `<span class="exam-choice-inline-note">Excellent! This is the correct answer.</span>`
        : "";
      const choiceInputId = `session-answer-${currentQid}-${choice.id}`;
      return `
        <div class="exam-choice ${selected ? "is-selected" : ""} ${struck ? "is-struck" : ""} ${statusClass}">
          <div class="exam-choice-hit">
            ${statusIndicator}
            <label class="exam-choice-radio-hit" for="${escapeHtml(choiceInputId)}" aria-label="Select answer ${choice.id}">
              <input id="${escapeHtml(choiceInputId)}" type="${choiceType}" name="answer" value="${choice.id}" ${selected ? "checked" : ""} ${isSubmitted ? "disabled" : ""} />
              <span class="exam-choice-radio"></span>
            </label>
            <button
              type="button"
              class="exam-choice-text exam-choice-text-hit"
              data-action="select-choice"
              data-choice-id="${choice.id}"
              ${isSubmitted ? "disabled" : ""}
              aria-label="Select answer ${choice.id}"
            ><b>${choice.id}.</b> <span class="exam-choice-text-body" data-highlight-kind="choice" data-choice-id="${choice.id}">${renderedChoiceText}</span> ${inlineFeedback}</button>
          </div>
          <button
            type="button"
            class="exam-choice-strike ${struck ? "is-active" : ""}"
            data-action="toggle-strike"
            data-choice-id="${choice.id}"
            ${isSubmitted ? "disabled" : ""}
            aria-pressed="${struck ? "true" : "false"}"
            aria-label="${struck ? "Restore" : "Eliminate"} choice ${choice.id}"
            title="${struck ? "Restore this option" : "Eliminate this option"}"
          ><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M16 4H9a3 3 0 0 0-2.83 4"/><path d="M14 12a4 4 0 0 1 0 8H6"/><line x1="4" x2="20" y1="12" y2="12"/></svg></button>
        </div>
      `;
    })
    .join("");

  return `
    <section class="exam-shell-wrap">
      <div class="${shellClassNames}" style="${shellStyleAttr}">
        <section class="exam-main exam-main-simple">
          ${nativeApp ? `
            <header class="native-exam-header">
              <div class="native-exam-header-row">
                <button type="button" class="native-exam-icon-btn" data-nav="dashboard" aria-label="Exit to Practice">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg>
                </button>
                <strong>Question ${session.currentIndex + 1} of ${total}</strong>
                <button type="button" class="native-exam-icon-btn" data-action="toggle-nav-collapse" aria-label="Open question navigator" aria-expanded="${navCollapsed ? "false" : "true"}">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 6h13M8 12h13M8 18h13"/><path d="M3 6h.01M3 12h.01M3 18h.01"/></svg>
                </button>
              </div>
              <div class="native-exam-progress-row">
                <div class="native-exam-progress"><span style="width:${Math.max(4, Math.round(((session.currentIndex + 1) / total) * 100))}%"></span></div>
                <span class="native-exam-time">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>
                  ${session.mode === "timed" ? `<b id="countdown">${formatDuration(Math.max(0, Number(session.timeRemainingSec || 0)))}</b>` : `<b id="elapsed-time">${formatElapsed(Math.max(0, Number(session.elapsedSec || 0)))}</b>`}
                </span>
              </div>
            </header>` : ""}
          <div class="exam-content exam-content-moodle ${navCollapsed ? "is-nav-collapsed" : ""}">
            <aside class="exam-question-meta exam-question-meta-moodle">
              <div class="exam-question-meta-primary">
                <h3 class="exam-question-title-moodle"><span>Question</span> <b>${session.currentIndex + 1}</b></h3>
                <p class="exam-question-status exam-question-status-moodle">${statusText}</p>
                <p class="exam-mark-line exam-mark-line-moodle">${markLineText}</p>
                <button class="exam-meta-link exam-meta-link-moodle" data-action="toggle-flag">
                  <span aria-hidden="true">⚑</span>
                  <span>${response.flagged ? "Unflag question" : "Flag question"}</span>
                </button>
              </div>
            </aside>

            <section class="exam-question-stage">
              <article class="exam-question-block exam-question-card">
                <div class="exam-question-topbar">
                  <button
                    type="button"
                    class="exam-ask-ai-btn"
                    data-action="open-course-ai"
                    title="${hasAskAiLink
      ? (currentCourse ? `Open Ask AI for ${escapeHtml(currentCourse)}` : "Open Ask AI")
      : "Ask AI is unavailable until an admin assigns a link."}"
                    ${hasAskAiLink ? "" : "disabled"}
                  >
                    <span class="exam-ask-ai-spark" aria-hidden="true">✦</span>
                    <span>Ask AI</span>
                  </button>
                  <button
                    type="button"
                    class="exam-copy-question-btn"
                    data-action="copy-course-ai-question"
                    title="Copy this question for Ask AI"
                  >
                    Copy question
                  </button>
                </div>
                ${renderQuestionStemVisual(question, { loading: "eager" })}
                <div class="exam-stem">
                  ${stemLines
      .map((line, index) => {
        const lineText = String(line || "");
        const lineHighlightColor = normalizeSessionHighlightColor(response.highlightedLineColors?.[index], "");
        let lineHighlightRanges = resolveTextHighlightRanges(response.textHighlights?.lines?.[index], lineText.length);
        if (!lineHighlightRanges.length && lineHighlightColor && lineText.length) {
          lineHighlightRanges = [{ start: 0, end: lineText.length, color: lineHighlightColor }];
        }
        return `<p class="exam-line" data-highlight-kind="line" data-line-index="${index}" title="Select text to highlight">${renderTextWithInlineHighlights(lineText, lineHighlightRanges)}</p>`;
      })
      .join("")}
                </div>

                <div class="exam-answers">
                  ${choicesHtml}
                </div>

                ${nativeApp ? `
                  <div class="native-exam-actions">
                    <button type="button" class="native-exam-action-secondary" data-action="prev-question" ${session.currentIndex <= 0 ? "disabled" : ""}>
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg><span>Previous</span>
                    </button>
                    <button type="button" class="native-exam-action-secondary ${response.flagged ? "is-active" : ""}" data-action="toggle-flag" aria-pressed="${response.flagged ? "true" : "false"}">
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 21V4"/><path d="M5 4h12l-2 4 2 4H5"/></svg><span>Flag</span>
                    </button>
                    <button type="button" class="btn exam-submit-btn" data-action="${answerAction}">${answerActionLabel === "Check" ? "Check Answer" : answerActionLabel}</button>
                  </div>` : `
                  <div class="exam-answer-actions">
                    <button class="btn exam-submit-btn" data-action="${answerAction}">${answerActionLabel}</button>
                  </div>`}
              </article>
              ${isSubmitted ? renderInlineExplanationPane(question, isCorrect) : ""}
            </section>

            <aside class="exam-nav-panel ${navCollapsed ? "is-collapsed" : ""}" aria-hidden="${navCollapsed ? "true" : "false"}" ${navCollapsed ? "inert" : ""}>
              <div class="exam-nav-panel-head">
                <h3>Quiz navigation</h3>
                <div class="exam-nav-head-actions">
                  <button
                    type="button"
                    class="exam-nav-collapse-toggle"
                    data-action="toggle-nav-collapse"
                    aria-label="Hide quiz navigation"
                    aria-expanded="true"
                    title="Hide quiz navigation"
                  >
                    <span aria-hidden="true">›</span>
                  </button>
                  <button
                    type="button"
                    class="exam-nav-settings-toggle ${state.sessionNavSettingsOpen ? "is-open" : ""}"
                    data-action="toggle-nav-settings"
                    aria-label="Open block settings"
                    aria-expanded="${state.sessionNavSettingsOpen ? "true" : "false"}"
                    aria-controls="session-settings-drawer"
                    title="Block settings"
                  >
                    <span class="bar" aria-hidden="true"></span>
                    <span class="bar" aria-hidden="true"></span>
                    <span class="bar" aria-hidden="true"></span>
                  </button>
                </div>
              </div>
              <div class="exam-nav-grid">${sideRows}</div>
              <button class="exam-nav-link" data-action="submit-session">Submit all and finish</button>
            </aside>
            ${nativeApp ? `<button type="button" class="native-exam-sheet-backdrop ${navCollapsed ? "" : "is-open"}" data-action="toggle-nav-collapse" aria-label="Close question navigator"></button>` : ""}
            ${navCollapsed ? `<button
              type="button"
              class="exam-nav-edge-toggle is-visible"
              data-action="toggle-nav-collapse"
              aria-label="Show quiz navigation"
              aria-expanded="false"
              title="Show quiz navigation"
            >
              <span aria-hidden="true">‹</span>
            </button>` : ""}
            <button
              type="button"
              class="exam-nav-settings-backdrop ${state.sessionNavSettingsOpen ? "is-open" : ""}"
              data-action="toggle-nav-settings"
              aria-label="Close block settings"
              aria-hidden="${state.sessionNavSettingsOpen ? "false" : "true"}"
            ></button>
            <aside
              id="session-settings-drawer"
              class="exam-nav-settings-drawer ${state.sessionNavSettingsOpen ? "is-open" : ""}"
              aria-hidden="${state.sessionNavSettingsOpen ? "false" : "true"}"
              ${state.sessionNavSettingsOpen ? "" : "inert"}
            >
              <div class="exam-nav-settings-drawer-head">
                <h4>Block settings</h4>
                <button
                  type="button"
                  class="btn ghost exam-nav-settings-close"
                  data-action="toggle-nav-settings"
                  aria-label="Close block settings"
                >Close</button>
              </div>
              ${renderSessionNavSettings()}
            </aside>
          </div>
        </section>
      </div>
    </section>
  `;
}

function getCurrentSessionResponseContext(session) {
  if (!session || !Array.isArray(session.questionIds)) {
    return null;
  }
  const qid = String(session.questionIds[session.currentIndex] || "").trim();
  if (!qid) {
    return null;
  }
  const resolvedQuestionId = resolveSessionQuestionId(qid);
  const response = session.responses && typeof session.responses === "object"
    ? (session.responses[qid] || session.responses[resolvedQuestionId])
    : null;
  if (!response || typeof response !== "object" || Array.isArray(response)) {
    return null;
  }
  return { qid: resolvedQuestionId || qid, response };
}

function syncActiveResponseSelectionFromDom(activeSession) {
  const currentContext = getCurrentSessionResponseContext(activeSession);
  if (!currentContext) {
    return [];
  }
  const selected = [...new Set(
    Array.from(appEl.querySelectorAll("input[name='answer']:checked"))
      .map((entry) => String(entry.value || "").trim().toUpperCase())
      .filter(Boolean),
  )];
  currentContext.response.selected = selected;
  return selected;
}

function wireSession() {
  const user = getCurrentUser();
  if (!user) {
    return;
  }
  const session = getActiveSession(user.id, state.sessionId);
  if (!session) {
    return;
  }

  const questionStore = getQuestionStore();
  normalizeSession(session, { questionStore });
  const sessionSnapshot = syncSessionSnapshot(session, {
    questionStore,
    persistOptions: { immediate: true },
  });
  if (sessionSnapshot.finalized) {
    clearTimer();
    state.reviewSessionId = session.id;
    state.reviewIndex = 0;
    state.sessionPanel = null;
    navigate("review");
    flushPendingSyncInBackground();
    return;
  }

  if (!session.lastQuestionAt) {
    session.lastQuestionAt = Date.now();
    upsertSession(session);
  }

  warmSessionQuestionAssets(session, questionStore);
  startSessionTicker(session.id);
  syncSessionTimingDisplays(session);
  syncSessionUiControlsInDom();

  const fontScaleSlider = document.getElementById("session-font-scale-slider");
  fontScaleSlider?.addEventListener("input", () => {
    const nextPercent = normalizeSessionFontScalePercent(fontScaleSlider.value, state.sessionFontScalePercent);
    setSessionFontScalePercent(nextPercent);
    syncSessionUiControlsInDom();
  });

  const answerInputs = appEl.querySelectorAll("input[name='answer']");
  answerInputs.forEach((input) => {
    input.addEventListener("change", () => {
      const latest = getSessionById(session.id);
      if (!latest || latest.status !== "in_progress") {
        return;
      }

      normalizeSession(latest, { questionStore: getQuestionStore() });
      const currentContext = getCurrentSessionResponseContext(latest);
      if (!currentContext) {
        state.skipNextRouteAnimation = true;
        render();
        return;
      }
      syncActiveResponseSelectionFromDom(latest);
      currentContext.response.submitted = false;
      latest.updatedAt = nowISO();
      upsertSession(latest);
      state.skipNextRouteAnimation = true;
      render();
    });
  });

  appEl.removeEventListener("click", handleSessionClick);
  appEl.addEventListener("click", handleSessionClick);
  document.removeEventListener("keydown", handleSessionKeydown);
  document.addEventListener("keydown", handleSessionKeydown);
  document.removeEventListener("mouseup", handleSessionHighlighterMouseup);
  document.addEventListener("mouseup", handleSessionHighlighterMouseup);

  const noteInput = document.getElementById("session-note-panel");
  noteInput?.addEventListener("input", () => {
    const latest = getSessionById(session.id);
    if (!latest || latest.status !== "in_progress") {
      return;
    }

    normalizeSession(latest, { questionStore: getQuestionStore() });
    const currentContext = getCurrentSessionResponseContext(latest);
    if (!currentContext) {
      state.skipNextRouteAnimation = true;
      render();
      return;
    }
    currentContext.response.notes = noteInput.value;
    latest.updatedAt = nowISO();
    upsertSession(latest);
  });

  const feedbackForm = document.getElementById("feedback-form");
  feedbackForm?.addEventListener("submit", (event) => {
    event.preventDefault();
    const latest = getSessionById(session.id);
    if (!latest || latest.status !== "in_progress") {
      return;
    }

    const input = document.getElementById("feedback-input");
    const message = String(input?.value || "").trim();
    if (!message) {
      toast("Write feedback first.");
      return;
    }

    const feedback = load(STORAGE_KEYS.feedback, []);
    feedback.push({
      id: makeId("fb"),
      userId: latest.userId,
      sessionId: latest.id,
      questionId: latest.questionIds[latest.currentIndex],
      message,
      createdAt: nowISO(),
    });
    save(STORAGE_KEYS.feedback, feedback);
    state.sessionPanel = null;
    toast("Feedback submitted.");
    render();
  });
}

async function handleSessionClick(event) {
  const target = event.target.closest("[data-action]");
  if (!target) {
    return;
  }

  const action = target.getAttribute("data-action");
  const user = getCurrentUser();
  if (!user) {
    return;
  }
  const session = getActiveSession(user.id, state.sessionId);
  if (!session) {
    return;
  }

  const questionStore = getQuestionStore();
  normalizeSession(session, { questionStore });
  syncActiveResponseSelectionFromDom(session);
  const currentContext = getCurrentSessionResponseContext(session);

  const maxIndex = session.questionIds.length - 1;
  const trackedActions = new Set(["prev-question", "next-question", "jump-question", "jump-unanswered", "save-exit", "submit-session"]);
  const shouldTrackElapsed = trackedActions.has(action);
  if (shouldTrackElapsed) {
    captureElapsedForCurrentQuestion(session);
    if (session.mode === "timed" && Number(session.timeRemainingSec || 0) <= 0) {
      finalizeSession(session.id, {
        sessionOverride: session,
        questionStore,
        skipElapsedCapture: true,
      });
      clearTimer();
      toast("Time is up. Session submitted automatically.");
      state.reviewSessionId = session.id;
      state.reviewIndex = 0;
      state.sessionPanel = null;
      navigate("review");
      return;
    }
  }

  if (action === "toggle-fullscreen") {
    toggleSessionFullscreen();
    return;
  }

  if (action === "open-shortcuts") {
    toggleSessionPanel("shortcuts");
    return;
  }

  if (action === "open-labs") {
    toggleSessionPanel("labs");
    return;
  }

  if (action === "open-notes") {
    toggleSessionPanel("notes");
    return;
  }

  if (action === "open-calculator") {
    toggleSessionPanel("calculator");
    return;
  }

  if (action === "open-settings") {
    toggleSessionPanel("settings");
    return;
  }

  if (action === "toggle-nav-settings") {
    state.sessionNavSettingsOpen = !state.sessionNavSettingsOpen;
    render();
    return;
  }

  if (action === "toggle-nav-collapse") {
    state.sessionNavCollapsed = !state.sessionNavCollapsed;
    if (state.sessionNavCollapsed) {
      state.sessionNavSettingsOpen = false;
    }
    persistSessionUiPreferences();
    render();
    return;
  }

  if (action === "decrease-session-font" || action === "increase-session-font") {
    const delta = action === "increase-session-font" ? SESSION_FONT_SCALE_STEP : -SESSION_FONT_SCALE_STEP;
    setSessionFontScalePercent(state.sessionFontScalePercent + delta);
    syncSessionUiControlsInDom();
    return;
  }

  if (action === "set-highlighter-color") {
    const requested = normalizeSessionHighlightColor(target.getAttribute("data-color"), state.sessionHighlighterColor);
    if (state.sessionHighlighterColor !== requested) {
      state.sessionHighlighterColor = requested;
      persistSessionUiPreferences();
      render();
      return;
    }
    return;
  }

  if (action === "reset-session-ui-settings") {
    state.sessionMarkerEnabled = false;
    state.sessionHighlighterColor = SESSION_HIGHLIGHTER_DEFAULT;
    state.sessionHighContrast = false;
    setSessionFontScalePercent(SESSION_FONT_SCALE_DEFAULT, { force: true });
    toast("Block settings reset.");
    render();
    return;
  }

  if (action === "open-library") {
    toggleSessionPanel("library");
    return;
  }

  if (action === "open-notebook") {
    toggleSessionPanel("notebook");
    return;
  }

  if (action === "open-feedback") {
    toggleSessionPanel("feedback");
    return;
  }

  if (action === "open-ai-tutor") {
    toggleSessionPanel("aiTutor");
    return;
  }

  if (action === "open-course-ai") {
    const qid = currentContext?.qid;
    if (!qid) {
      state.skipNextRouteAnimation = true;
      render();
      return;
    }
    const question = getQuestionForSession(session, qid, questionStore);
    if (!question) {
      toast("Current question could not be loaded.");
      return;
    }
    const notebookUrl = resolveAskAiNotebookUrlForQuestion(question);
    if (!notebookUrl) {
      toast("Ask AI is unavailable until an admin assigns a link.");
      return;
    }
    const opened = openAskAiNotebook(notebookUrl);
    if (!opened) {
      toast("Popup blocked, so Ask AI tab did not open. Allow popups and try again.");
    }
    return;
  }

  if (action === "copy-course-ai-question") {
    const qid = currentContext?.qid;
    if (!qid) {
      state.skipNextRouteAnimation = true;
      render();
      return;
    }
    const question = getQuestionForSession(session, qid, questionStore);
    if (!question) {
      toast("Current question could not be loaded.");
      return;
    }
    const promptText = buildAskAiPromptText(question);
    const copied = await copyTextToClipboard(promptText);
    toast(copied
      ? "Question copied. Paste in Ask AI with Ctrl/Cmd+V."
      : "Could not auto-copy. Please copy and paste manually.");
    return;
  }

  if (action === "close-session-panel") {
    state.sessionPanel = null;
    render();
    return;
  }

  if (action === "toggle-marker-mode") {
    state.sessionMarkerEnabled = !state.sessionMarkerEnabled;
    persistSessionUiPreferences();
    toast(state.sessionMarkerEnabled ? "Highlighter enabled." : "Highlighter disabled.");
    render();
    return;
  }

  if (action === "set-font-scale") {
    const scale = target.getAttribute("data-scale");
    if (["compact", "normal", "large"].includes(scale)) {
      const mappedPercent = scale === "compact" ? 90 : scale === "large" ? 112 : SESSION_FONT_SCALE_DEFAULT;
      setSessionFontScalePercent(mappedPercent);
      syncSessionUiControlsInDom();
    }
    return;
  }

  if (action === "toggle-contrast") {
    state.sessionHighContrast = !state.sessionHighContrast;
    persistSessionUiPreferences();
    render();
    return;
  }

  if (action === "calc-input") {
    const value = target.getAttribute("data-value") || "";
    applyCalculatorInput(value);
    render();
    return;
  }

  if (action === "calc-clear") {
    state.calcExpression = "";
    render();
    return;
  }

  if (action === "calc-delete") {
    state.calcExpression = state.calcExpression.slice(0, -1);
    render();
    return;
  }

  if (action === "calc-eval") {
    evaluateCalculator();
    render();
    return;
  }

  if (action === "add-flashcard") {
    if (!currentContext?.qid) {
      state.skipNextRouteAnimation = true;
      render();
      return;
    }
    addCurrentQuestionToFlashcards(session.userId, currentContext.qid);
    toast("Added to flashcards.");
    return;
  }

  if (action === "toggle-line-highlight") {
    return;
  }

  if (action === "prev-question") {
    session.currentIndex = Math.max(0, session.currentIndex - 1);
  }

  if (action === "next-question") {
    session.currentIndex = Math.min(maxIndex, session.currentIndex + 1);
  }

  if (action === "jump-question") {
    const index = Number(target.getAttribute("data-index") || 0);
    session.currentIndex = Math.min(maxIndex, Math.max(0, index));
  }

  if (action === "jump-unanswered") {
    const unansweredIndex = session.questionIds.findIndex((qid) => {
      const resolvedQuestionId = resolveSessionQuestionId(qid, questionStore);
      const response = session.responses[qid] || session.responses[resolvedQuestionId];
      return !Array.isArray(response?.selected) || response.selected.length === 0;
    });
    if (unansweredIndex === -1) {
      toast("All questions are answered.");
      return;
    }
    session.currentIndex = unansweredIndex;
  }

  if (action === "toggle-flag") {
    if (!currentContext) {
      state.skipNextRouteAnimation = true;
      render();
      return;
    }
    currentContext.response.flagged = !currentContext.response.flagged;
  }

  if (action === "select-choice") {
    const choiceId = normalizeQuestionChoiceLabel(target.getAttribute("data-choice-id"));
    if (!choiceId) {
      return;
    }
    if (!currentContext) {
      state.skipNextRouteAnimation = true;
      render();
      return;
    }
    if (currentContext.response.submitted) {
      return;
    }
    // Ignore the click that ends a text-highlight drag on this choice.
    if (shouldSuppressStrikeClick(session.id, currentContext.qid, choiceId)) {
      return;
    }
    const choiceInput = Array.from(appEl.querySelectorAll("input[name='answer']"))
      .find((entry) => String(entry.value || "").trim().toUpperCase() === choiceId);
    if (!choiceInput || choiceInput.disabled) {
      return;
    }
    if (choiceInput.type === "checkbox") {
      choiceInput.checked = !choiceInput.checked;
    } else {
      choiceInput.checked = true;
    }
    syncActiveResponseSelectionFromDom(session);
    currentContext.response.submitted = false;
    session.updatedAt = nowISO();
    upsertSession(session);
    state.skipNextRouteAnimation = true;
    render();
    return;
  }

  if (action === "toggle-strike") {
    const choiceId = normalizeQuestionChoiceLabel(target.getAttribute("data-choice-id"));
    if (!choiceId) {
      return;
    }
    if (!currentContext) {
      state.skipNextRouteAnimation = true;
      render();
      return;
    }
    const qid = currentContext.qid;
    const response = currentContext.response;
    if (shouldSuppressStrikeClick(session.id, qid, choiceId)) {
      return;
    }
    if (response.struck.includes(choiceId)) {
      response.struck = response.struck.filter((entry) => entry !== choiceId);
    } else {
      response.struck.push(choiceId);
    }
  }

  if (action === "toggle-pause") {
    session.paused = !session.paused;
    session.lastTimerSyncAt = Date.now();
    toast(session.paused ? "Timer paused." : "Timer resumed.");
  }

  if (action === "submit-answer") {
    if (!currentContext) {
      state.skipNextRouteAnimation = true;
      render();
      return;
    }
    const qid = currentContext.qid;
    const response = currentContext.response;
    if (response.submitted) {
      captureElapsedForCurrentQuestion(session);
      session.currentIndex = Math.min(maxIndex, session.currentIndex + 1);
      session.updatedAt = nowISO();
      upsertSession(session);
      render();
      return;
    }
    if (!response.selected.length) {
      toast("Select an answer before submitting.");
      return;
    }
    response.submitted = true;
    const question = getQuestionForSession(session, qid, questionStore);
    const correct = isSubmittedResponseCorrect(question, response);
    if (!correct) {
      addQuestionToIncorrectQueue(session.userId, qid);
    }
    toast(correct ? "Correct." : "Incorrect.");
  }

  if (action === "reset-answer") {
    if (!currentContext) {
      state.skipNextRouteAnimation = true;
      render();
      return;
    }
    currentContext.response.submitted = false;
    state.sessionPanel = null;
  }

  if (action === "save-exit") {
    persistInProgressSessionSnapshot({
      session,
      user,
      immediate: true,
    });
    await flushPendingSyncNow({ throwOnRelationalFailure: false }).catch(() => { });
    appEl.removeEventListener("click", handleSessionClick);
    document.removeEventListener("keydown", handleSessionKeydown);
    document.removeEventListener("mouseup", handleSessionHighlighterMouseup);
    state.sessionPanel = null;
    navigate("create-test");
    toast("Session suspended.");
    return;
  }

  if (action === "submit-session") {
    const unansweredQuestionNumbers = session.questionIds
      .map((qid, index) => {
        const resolvedQuestionId = resolveSessionQuestionId(qid, questionStore);
        return { index, response: session.responses[qid] || session.responses[resolvedQuestionId] };
      })
      .filter(({ response }) => !Array.isArray(response?.selected) || response.selected.length === 0)
      .map(({ index }) => index + 1);
    if (unansweredQuestionNumbers.length) {
      const preview = unansweredQuestionNumbers.slice(0, 15).join(", ");
      const moreCount = unansweredQuestionNumbers.length - Math.min(unansweredQuestionNumbers.length, 15);
      const suffix = moreCount > 0 ? ` (+${moreCount} more)` : "";
      const confirmed = window.confirm(
        `Questions ${preview}${suffix} are not submitted (no answer selected). Submit all and finish anyway?`,
      );
      if (!confirmed) {
        return;
      }
    }

    session.questionIds.forEach((qid) => {
      const resolvedQuestionId = resolveSessionQuestionId(qid, questionStore);
      const response = session.responses[qid] || session.responses[resolvedQuestionId];
      if (response?.selected?.length) {
        response.submitted = true;
      }
    });
    finalizeSession(session.id, { questionStore });
    let syncWarning = "";
    try {
      await flushPendingSyncNow({ throwOnRelationalFailure: true });
    } catch (error) {
      console.warn("Could not persist completed block before opening review.", error?.message || error);
      syncWarning = "Block submitted locally, but cloud sync has not finished yet. Keep this tab open until sync completes.";
    }
    if (!syncWarning && hasUnresolvedSessionCloudSync(session.id)) {
      syncWarning = "Block submitted locally, but cloud sync is still pending. Keep this tab open until sync completes.";
    }
    appEl.removeEventListener("click", handleSessionClick);
    document.removeEventListener("keydown", handleSessionKeydown);
    document.removeEventListener("mouseup", handleSessionHighlighterMouseup);
    state.sessionPanel = null;
    state.reviewSessionId = session.id;
    state.reviewIndex = 0;
    navigate("review");
    toast(syncWarning || "Block submitted.");
    return;
  }

  session.updatedAt = nowISO();
  upsertSession(session, {
    immediate: action === "submit-answer",
  });
  render();
}

function handleSessionKeydown(event) {
  if (state.route !== "session") {
    return;
  }

  const activeTag = document.activeElement?.tagName;
  const isUndoShortcut = (event.key === "z" || event.key === "Z") && (event.metaKey || event.ctrlKey) && !event.altKey;
  if (isUndoShortcut) {
    if (["INPUT", "TEXTAREA", "SELECT"].includes(activeTag)) {
      return;
    }
    event.preventDefault();
    const user = getCurrentUser();
    if (!user) {
      return;
    }
    const session = getActiveSession(user.id, state.sessionId);
    if (!session || session.status !== "in_progress") {
      return;
    }
    normalizeSession(session, { questionStore: getQuestionStore() });
    const questionId = session.questionIds[session.currentIndex];
    if (!questionId) {
      return;
    }
    const undone = undoSessionHighlightChange(session, questionId);
    if (!undone) {
      toast("No highlight step to undo.");
      return;
    }
    toast("Highlight undone.");
    render();
    return;
  }
  if (["INPUT", "TEXTAREA", "SELECT"].includes(activeTag) && event.key !== "Escape") {
    return;
  }
  if (event.metaKey || event.ctrlKey || event.altKey) {
    return;
  }

  if (/^[1-5]$/.test(event.key)) {
    const index = Number(event.key) - 1;
    const choiceInput = appEl.querySelectorAll("input[name='answer']")[index];
    if (choiceInput) {
      choiceInput.checked = true;
      choiceInput.dispatchEvent(new Event("change"));
      event.preventDefault();
    }
    return;
  }

  if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
    event.preventDefault();
    const user = getCurrentUser();
    if (!user) {
      return;
    }
    const session = getActiveSession(user.id, state.sessionId);
    if (!session || session.status !== "in_progress") {
      return;
    }
    const questionStore = getQuestionStore();
    normalizeSession(session, { questionStore });
    syncActiveResponseSelectionFromDom(session);
    captureElapsedForCurrentQuestion(session);
    const maxIndex = Math.max(0, session.questionIds.length - 1);
    if (event.key === "ArrowLeft") {
      session.currentIndex = Math.max(0, session.currentIndex - 1);
    } else {
      session.currentIndex = Math.min(maxIndex, session.currentIndex + 1);
    }
    session.updatedAt = nowISO();
    upsertSession(session);
    render();
    return;
  }

  // Only map shortcuts whose target controls actually exist in the current
  // session UI. The notes/labs/calculator/shortcuts tool panels are not
  // rendered, so their keys were silent no-ops and have been removed.
  const mapped = {
    f: "toggle-flag",
    m: "toggle-marker-mode",
    s: "submit-answer",
  };

  if (event.key === "Escape") {
    if (state.sessionPanel) {
      state.sessionPanel = null;
      render();
      event.preventDefault();
    }
    return;
  }

  const action = mapped[event.key] || mapped[event.key.toLowerCase()];
  if (!action) {
    return;
  }

  event.preventDefault();
  appEl.querySelector(`[data-action="${action}"]`)?.click();
}

function handleSessionHighlighterMouseup() {
  if (state.route !== "session" || !state.sessionMarkerEnabled) {
    return;
  }
  const selection = window.getSelection?.();
  if (!selection || selection.rangeCount === 0 || selection.isCollapsed) {
    return;
  }
  const selectedText = String(selection.toString() || "");
  if (!selectedText.trim()) {
    selection.removeAllRanges();
    return;
  }
  const range = selection.getRangeAt(0);
  const startTarget = getHighlightTargetFromNode(range.startContainer);
  const endTarget = getHighlightTargetFromNode(range.endContainer);
  if (
    !startTarget
    || !endTarget
    || startTarget.kind !== endTarget.kind
    || startTarget.key !== endTarget.key
  ) {
    selection.removeAllRanges();
    return;
  }
  const offsets = getSelectionOffsetsWithinElement(range, startTarget.element);
  selection.removeAllRanges();
  if (!offsets) {
    return;
  }
  const user = getCurrentUser();
  if (!user) {
    return;
  }
  const session = getActiveSession(user.id, state.sessionId);
  if (!session || session.status !== "in_progress") {
    return;
  }
  normalizeSession(session, { questionStore: getQuestionStore() });
  const qid = session.questionIds[session.currentIndex];
  const resolvedQuestionId = resolveSessionQuestionId(qid);
  const response = session.responses[qid] || session.responses[resolvedQuestionId];
  if (!response) {
    return;
  }
  const textLength = Math.max(0, String(startTarget.element.textContent || "").length);
  if (!textLength) {
    return;
  }
  const highlightStore = ensureResponseTextHighlightStore(response);
  const activeColor = normalizeSessionHighlightColor(state.sessionHighlighterColor);
  pushSessionHighlightUndoSnapshot(session.id, qid, response);
  state.sessionPendingHighlightSelection = null;
  if (startTarget.kind === "line") {
    const lineKey = startTarget.key;
    const lineRanges = updateHighlightRangesWithSelection(
      highlightStore.lines[lineKey],
      offsets.start,
      offsets.end,
      activeColor,
      textLength,
    );
    const lineIndex = Math.floor(Number(lineKey));
    if (!Array.isArray(response.highlightedLines)) {
      response.highlightedLines = [];
    }
    if (!response.highlightedLineColors || typeof response.highlightedLineColors !== "object" || Array.isArray(response.highlightedLineColors)) {
      response.highlightedLineColors = {};
    }
    if (lineRanges.length) {
      highlightStore.lines[lineKey] = lineRanges;
      if (!response.highlightedLines.includes(lineIndex)) {
        response.highlightedLines.push(lineIndex);
      }
      const primaryColor = getPrimaryHighlightColorFromRanges(lineRanges) || activeColor;
      response.highlightedLineColors[lineIndex] = primaryColor;
    } else {
      delete highlightStore.lines[lineKey];
      response.highlightedLines = response.highlightedLines.filter((entry) => entry !== lineIndex);
      delete response.highlightedLineColors[lineIndex];
    }
  } else if (startTarget.kind === "choice") {
    const choiceKey = startTarget.key;
    state.sessionPendingHighlightSelection = {
      kind: "choice",
      sessionId: session.id,
      questionId: qid,
      choiceId: choiceKey,
      expiresAt: Date.now() + 400,
    };
    const choiceRanges = updateHighlightRangesWithSelection(
      highlightStore.choices[choiceKey],
      offsets.start,
      offsets.end,
      activeColor,
      textLength,
    );
    if (!response.highlightedChoices || typeof response.highlightedChoices !== "object" || Array.isArray(response.highlightedChoices)) {
      response.highlightedChoices = {};
    }
    if (choiceRanges.length) {
      highlightStore.choices[choiceKey] = choiceRanges;
      const primaryColor = getPrimaryHighlightColorFromRanges(choiceRanges) || activeColor;
      response.highlightedChoices[choiceKey] = primaryColor;
    } else {
      delete highlightStore.choices[choiceKey];
      delete response.highlightedChoices[choiceKey];
    }
  }
  session.updatedAt = nowISO();
  upsertSession(session);
  render();
}

function startSessionTicker(sessionId) {
  clearTimer();
  const initialSession = getSessionById(sessionId);
  if (initialSession) {
    syncSessionTimingDisplays(initialSession);
  }

  timerHandle = window.setInterval(() => {
    const session = getSessionById(sessionId);
    if (!session || session.status !== "in_progress") {
      clearTimer();
      return;
    }

    if (session.paused) {
      syncSessionTimingDisplays(session);
      return;
    }

    const clockState = syncSessionSnapshot(session, {
      questionStore: getQuestionStore(),
    });
    syncSessionTimingDisplays(session);

    if (clockState.finalized) {
      clearTimer();
      toast("Time is up. Session submitted automatically.");
      state.reviewSessionId = session.id;
      state.reviewIndex = 0;
      state.sessionPanel = null;
      navigate("review");
      flushPendingSyncInBackground();
    }
  }, 1000);
}

function clearTimer() {
  if (timerHandle) {
    window.clearInterval(timerHandle);
    timerHandle = null;
  }
}

function finalizeSession(sessionId, options = {}) {
  const session = options?.sessionOverride && String(options.sessionOverride?.id || "").trim() === String(sessionId || "").trim()
    ? options.sessionOverride
    : getSessionById(sessionId);
  if (!session) {
    return;
  }
  const questionStore = options?.questionStore || getQuestionStore();
  if (options?.skipElapsedCapture !== true) {
    captureElapsedForCurrentQuestion(session);
  }

  const currentUser = getCurrentUser();
  const currentSessionProfileId = String(getCurrentSessionProfileId(currentUser) || "").trim();
  if (currentUser && currentUser.role === "student") {
    session.userId = String(currentUser?.id || session.userId || "").trim();
    if (isUuidValue(currentSessionProfileId)) {
      session.ownerProfileId = currentSessionProfileId;
      session.ownerAuthId = currentSessionProfileId;
    }
    session.ownerIds = normalizeSessionOwnerIdList([
      ...(Array.isArray(session?.ownerIds) ? session.ownerIds : []),
      session?.userId,
      session?.ownerProfileId,
      session?.ownerAuthId,
      ...getStoredUserIdentityAliases(currentUser),
      currentSessionProfileId,
    ]);
  }

  session.status = "completed";
  session.completedAt = nowISO();
  session.paused = false;
  session.updatedAt = nowISO();
  upsertSession(session, { immediate: true });

  const incorrectMap = load(STORAGE_KEYS.incorrectQueue, {});
  const userQueue = new Set(incorrectMap[session.userId] || []);

  for (const qid of session.questionIds) {
    const resolvedQuestionId = resolveSessionQuestionId(qid, questionStore);
    const question = getQuestionForSession(session, qid, questionStore);
    const response = session.responses[qid] || session.responses[resolvedQuestionId];
    const correct = isSubmittedResponseCorrect(question, response);
    if (!correct) {
      userQueue.add(resolvedQuestionId || qid);
    }
  }

  incorrectMap[session.userId] = [...userQueue];
  save(STORAGE_KEYS.incorrectQueue, incorrectMap);
  clearPersistedActiveSessionId(session.id);
}

function finalizeActiveSessionsForUser(userId) {
  const targetUserId = String(userId || "").trim();
  if (!targetUserId) {
    return [];
  }
  const activeSessions = getSessionsForUser(targetUserId)
    .filter((session) => String(session?.status || "").trim() === "in_progress")
    .sort((a, b) => new Date(b.updatedAt || b.createdAt || 0) - new Date(a.updatedAt || a.createdAt || 0));
  if (!activeSessions.length) {
    return [];
  }

  const finalizedIds = [];
  activeSessions.forEach((session) => {
    const sessionId = String(session?.id || "").trim();
    if (!sessionId) {
      return;
    }
    finalizeSession(sessionId);
    finalizedIds.push(sessionId);
  });

  if (finalizedIds.includes(String(state.sessionId || "").trim())) {
    state.sessionId = null;
  }
  return finalizedIds;
}

function addQuestionToIncorrectQueue(userId, questionId) {
  if (!userId || !questionId) {
    return;
  }
  const incorrectMap = load(STORAGE_KEYS.incorrectQueue, {});
  const userQueue = new Set(incorrectMap[userId] || []);
  userQueue.add(questionId);
  incorrectMap[userId] = [...userQueue];
  save(STORAGE_KEYS.incorrectQueue, incorrectMap);
}

function renderReview() {
  const user = getCurrentUser();
  const completedSessions = getReviewableCompletedSessionsForUser(user, {
    userOverride: user,
    fallbackToAllTerms: true,
  });

  if (!completedSessions.length) {
    return `
      <section class="panel">
        <h2 class="title">Review</h2>
        <p class="subtle">No completed blocks yet.</p>
        <button class="btn" data-nav="create-test">Create your first test</button>
      </section>
    `;
  }

  const selected =
    completedSessions.find((session) => session.id === state.reviewSessionId) || completedSessions[0];
  state.reviewSessionId = selected.id;
  const questionStore = getQuestionStore();
  normalizeSession(selected, { questionStore });

  const reviewedEntries = selected.questionIds.map((qid) => {
    const resolvedQuestionId = resolveSessionQuestionId(qid, questionStore);
    const question = getQuestionForSession(selected, qid, questionStore);
    const response = selected.responses[qid] || selected.responses[resolvedQuestionId] || {
      selected: [],
      flagged: false,
      struck: [],
      notes: "",
      timeSpentSec: 0,
      highlightedLines: [],
      highlightedLineColors: {},
      highlightedChoices: {},
      textHighlights: buildEmptyTextHighlightStore(),
      submitted: true,
    };
    const hasAnswer = response.selected.length > 0;
    const isCorrect = isSubmittedResponseCorrect(question, response);
    const isWrong = Boolean(question && !isCorrect);
    return { qid, question, response, hasAnswer, isCorrect, isWrong };
  });

  const total = reviewedEntries.length;
  const correctCount = reviewedEntries.filter((entry) => entry.isCorrect).length;
  const accuracy = total ? Math.round((correctCount / total) * 100) : 0;

  if (!Number.isFinite(state.reviewIndex)) {
    state.reviewIndex = 0;
  }
  state.reviewIndex = Math.max(0, Math.min(total - 1, Math.floor(state.reviewIndex)));
  const current = reviewedEntries[state.reviewIndex];
  if (!current) {
    return `
      <section class="panel">
        <h2 class="title">Review</h2>
        <p class="subtle">This block has no questions to review.</p>
        <button class="btn" data-nav="create-test">Create a new test</button>
      </section>
    `;
  }

  const question = current.question;
  const response = current.response;
  const isCorrect = current.isCorrect;
  const markText = isCorrect ? "1.00" : "0.00";
  const statusText = isCorrect ? "Correct" : "Incorrect";
  const stemLines = splitStemLines(question?.stem || "Question content is not available.");
  const correctChoiceIds = Array.isArray(question?.correct) ? question.correct : [];
  const questionChoices = Array.isArray(question?.choices) ? question.choices : [];
  const choiceType = question && correctChoiceIds.length > 1 ? "checkbox" : "radio";
  const reviewShellClassNames = [
    "exam-shell",
    "exam-shell-moodle",
    `font-${state.sessionFontScale}`,
    state.sessionHighContrast ? "high-contrast" : "",
    `marker-${normalizeSessionHighlightColor(state.sessionHighlighterColor)}`,
  ].filter(Boolean).join(" ");
  const reviewShellStyleAttr = `--exam-font-scale:${getSessionFontScaleCssValue()};`;
  const sessionName = getSessionDisplayName(selected);
  const sessionTestId = getSessionDisplayId(selected);
  const navCollapsed = Boolean(state.sessionNavCollapsed);

  const sideRows = reviewedEntries
    .map((entry, index) => {
      const currentClass = index === state.reviewIndex ? "is-current" : "";
      const flaggedClass = entry.response.flagged ? "is-flagged" : "";
      const answeredClass = entry.hasAnswer ? "is-answered" : "is-unanswered";
      const correctnessClass = entry.isCorrect ? "is-correct" : entry.isWrong ? "is-wrong" : "";
      const statusLabel = entry.response.flagged
        ? "flagged"
        : entry.isCorrect
          ? "correct"
          : entry.isWrong
            ? "incorrect"
            : entry.hasAnswer
              ? "answered"
              : "unanswered";
      return `
        <button
          type="button"
          class="exam-nav-item ${currentClass} ${flaggedClass} ${answeredClass} ${correctnessClass}"
          data-action="review-jump-question"
          data-index="${index}"
          aria-label="Go to review question ${index + 1}, ${statusLabel}"
        >
          <span class="num">${index + 1}</span>
        </button>
      `;
    })
    .join("");

  const choicesHtml = question
    ? questionChoices
      .map((choice) => {
        const selectedChoice = response.selected.includes(choice.id);
        const choiceText = String(choice.text || "");
        const choiceLegacyHighlightColor = normalizeSessionHighlightColor(response.highlightedChoices?.[choice.id], "");
        let choiceHighlightRanges = resolveTextHighlightRanges(response.textHighlights?.choices?.[choice.id], choiceText.length);
        if (!choiceHighlightRanges.length && choiceLegacyHighlightColor && choiceText.length) {
          choiceHighlightRanges = [{ start: 0, end: choiceText.length, color: choiceLegacyHighlightColor }];
        }
        const renderedChoiceText = renderTextWithInlineHighlights(choiceText, choiceHighlightRanges);
        const correctChoice = correctChoiceIds.includes(choice.id);
        const wrongSelected = selectedChoice && !correctChoice;
        const showCorrect = correctChoice;
        const statusClass = `${showCorrect ? "is-correct" : ""} ${wrongSelected ? "is-user-wrong" : ""}`;
        const statusIndicator = showCorrect
          ? `<span class="exam-choice-indicator good">✓</span>`
          : wrongSelected
            ? `<span class="exam-choice-indicator bad">✕</span>`
            : `<span class="exam-choice-indicator neutral"></span>`;
        const inlineFeedback = isCorrect && selectedChoice && correctChoice
          ? `<span class="exam-choice-inline-note">Excellent! This is the correct answer.</span>`
          : "";
        return `
            <div class="exam-choice ${selectedChoice ? "is-selected" : ""} ${statusClass}">
              <label class="exam-choice-hit">
                ${statusIndicator}
                <input type="${choiceType}" name="review-answer" value="${choice.id}" ${selectedChoice ? "checked" : ""} disabled />
                <span class="exam-choice-radio"></span>
                <span class="exam-choice-text"><b>${choice.id}.</b> <span class="exam-choice-text-body">${renderedChoiceText}</span> ${inlineFeedback}</span>
              </label>
            </div>
          `;
      })
      .join("")
    : `<p class="subtle">This question was removed from the bank and cannot be rendered.</p>`;
  const isFirstReviewQuestion = state.reviewIndex <= 0;
  const isLastReviewQuestion = state.reviewIndex >= total - 1;

  return `
    <section class="exam-shell-wrap">
      <div class="${reviewShellClassNames}" style="${reviewShellStyleAttr}">
        <section class="exam-main exam-main-simple">
          <div class="exam-content exam-content-moodle ${navCollapsed ? "is-nav-collapsed" : ""}">
            <aside class="exam-question-meta">
              <h3>Question <b>${state.reviewIndex + 1}</b></h3>
              <p class="exam-mark-line"><b>${escapeHtml(sessionName)}</b></p>
              <p class="exam-mark-line subtle">${escapeHtml(sessionTestId)}</p>
              <p class="exam-question-status ${isCorrect ? "good" : "bad"}">${statusText}</p>
              <p class="exam-mark-line">Mark ${markText} out of 1.00</p>
              <p class="exam-mark-line subtle">Mode: ${escapeHtml(selected.mode === "timed" ? "Timed" : "Tutor")}</p>
              <p class="exam-mark-line subtle">Block score: ${correctCount}/${total} (${accuracy}%)</p>
              <span class="exam-meta-link muted">${response.flagged ? "⚑ Flagged question" : "⚑ Not flagged"}</span>
              <span class="exam-meta-badge">v1 (latest)</span>
            </aside>

            <section class="exam-question-stage">
              <article class="exam-question-block exam-question-card">
                ${renderQuestionStemVisual(question)}
                <div class="exam-stem">
                  ${stemLines
      .map((line, index) => {
        const lineText = String(line || "");
        const lineHighlightColor = normalizeSessionHighlightColor(response.highlightedLineColors?.[index], "");
        let lineHighlightRanges = resolveTextHighlightRanges(response.textHighlights?.lines?.[index], lineText.length);
        if (!lineHighlightRanges.length && lineHighlightColor && lineText.length) {
          lineHighlightRanges = [{ start: 0, end: lineText.length, color: lineHighlightColor }];
        }
        return `<p class="exam-line">${renderTextWithInlineHighlights(lineText, lineHighlightRanges)}</p>`;
      })
      .join("")}
                </div>

                <div class="exam-answers">
                  ${choicesHtml}
                </div>

                <div class="exam-answer-actions">
                  <div class="exam-nav-icons">
                    <button
                      class="btn ghost exam-icon-btn"
                      data-action="review-prev-question"
                      ${isFirstReviewQuestion ? "disabled" : ""}
                      aria-label="Previous question"
                      title="Previous question"
                    ><span aria-hidden="true">←</span></button>
                    <button
                      class="btn ghost exam-icon-btn"
                      data-action="review-next-question"
                      ${isLastReviewQuestion ? "disabled" : ""}
                      aria-label="Next question"
                      title="Next question"
                    ><span aria-hidden="true">→</span></button>
                  </div>
                </div>
              </article>
              ${renderReviewFeedbackPane(question, response, isCorrect)}
            </section>

            <aside class="exam-nav-panel ${navCollapsed ? "is-collapsed" : ""}" aria-hidden="${navCollapsed ? "true" : "false"}" ${navCollapsed ? "inert" : ""}>
              <div class="exam-nav-panel-head">
                <h3>Quiz navigation</h3>
                <button
                  type="button"
                  class="exam-nav-collapse-toggle"
                  data-action="toggle-review-nav-collapse"
                  aria-label="Hide quiz navigation"
                  aria-expanded="true"
                  title="Hide quiz navigation"
                >
                  <span aria-hidden="true">›</span>
                </button>
              </div>
              <div class="exam-nav-grid">${sideRows}</div>
              <button class="exam-nav-link" data-action="review-finish">Finish review</button>
              <button class="btn ghost exam-nav-new" data-nav="create-test">Start a new preview</button>
            </aside>
            ${navCollapsed ? `<button
              type="button"
              class="exam-nav-edge-toggle is-visible"
              data-action="toggle-review-nav-collapse"
              aria-label="Show quiz navigation"
              aria-expanded="false"
              title="Show quiz navigation"
            >
              <span aria-hidden="true">‹</span>
            </button>` : ""}
          </div>
        </section>
      </div>
    </section>
  `;
}

function wireReview() {
  appEl.removeEventListener("click", handleReviewClick);
  appEl.addEventListener("click", handleReviewClick);
  document.removeEventListener("keydown", handleReviewKeydown);
  document.addEventListener("keydown", handleReviewKeydown);
}

async function handleReviewClick(event) {
  if (state.route !== "review") {
    return;
  }

  const target = event.target.closest("[data-action]");
  if (!target) {
    return;
  }

  const user = getCurrentUser();
  const completedSessions = getReviewableCompletedSessionsForUser(user, {
    userOverride: user,
    fallbackToAllTerms: true,
  });
  const selected =
    completedSessions.find((session) => session.id === state.reviewSessionId) || completedSessions[0];
  if (!selected) {
    return;
  }

  const maxIndex = Math.max(0, selected.questionIds.length - 1);
  const action = target.getAttribute("data-action");

  if (action === "review-jump-question") {
    const index = Number(target.getAttribute("data-index") || 0);
    state.reviewIndex = Math.min(maxIndex, Math.max(0, index));
    render();
    return;
  }

  if (action === "toggle-review-nav-collapse") {
    state.sessionNavCollapsed = !state.sessionNavCollapsed;
    persistSessionUiPreferences();
    render();
    return;
  }

  if (action === "review-prev-question") {
    state.reviewIndex = Math.max(0, state.reviewIndex - 1);
    render();
    return;
  }

  if (action === "review-next-question") {
    state.reviewIndex = Math.min(maxIndex, state.reviewIndex + 1);
    render();
    return;
  }

  if (action === "review-finish") {
    let syncWarning = "";
    try {
      await flushPendingSyncNow({ throwOnRelationalFailure: true });
    } catch (error) {
      console.warn("Could not persist completed block before returning to dashboard.", error?.message || error);
      syncWarning = "Your finished block is saved locally, but cloud sync has not finished yet. Keep this tab open and try Dashboard refresh again in a moment.";
    }
    if (!syncWarning && hasUnresolvedSessionCloudSync(selected.id)) {
      syncWarning = "Your finished block is still waiting for cloud sync. Keep this tab open and try Dashboard refresh again in a moment.";
    }
    state.reviewIndex = 0;
    navigate("app-launcher");
    if (syncWarning) {
      toast(syncWarning);
      return;
    }
    if (user?.role === "student") {
      refreshStudentDataSnapshot(user, {
        force: true,
        rerender: true,
      }).catch((error) => {
        console.warn("Could not refresh completed session history after review.", error?.message || error);
      });
    }
  }
}

function handleReviewKeydown(event) {
  if (state.route !== "review") {
    return;
  }

  const activeTag = document.activeElement?.tagName;
  if (["INPUT", "TEXTAREA", "SELECT"].includes(activeTag) && event.key !== "Escape") {
    return;
  }
  if (event.metaKey || event.ctrlKey || event.altKey) {
    return;
  }

  if (event.key === "ArrowLeft") {
    event.preventDefault();
    state.reviewIndex = Math.max(0, state.reviewIndex - 1);
    render();
    return;
  }

  if (event.key === "ArrowRight") {
    event.preventDefault();
    const user = getCurrentUser();
    const selected = getReviewableCompletedSessionsForUser(user, {
      userOverride: user,
      fallbackToAllTerms: true,
    })
      .find((session) => session.id === state.reviewSessionId);
    if (!selected) {
      return;
    }
    const maxIndex = Math.max(0, selected.questionIds.length - 1);
    state.reviewIndex = Math.min(maxIndex, state.reviewIndex + 1);
    render();
    return;
  }

  if (/^[1-9]$/.test(event.key)) {
    const index = Number(event.key) - 1;
    const directTarget = appEl.querySelector(`[data-action="review-jump-question"][data-index="${index}"]`);
    if (directTarget) {
      event.preventDefault();
      directTarget.click();
    }
  }
}

function renderReviewFeedbackPane(question, response, isCorrect) {
  if (!question) {
    return `
      <section class="exam-feedback-block bad">
        <header class="exam-feedback-head">
          <h4>Question unavailable.</h4>
        </header>
        <p class="exam-review-rationale">This question no longer exists in the bank and cannot be reviewed.</p>
      </section>
    `;
  }

  if (response.selected.length) {
    return renderInlineExplanationPane(question, isCorrect);
  }

  const choices = Array.isArray(question.choices) ? question.choices : [];
  const correctIds = Array.isArray(question.correct) ? question.correct : [];
  const correctAnswerText = choices
    .filter((choice) => correctIds.includes(choice.id))
    .map((choice) => `${choice.id}. ${choice.text}`)
    .join(" | ");

  return `
    <section class="exam-feedback-block bad">
      <header class="exam-feedback-head">
        <h4>Your answer is incorrect (not submitted).</h4>
      </header>
      <p class="exam-review-rationale">${escapeHtml(question.explanation)}</p>
      <p class="exam-feedback-answer">The correct answer is: ${escapeHtml(correctAnswerText || correctIds.join(", "))}</p>
    </section>
  `;
}

function renderAnalyticsTrend(sessionRollups) {
  const points = (Array.isArray(sessionRollups) ? sessionRollups : []).slice(-12);
  if (points.length < 2) {
    return `
      <div class="analytics-empty">
        <span class="analytics-empty-icon">${studentSvgIcon("chart")}</span>
        <b>Not enough data yet</b>
        <span class="subtle">Complete at least two tests in this course to see your accuracy trend.</span>
      </div>
    `;
  }
  const w = 300;
  const h = 92;
  const pad = 8;
  const n = points.length;
  const xFor = (i) => pad + (i * (w - pad * 2)) / (n - 1);
  const yFor = (a) => pad + (h - pad * 2) * (1 - Math.max(0, Math.min(100, Number(a) || 0)) / 100);
  const coords = points.map((p, i) => [xFor(i), yFor(p.accuracy)]);
  const line = coords.map(([x, y], i) => `${i ? "L" : "M"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
  const area = `M${coords[0][0].toFixed(1)} ${(h - pad).toFixed(1)} `
    + coords.map(([x, y]) => `L${x.toFixed(1)} ${y.toFixed(1)}`).join(" ")
    + ` L${coords[n - 1][0].toFixed(1)} ${(h - pad).toFixed(1)} Z`;
  const last = Number(points[n - 1].accuracy) || 0;
  const first = Number(points[0].accuracy) || 0;
  const delta = last - first;
  return `
    <div class="analytics-trend">
      <svg class="analytics-trend-svg" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Accuracy across your recent tests">
        <path class="analytics-trend-area" d="${area}" />
        <path class="analytics-trend-line" d="${line}" />
      </svg>
      <div class="analytics-trend-meta">
        <span><b>${last}%</b><small>latest test</small></span>
        <span class="analytics-trend-delta ${delta >= 0 ? "is-up" : "is-down"}"><b>${delta >= 0 ? "+" : ""}${delta}%</b><small>across last ${n}</small></span>
      </div>
    </div>
  `;
}

function renderAnalyticsTopicBars(topicStats) {
  const list = (Array.isArray(topicStats) ? topicStats : [])
    .slice()
    .sort((a, b) => b.total - a.total || a.accuracy - b.accuracy)
    .slice(0, 8);
  if (!list.length) {
    return `<p class="subtle">No topic data yet. Complete a block to see per-topic accuracy.</p>`;
  }
  return `
    <div class="analytics-bars">
      ${list.map((t) => {
    const tone = t.accuracy >= 75 ? "good" : t.accuracy >= 50 ? "warn" : "bad";
    return `
        <div class="analytics-bar-row">
          <div class="analytics-bar-head">
            <span class="analytics-bar-topic">${escapeHtml(t.topic)}</span>
            <span class="analytics-bar-val">${t.accuracy}% <small>(${t.correct}/${t.total})</small></span>
          </div>
          <div class="analytics-bar-track"><span class="analytics-bar-fill is-${tone}" style="width:${Math.max(3, Math.min(100, t.accuracy))}%"></span></div>
        </div>`;
  }).join("")}
    </div>
  `;
}

function renderAnalytics() {
  const user = getCurrentUser();
  const availableCourses = getAvailableCoursesForUser(user);
  const contentReadiness = getStudentContentReadiness(user, { availableCourses });
  if (contentReadiness.loading) {
    logStudentContentAccessDecision(user, {
      reason: "analytics_waiting_for_content",
      surface: "analytics",
      availableCourses,
    });
    return renderStudentContentLoadingPanel("Checking Analytics Data");
  }
  if (contentReadiness.issue) {
    recordStudentAccessIssue(contentReadiness.issue, user, { surface: "analytics" });
    return `
      <section class="panel">
        <h2 class="title">Performance Analytics</h2>
        <p class="subtle">${escapeHtml(contentReadiness.issue.message)}</p>
      </section>
    `;
  }
  if (contentReadiness.error) {
    return renderStudentContentErrorPanel("Analytics Could Not Load", contentReadiness.error);
  }
  if (!availableCourses.length) {
    return `
      <section class="panel">
        <h2 class="title">Performance Analytics</h2>
        <p class="subtle">No courses are assigned to this account yet.</p>
      </section>
    `;
  }
  if (!availableCourses.includes(state.analyticsCourse)) {
    state.analyticsCourse = availableCourses[0];
  }

  const selectedCourse = state.analyticsCourse;
  const analytics = getStudentAnalyticsSnapshot(user.id, selectedCourse);
  const stats = analytics.stats;
  const topicStats = analytics.topicStats;
  const weak = analytics.weakAreas;
  const insights = analytics.insights;
  const syncStatusText = getStudentDataSyncStatusText();

  const incorrectQueueCount = getStudentIncorrectQueueCount(user.id);
  const flaggedCount = Number(analytics.flaggedCount || 0);
  const completedTestCount = Array.isArray(analytics.sessionRollups) ? analytics.sessionRollups.length : 0;

  return `
    <section class="panel">
      <h2 class="title">Performance Analytics</h2>
      <p class="subtle">Real insights from your completed tests — what is improving and what to study next.</p>
      ${isNativeAppUi() ? `
        <section class="native-performance-hero">
          <div class="native-performance-ring" style="--native-ring-value:${Math.max(0, Math.min(100, Number(stats.accuracy || 0)))}">
            <strong>${Math.max(0, Math.round(Number(stats.accuracy || 0)))}%</strong>
            <span>overall accuracy</span>
          </div>
          <div class="native-performance-summary">
            <article><span>${studentSvgIcon("solved")}</span><div><strong>${Math.max(0, Number(stats.totalAnswered || 0))}</strong><small>Questions done</small></div></article>
            <article><span>${studentSvgIcon("streak")}</span><div><strong>${Math.max(0, Number(stats.streak || 0))}</strong><small>Perfect-test streak</small></div></article>
          </div>
        </section>` : ""}
      <div class="flex-between" style="gap: 0.8rem; align-items: flex-end; flex-wrap: wrap;">
        <form id="analytics-course-form" style="margin-top: 0.8rem; max-width: 520px;" autocomplete="off">
          <label>Course
            <select id="analytics-course-select" name="analyticsCourse">
              ${availableCourses
      .map((course) => `<option value="${escapeHtml(course)}" ${course === selectedCourse ? "selected" : ""}>${escapeHtml(course)}</option>`)
      .join("")}
            </select>
          </label>
        </form>
        <button class="btn ghost ${state.studentDataRefreshing ? "is-loading" : ""}" type="button" data-action="refresh-student-analytics" ${state.studentDataRefreshing ? "disabled" : ""}>
          ${renderStudentRefreshButtonContent()}
        </button>
      </div>
      <small class="subtle">Showing analytics for <b>${escapeHtml(selectedCourse)}</b>. ${escapeHtml(syncStatusText)}</small>
      <div class="student-stats-grid" style="margin-top: 0.85rem;">
        ${renderStudentStatCard("accuracy", `${stats.accuracy}%`, "Accuracy", "brand")}
        ${renderStudentStatCard("time", `${stats.timePerQuestion}s`, "Time / question", "accent")}
        ${renderStudentStatCard("streak", stats.streak, "Perfect-test streak", "good")}
        ${renderStudentStatCard("solved", stats.totalAnswered, "Total answered")}
      </div>
    </section>

    <section class="panel grid-2">
      <article class="card">
        <h4>Accuracy Trend</h4>
        <p class="subtle">Per-test accuracy across your recent ${escapeHtml(selectedCourse)} blocks.</p>
        ${renderAnalyticsTrend(analytics.sessionRollups)}
      </article>
      <article class="card">
        <h4>Topic Accuracy</h4>
        <p class="subtle">Strongest and weakest topics, by accuracy.</p>
        ${renderAnalyticsTopicBars(topicStats)}
      </article>
    </section>

    <section class="panel grid-2">
      <article class="card">
        <h4>Focus Areas</h4>
        <p class="subtle">Your weakest topics in this course — prioritise these.</p>
        ${weak.length
      ? `<div class="analytics-focus-list">${weak
        .slice(0, 6)
        .map((entry) => `<p class="analytics-focus-item"><b>${escapeHtml(entry.topic)}</b><span class="subtle">${entry.accuracy}% • ${entry.total} q • ${entry.timePerQuestion || 0}s/q</span></p>`)
        .join("")}</div>`
      : `<div class="analytics-empty"><span class="analytics-empty-icon">${studentSvgIcon("flag")}</span><b>No focus areas yet</b><span class="subtle">Complete a block to surface your weak topics.</span></div>`
    }
      </article>
      <article class="card analytics-review-card">
        <h4>Review &amp; Retry</h4>
        <p class="subtle">Close the loop on questions you missed or flagged.</p>
        <div class="analytics-review-stats">
          <span><b>${incorrectQueueCount}</b><small>saved incorrect</small></span>
          <span><b>${flaggedCount}</b><small>flagged</small></span>
          <span><b>${completedTestCount}</b><small>tests completed</small></span>
        </div>
        <button class="btn" type="button" data-action="dash-review-incorrect" ${incorrectQueueCount ? "" : "disabled"}>
          ${incorrectQueueCount ? `Review ${incorrectQueueCount} incorrect question${incorrectQueueCount === 1 ? "" : "s"}` : "No saved incorrect questions"}
        </button>
      </article>
    </section>

    <section class="panel grid-2">
      <article class="card">
        <h4>Smart Study Coach</h4>
        <p><b>${escapeHtml(insights.summary)}</b></p>
        <p class="subtle">${escapeHtml(insights.focusMessage)}</p>
        <p class="subtle">${escapeHtml(insights.trendMessage)}</p>
        <p class="subtle">${escapeHtml(insights.paceMessage)}</p>
      </article>
      <article class="card">
        <h4>Recommended Next Block</h4>
        <p><b>Source:</b> ${escapeHtml(getCreateTestSourceLabel(insights.nextSource))}</p>
        <p><b>Target:</b> ${escapeHtml(insights.nextTargetText)}</p>
        <p><b>Suggested size:</b> ${insights.suggestedCount} questions</p>
        <p class="subtle">${escapeHtml(insights.nextReason)}</p>
        <button
          class="btn ghost admin-btn-sm"
          type="button"
          data-action="apply-analytics-plan"
          data-source="${escapeHtml(insights.nextSource)}"
          data-course="${escapeHtml(selectedCourse)}"
          data-topic="${escapeHtml(insights.focusTopic || "")}"
        >
          Apply Plan In Create Test
        </button>
      </article>
    </section>
  `;
}

function wireAnalytics() {
  appEl.querySelector("[data-action='dash-review-incorrect']")?.addEventListener("click", () => {
    state.createTestSource = "incorrect";
    state.skipNextRouteAnimation = true;
    navigate("create-test");
  });

  const form = document.getElementById("analytics-course-form");
  form?.addEventListener("change", () => {
    const data = new FormData(form);
    state.analyticsCourse = String(data.get("analyticsCourse") || "").trim();
    render();
  });

  wireStudentRefreshButtons();

  appEl.querySelector("[data-action='apply-analytics-plan']")?.addEventListener("click", () => {
    const user = getCurrentUser();
    const availableCourses = getAvailableCoursesForUser(user);
    const button = appEl.querySelector("[data-action='apply-analytics-plan']");
    const source = String(button?.getAttribute("data-source") || "").trim();
    const course = String(button?.getAttribute("data-course") || "").trim();
    const topic = String(button?.getAttribute("data-topic") || "").trim();
    if (["all", "unused", "incorrect", "flagged"].includes(source)) {
      state.createTestSource = source;
    }
    if (course && availableCourses.includes(course)) {
      state.qbankFilters.course = course;
    }
    state.qbankFilters.topicSource = "";
    state.qbankFilters.topics = topic ? [topic] : [];
    state.skipNextRouteAnimation = true;
    navigate("create-test");
  });
}

function renderProfile() {
  const user = getCurrentUser();
  const queue = load(STORAGE_KEYS.incorrectQueue, {})[user.id] || [];
  const isGoogleAuthUser = getAuthProviderFromUser(user) === "google";

  return `
    <section class="panel">
      <h2 class="title">Profile & Settings</h2>
      <p class="subtle">Manage account details and credentials.</p>
      <div class="grid-2" style="margin-top: 0.9rem;">
        <form id="profile-form" class="card" autocomplete="on">
          <h4>Account</h4>
          <label>Name <input name="name" autocomplete="name" value="${escapeHtml(user.name)}" required /></label>
          <label>
            Email
            <input
              name="email"
              type="email"
              autocomplete="email"
              value="${escapeHtml(user.email)}"
              ${isGoogleAuthUser ? "readonly aria-readonly=\"true\"" : ""}
              required
            />
          </label>
          ${isGoogleAuthUser
      ? `<p class="subtle" style="margin: -0.35rem 0 0;">Email is locked for Google sign-in accounts.</p>`
      : ""
    }
          <label>New password <input name="password" type="password" minlength="6" autocomplete="new-password" /></label>
          <button class="btn" type="submit">Save changes</button>
        </form>
        <article class="card">
          <h4>Study Queue</h4>
          <p><b>Incorrect queue size:</b> ${queue.length}</p>
          <p class="subtle">Use source = Incorrect when creating blocks to target weak items.</p>
          <hr />
          <p><b>Role:</b> ${escapeHtml(user.role)}</p>
          ${user.role === "student" ? `<p><b>Year/Semester:</b> ${normalizeAcademicYearOrNull(user.academicYear) ?? "-"} / ${normalizeAcademicSemesterOrNull(user.academicSemester) ?? "-"}</p>` : ""}
          <p><b>Phone:</b> ${escapeHtml(user.phone || "-")}</p>
          <p><b>Access approved:</b> ${isUserAccessApproved(user) ? "Yes" : "Pending admin approval"}</p>
          <p><b>Assigned MCQ subjects:</b> ${escapeHtml((user.assignedCourses || []).join(", "))}</p>
          <p><b>Email verified:</b> ${user.verified ? "Yes" : "No"}</p>
        </article>
      </div>
    </section>
  `;
}

function wireProfile() {
  const form = document.getElementById("profile-form");
  form?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const user = getCurrentUser();
    const users = getUsers();
    const data = new FormData(form);
    const isGoogleAuthUser = getAuthProviderFromUser(user) === "google";

    const name = String(data.get("name") || "").trim();
    const requestedEmail = String(data.get("email") || "").trim().toLowerCase();
    const email = isGoogleAuthUser ? String(user.email || "").trim().toLowerCase() : requestedEmail;
    const password = String(data.get("password") || "");

    if (!isGoogleAuthUser) {
      const emailConflict = users.some((entry) => entry.email.toLowerCase() === email && entry.id !== user.id);
      if (emailConflict) {
        toast("Email already used by another account.");
        return;
      }
    }

    const authClient = getSupabaseAuthClient();
    if (authClient && user.supabaseAuthId) {
      const updates = { data: { full_name: name } };
      if (!isGoogleAuthUser && email && email !== user.email) {
        updates.email = email;
      }
      if (password) {
        updates.password = password;
      }
      const { error } = await queueSupabaseAuthRequest(authClient, () => authClient.auth.updateUser(updates));
      if (error) {
        toast(error.message || "Could not update Supabase profile.");
        return;
      }
    }

    const index = users.findIndex((entry) => entry.id === user.id);
    users[index].name = name;
    users[index].email = email;
    if (password) {
      users[index].password = password;
    }

    save(STORAGE_KEYS.users, users);
    toast("Profile updated.");
    render();
  });
}

function normalizeAdminQuestionFilterToken(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

function resolveAdminQuestionListView(questions, allCourses, preferredCourse = "", preferredTopic = "") {
  const questionList = Array.isArray(questions) ? questions : [];
  const configuredCourses = Array.isArray(allCourses) ? allCourses.filter(Boolean) : [];
  const questionCountByCourseKey = new Map();
  const topicsByCourseKeyFromQuestions = new Map();
  const courseDisplayByKey = new Map();

  questionList.forEach((question) => {
    const meta = getQbankCourseTopicMeta(question);
    const course = String(meta.course || "").trim();
    const topic = String(meta.topic || "").trim();
    const courseKey = normalizeAdminQuestionFilterToken(course);
    if (!courseKey) {
      return;
    }
    if (!courseDisplayByKey.has(courseKey)) {
      courseDisplayByKey.set(courseKey, course);
    }
    questionCountByCourseKey.set(courseKey, (questionCountByCourseKey.get(courseKey) || 0) + 1);

    if (!topic) {
      return;
    }
    const topicKey = normalizeAdminQuestionFilterToken(topic);
    if (!topicKey) {
      return;
    }
    if (!topicsByCourseKeyFromQuestions.has(courseKey)) {
      topicsByCourseKeyFromQuestions.set(courseKey, []);
    }
    const topicList = topicsByCourseKeyFromQuestions.get(courseKey);
    if (!topicList.some((entry) => normalizeAdminQuestionFilterToken(entry) === topicKey)) {
      topicList.push(topic);
    }
  });

  const questionCourses = [...courseDisplayByKey.values()];
  const availableCourses = [];
  const seenCourseKeys = new Set();
  [...configuredCourses, ...questionCourses].forEach((course) => {
    const courseName = String(course || "").trim();
    const courseKey = normalizeAdminQuestionFilterToken(courseName);
    if (!courseKey || seenCourseKeys.has(courseKey)) {
      return;
    }
    seenCourseKeys.add(courseKey);
    availableCourses.push(courseName);
  });

  const preferredCourseKey = normalizeAdminQuestionFilterToken(preferredCourse);
  let selectedCourse = availableCourses.find((course) => normalizeAdminQuestionFilterToken(course) === preferredCourseKey) || "";
  if (!selectedCourse) {
    selectedCourse = availableCourses.find(
      (course) => (questionCountByCourseKey.get(normalizeAdminQuestionFilterToken(course)) || 0) > 0,
    ) || availableCourses[0] || "";
  } else if ((questionCountByCourseKey.get(normalizeAdminQuestionFilterToken(selectedCourse)) || 0) === 0) {
    const fallbackCourse = availableCourses.find(
      (course) => (questionCountByCourseKey.get(normalizeAdminQuestionFilterToken(course)) || 0) > 0,
    );
    if (fallbackCourse) {
      selectedCourse = fallbackCourse;
    }
  }

  const selectedCourseKey = normalizeAdminQuestionFilterToken(selectedCourse);
  const configuredTopics = selectedCourse ? (QBANK_COURSE_TOPICS[selectedCourse] || []) : [];
  const questionTopics = selectedCourseKey ? (topicsByCourseKeyFromQuestions.get(selectedCourseKey) || []) : [];
  const selectedCourseTopics = mergeUniqueCourseTopics(selectedCourse, configuredTopics, questionTopics);
  const preferredTopicKey = normalizeAdminQuestionFilterToken(preferredTopic);
  const selectedTopic = selectedCourseTopics.find((topic) => normalizeAdminQuestionFilterToken(topic) === preferredTopicKey) || "";
  const selectedTopicKey = normalizeAdminQuestionFilterToken(selectedTopic);

  const filteredQuestions = questionList
    .filter((question) => String(question?.status || "").trim().toLowerCase() !== "archived")
    .filter((question) => {
      const meta = getQbankCourseTopicMeta(question);
      return normalizeAdminQuestionFilterToken(meta.course) === selectedCourseKey;
    })
    .filter((question) => {
      if (!selectedTopicKey) {
        return true;
      }
      const meta = getQbankCourseTopicMeta(question);
      return normalizeAdminQuestionFilterToken(meta.topic) === selectedTopicKey;
    });

  return {
    selectedCourse,
    selectedCourseTopics,
    selectedTopic,
    filteredQuestions,
  };
}

function resolveAdminImportView(allCourses, preferredCourse = "") {
  const configuredCourses = Array.isArray(allCourses) ? allCourses.filter(Boolean) : [];
  const fallbackCourse = configuredCourses.includes(preferredCourse) ? preferredCourse : (configuredCourses[0] || "");
  const importCourse = configuredCourses.includes(state.adminImportCourse)
    ? state.adminImportCourse
    : fallbackCourse;
  const importTopics = QBANK_COURSE_TOPICS[importCourse] || [];
  const importTopic = importTopics.includes(state.adminImportTopic)
    ? state.adminImportTopic
    : (importTopics[0] || "");
  return {
    importCourse,
    importTopics,
    importTopic,
    importReport: state.adminImportReport,
    importDraft: String(state.adminImportDraft || ""),
    importRunning: Boolean(state.adminImportRunning),
    importAsDraft: Boolean(state.adminImportAsDraft),
    importStatus: String(state.adminImportStatus || "").trim(),
    importStatusTone: ["success", "error", "warning"].includes(state.adminImportStatusTone)
      ? state.adminImportStatusTone
      : "neutral",
  };
}

function renderAdminBulkImportSection(allCourses, options = {}) {
  const preferredCourse = String(options.preferredCourse || "").trim();
  const {
    importCourse,
    importTopics,
    importTopic,
    importReport,
    importDraft,
    importRunning,
    importAsDraft,
    importStatus,
    importStatusTone,
  } = resolveAdminImportView(allCourses, preferredCourse);
  const importErrorPreview = (importReport?.errors || []).slice(0, 15);

  return `
    <section class="card admin-section" id="admin-bulk-import-section">
      <h3 style="margin: 0;">Bulk Import</h3>
      <p class="subtle">Upload or paste CSV/JSON and import questions by default course/topic.</p>
      <form id="admin-import-form" style="margin-top: 0.7rem;" autocomplete="off">
        <div class="form-row">
          <label>
            Default course
            <select name="defaultCourse" id="admin-import-course">
              ${allCourses
      .map((course) => `<option value="${escapeHtml(course)}" ${importCourse === course ? "selected" : ""}>${escapeHtml(course)}</option>`)
      .join("")}
            </select>
          </label>
          <label>
            Default topic
            <select name="defaultTopic" id="admin-import-topic">
              ${importTopics
      .map((topic) => `<option value="${escapeHtml(topic)}" ${importTopic === topic ? "selected" : ""}>${escapeHtml(topic)}</option>`)
      .join("")}
            </select>
          </label>
        </div>
        <label class="admin-course-check" style="width: fit-content;">
          <input type="checkbox" name="importAsDraft" ${importAsDraft ? "checked" : ""} />
          <span>Save all imported questions as draft (hide from students)</span>
        </label>
        <label>Upload file(s)
          <input type="file" id="admin-import-file" accept=".csv,.json,text/csv,application/json" multiple />
        </label>
        <label>Paste CSV rows or JSON array
          <textarea id="admin-import-text" name="importText" placeholder='CSV headers example: stem,choiceA,choiceB,choiceC,choiceD,choiceE,correct,explanation,course,topic,system,difficulty,status,tags,questionImage,explanationImage'>${escapeHtml(importDraft)}</textarea>
        </label>
        <div class="stack">
          <button class="btn ${importRunning ? "is-loading" : ""}" type="submit" ${importRunning ? "disabled" : ""}>
            ${importRunning ? `<span class="inline-loader" aria-hidden="true"></span><span>Importing questions...</span>` : "Run bulk import"}
          </button>
          <button class="btn ghost ${importRunning ? "is-loading" : ""}" type="button" id="admin-sync-questions-now" ${importRunning ? "disabled" : ""}>
            ${importRunning ? `<span class="inline-loader" aria-hidden="true"></span><span>Syncing cloud data...</span>` : "Sync existing questions to cloud"}
          </button>
          <button class="btn ghost" type="button" id="admin-download-template">Download Excel template (.csv)</button>
        </div>
      </form>
      ${importStatus
      ? `<p class="subtle import-status is-${importStatusTone}" aria-live="polite">${escapeHtml(importStatus)}</p>`
      : ""
    }
      ${importReport
      ? `
            <div class="admin-import-report card" style="margin-top: 0.7rem;">
              <p style="margin: 0;"><b>Last import:</b> ${new Date(importReport.createdAt).toLocaleString()}</p>
              <p class="subtle">Imported ${importReport.added}/${importReport.total} rows. ${importReport.errors.length} error(s).</p>
              ${importErrorPreview.length
        ? `
                    <ol class="admin-import-error-list">
                      ${importErrorPreview.map((error) => `<li>${escapeHtml(error)}</li>`).join("")}
                    </ol>
                    <small class="subtle">Showing first ${importErrorPreview.length} errors.</small>
                  `
        : `<p class="subtle">No errors in last import.</p>`
      }
              <div class="stack">
                <button class="btn ghost admin-btn-sm" type="button" id="admin-download-import-errors" ${importReport.errors.length ? "" : "disabled"}>Download full error report</button>
                <button class="btn ghost admin-btn-sm" type="button" id="admin-clear-import-report">Clear report</button>
              </div>
            </div>
          `
      : ""
    }
    </section>
  `;
}

function getAdminVisibleCoursesForUser(account, allCourses = Object.keys(QBANK_COURSE_TOPICS)) {
  if (!account) {
    return [];
  }
  const enrolledCourses = sanitizeCourseAssignments(account.enrolledCourses || []);
  if (account.role === "student" && enrolledCourses.length) {
    return enrolledCourses;
  }
  const year = account.role === "student" ? normalizeAcademicYearOrNull(account.academicYear) : null;
  const semester = account.role === "student" ? normalizeAcademicSemesterOrNull(account.academicSemester) : null;
  if (account.role === "student") {
    return year && semester
      ? getCurriculumCourses(year, semester)
      : sanitizeCourseAssignments(account.assignedCourses || []);
  }
  return sanitizeCourseAssignments(account.assignedCourses || allCourses);
}

function getAdminVisibleCoursePreviewText(visibleCourses) {
  const list = Array.isArray(visibleCourses) ? visibleCourses : [];
  const compactCourses = list.slice(0, 2).map((course) => (course.length > 42 ? `${course.slice(0, 39)}...` : course));
  return list.length > 2 ? `${compactCourses.join(", ")} +${list.length - 2} more` : compactCourses.join(", ");
}

function patchAdminUsersPendingSummaryUi() {
  const usersSection = appEl?.querySelector("#admin-users-section");
  if (!usersSection) {
    return false;
  }
  const pendingCount = getUsers().filter((entry) => entry.role === "student" && !isUserAccessApproved(entry)).length;
  const pendingBadge = usersSection.querySelector("[data-admin-pending-count]");
  if (pendingBadge) {
    pendingBadge.className = `badge ${pendingCount ? "bad" : "good"}`;
    pendingBadge.innerHTML = `Pending: <b>${pendingCount}</b>`;
  }
  const approveAllButton = usersSection.querySelector("[data-action='approve-all-pending']");
  if (approveAllButton && !state.adminUserBulkActionRunning && !state.adminApproveAllPendingRunning) {
    approveAllButton.disabled = !pendingCount;
  }
  return true;
}

function patchAdminUserRowUi(row, account, actorUser = null) {
  if (!row || !account) {
    return false;
  }
  const accountId = String(account.id || "").trim();
  const enrollmentView = getAdminUserEnrollmentViewModel(account);
  const displayAccount = enrollmentView.account || account;
  const year = displayAccount.role === "student" ? normalizeAcademicYearOrNull(displayAccount.academicYear) : null;
  const semester = displayAccount.role === "student" ? normalizeAcademicSemesterOrNull(displayAccount.academicSemester) : null;
  const isApproved = isUserAccessApproved(account);
  const mcqAccessEnabled = account.role === "admin" || account.mcqAccessEnabled !== false;
  const coursesAccessEnabled = isUserCoursesAccessEnabled(account);
  const visibleCourses = getAdminVisibleCoursesForUser(displayAccount);
  const coursePreview = getAdminVisibleCoursePreviewText(visibleCourses);
  const nameInput = row.querySelector("input[data-field='name']");
  const phoneInput = row.querySelector("input[data-field='phone']");
  const saveButton = row.querySelector("[data-action='save-user-enrollment']");

  const yearSelect = row.querySelector("select[data-field='academicYear']");
  if (yearSelect) {
    yearSelect.value = year === null ? "" : String(year);
  }

  const semesterSelect = row.querySelector("select[data-field='academicSemester']");
  if (semesterSelect) {
    semesterSelect.value = semester === null ? "" : String(semester);
  }

  if (nameInput) {
    nameInput.value = String(displayAccount.name ?? account.name ?? "");
  }

  if (phoneInput) {
    phoneInput.value = String(displayAccount.phone ?? "");
  }

  if (saveButton) {
    setAdminUserEnrollmentSaveButtonBusy(
      saveButton,
      Boolean(getAdminUserEnrollmentSaveMode(accountId)),
      { mode: getAdminUserEnrollmentSaveMode(accountId) || "manual" },
    );
  }

  const coursePreviewEl = row.querySelector(".admin-course-preview");
  if (coursePreviewEl) {
    coursePreviewEl.textContent = coursePreview || "No MCQ subjects assigned";
    coursePreviewEl.title = visibleCourses.join(", ");
  }

  const statusBadge = row.querySelector("[data-user-status-badge]");
  if (statusBadge) {
    statusBadge.className = `badge ${isApproved ? "good" : "bad"}`;
    statusBadge.textContent = isApproved ? "approved" : "pending";
  }

  const mcqStatusBadge = row.querySelector("[data-user-mcq-status-badge]");
  if (mcqStatusBadge) {
    mcqStatusBadge.className = `badge ${mcqAccessEnabled ? "good" : "neutral"}`;
    mcqStatusBadge.textContent = `MCQ ${mcqAccessEnabled ? "on" : "off"}`;
  }

  const coursesStatusBadge = row.querySelector("[data-user-courses-status-badge]");
  if (coursesStatusBadge) {
    coursesStatusBadge.className = `badge ${coursesAccessEnabled ? "good" : "neutral"}`;
    coursesStatusBadge.textContent = `Video Courses ${coursesAccessEnabled ? "on" : "off"}`;
  }

  const approvalButton = row.querySelector("[data-action='toggle-user-approval']");
  if (approvalButton) {
    const isBusy = approvalButton.dataset.busy === "1";
    approvalButton.disabled = isBusy || account.role === "admin";
    if (!isBusy) {
      approvalButton.textContent = isApproved ? "Suspend" : "Approve";
    }
  }

  const mcqAccessButton = row.querySelector("[data-action='toggle-user-mcq-access']");
  if (mcqAccessButton) {
    const isBusy = mcqAccessButton.dataset.busy === "1";
    mcqAccessButton.disabled = isBusy || account.role === "admin";
    mcqAccessButton.setAttribute("aria-checked", mcqAccessEnabled ? "true" : "false");
    if (!isBusy) {
      mcqAccessButton.innerHTML = renderAdminAccessSwitchContent("MCQs", mcqAccessEnabled);
    }
  }

  const coursesAccessButton = row.querySelector("[data-action='toggle-user-courses-access']");
  if (coursesAccessButton) {
    const isBusy = coursesAccessButton.dataset.busy === "1";
    coursesAccessButton.disabled = isBusy || account.role === "admin";
    coursesAccessButton.setAttribute("aria-checked", coursesAccessEnabled ? "true" : "false");
    if (!isBusy) {
      coursesAccessButton.innerHTML = renderAdminAccessSwitchContent("Video Courses", coursesAccessEnabled);
    }
  }

  const roleButton = row.querySelector("[data-action='toggle-user-role']");
  if (roleButton) {
    const currentAdmin = actorUser || getCurrentUser();
    const isSelf = account.id === currentAdmin?.id;
    roleButton.disabled = Boolean(isSelf);
    roleButton.textContent = account.role === "admin" ? "Make student" : "Make admin";
  }

  patchAdminUsersPendingSummaryUi();
  return true;
}

function renderAdminAccessSwitchContent(label, enabled) {
  return `
    <span class="admin-access-switch-text">${escapeHtml(label)}</span>
    <span class="admin-access-switch-track" aria-hidden="true">
      <span class="admin-access-switch-thumb"></span>
    </span>
    <span class="admin-access-switch-state">${enabled ? "On" : "Off"}</span>
  `;
}

function getAdminAgentPermissionLabel(permissionKey) {
  const entry = ADMIN_AGENT_PERMISSION_OPTIONS.find(([key]) => key === String(permissionKey || "").trim());
  return entry ? entry[1] : String(permissionKey || "").trim();
}

function getAdminAgentRowsByAgentId(rows, agentId) {
  return (Array.isArray(rows) ? rows : []).filter((row) => String(row?.agent_id || "").trim() === String(agentId || "").trim());
}

async function loadAdminAgents(options = {}) {
  const client = getCoursesPlatformClient();
  if (!client) {
    state.adminAgentsError = "No active Supabase admin session.";
    state.adminAgentsLoadedAt = Date.now();
    return false;
  }
  if (state.adminAgentsLoading && !options.force) {
    return false;
  }
  state.adminAgentsLoading = true;
  state.adminAgentsError = "";
  try {
    const [agents, permissions, actions, approvals] = await Promise.all([
      runRelationalQueryWithTimeout(
        client.from("admin_agents").select("id,name,description,status,token_hint,last_used_at,created_at,updated_at").order("created_at", { ascending: false }),
        "Agent list query timed out.",
      ),
      runRelationalQueryWithTimeout(
        client.from("admin_agent_permissions").select("agent_id,permission_key,created_at"),
        "Agent permission query timed out.",
      ),
      runRelationalQueryWithTimeout(
        client.from("admin_agent_action_log").select("id,agent_id,action_key,action_status,response_summary,created_at").order("created_at", { ascending: false }).limit(40),
        "Agent activity query timed out.",
      ),
      runRelationalQueryWithTimeout(
        client.from("admin_agent_approval_requests").select("id,agent_id,action_key,request_payload,reason,status,created_at,reviewed_at").order("created_at", { ascending: false }).limit(40),
        "Agent approval query timed out.",
      ),
    ]);
    state.adminAgents = Array.isArray(agents) ? agents : [];
    state.adminAgentPermissions = Array.isArray(permissions) ? permissions : [];
    state.adminAgentActions = Array.isArray(actions) ? actions : [];
    state.adminAgentApprovals = Array.isArray(approvals) ? approvals : [];
    state.adminAgentsLoadedAt = Date.now();
    return true;
  } catch (error) {
    state.adminAgentsError = isMissingRelationError(error)
      ? "Hermes Assistant is not installed in Supabase yet. Apply the latest database migration, then refresh."
      : getErrorMessage(error, "Could not load Hermes Assistant.");
    state.adminAgentsLoadedAt = Date.now();
    return false;
  } finally {
    state.adminAgentsLoading = false;
  }
}

function generateAdminAgentToken() {
  const bytes = new Uint8Array(36);
  window.crypto.getRandomValues(bytes);
  const encoded = window.btoa(String.fromCharCode(...bytes))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/g, "");
  return `mba_${encoded}`;
}

async function hashAdminAgentToken(token) {
  const digest = await window.crypto.subtle.digest("SHA-256", new TextEncoder().encode(String(token || "")));
  return Array.from(new Uint8Array(digest))
    .map((value) => value.toString(16).padStart(2, "0"))
    .join("");
}

function getPrimaryAdminAssistant() {
  const assistants = Array.isArray(state.adminAgents) ? state.adminAgents : [];
  return assistants.find((assistant) => assistant.name === PRIMARY_ADMIN_ASSISTANT_NAME) || assistants[0] || null;
}

async function initializePrimaryAdminAssistant() {
  const client = getCoursesPlatformClient();
  const currentUserId = getCurrentCoursePlatformUserId();
  if (!client) throw new Error("Hermes connection cannot be created.");
  const existingRows = await runRelationalQueryWithTimeout(
    client.from("admin_agents").select("id").limit(1),
    "Hermes connection check timed out.",
  );
  if (Array.isArray(existingRows) && existingRows.length) {
    throw new Error("Hermes is already connected. Rotate its token to issue a new credential.");
  }
  const permissionKeys = ["read_dashboard", "draft_announcements", "request_content_publish", "full_admin"];
  const token = generateAdminAgentToken();
  const tokenHash = await hashAdminAgentToken(token);
  const rows = await runRelationalQueryWithTimeout(
    client.from("admin_agents").insert({
      name: PRIMARY_ADMIN_ASSISTANT_NAME,
      description: PRIMARY_ADMIN_ASSISTANT_DESCRIPTION,
      token_hash: tokenHash,
      token_hint: token.slice(-8),
      created_by: isUuidValue(currentUserId) ? currentUserId : null,
    }).select("id,name").limit(1),
    "Agent creation timed out.",
  );
  const agent = Array.isArray(rows) ? rows[0] : null;
  if (!agent?.id) throw new Error("Hermes connection could not be created.");
  await runRelationalQueryWithTimeout(
    client.from("admin_agent_permissions").insert(permissionKeys.map((permissionKey) => ({
      agent_id: agent.id,
      permission_key: permissionKey,
      created_by: isUuidValue(currentUserId) ? currentUserId : null,
    }))),
    "Agent permission save timed out.",
  );
  state.adminAgentNewToken = { name: PRIMARY_ADMIN_ASSISTANT_NAME, token };
  await loadAdminAgents({ force: true });
}

async function rotateAdminAgentToken(agentId, agentName) {
  const client = getCoursesPlatformClient();
  if (!client || !isUuidValue(agentId)) throw new Error("Agent token cannot be rotated.");
  const token = generateAdminAgentToken();
  const tokenHash = await hashAdminAgentToken(token);
  await runRelationalQueryWithTimeout(
    client.from("admin_agents").update({ token_hash: tokenHash, token_hint: token.slice(-8) }).eq("id", agentId),
    "Agent token rotation timed out.",
  );
  state.adminAgentNewToken = { name: agentName || "AI agent", token };
  await loadAdminAgents({ force: true });
}

async function setAdminAgentStatus(agentId, status) {
  const client = getCoursesPlatformClient();
  const nextStatus = status === "active" ? "active" : "disabled";
  if (!client || !isUuidValue(agentId)) throw new Error("Agent status cannot be changed.");
  await runRelationalQueryWithTimeout(
    client.from("admin_agents").update({ status: nextStatus }).eq("id", agentId),
    "Agent status update timed out.",
  );
  await loadAdminAgents({ force: true });
}

async function setAdminAgentFullAccess(agentId, enabled) {
  const client = getCoursesPlatformClient();
  const currentUserId = getCurrentCoursePlatformUserId();
  if (!client || !isUuidValue(agentId)) throw new Error("Agent permissions cannot be changed.");
  if (enabled) {
    await runRelationalQueryWithTimeout(
      client.from("admin_agent_permissions").upsert({
        agent_id: agentId,
        permission_key: "full_admin",
        created_by: isUuidValue(currentUserId) ? currentUserId : null,
      }, { onConflict: "agent_id,permission_key", defaultToNull: false }),
      "Full administrator permission update timed out.",
    );
  } else {
    await runRelationalQueryWithTimeout(
      client.from("admin_agent_permissions").delete().eq("agent_id", agentId).eq("permission_key", "full_admin"),
      "Full administrator permission removal timed out.",
    );
  }
  await loadAdminAgents({ force: true });
}

async function resolveAdminAgentApproval(approvalId, decision) {
  const client = getCoursesPlatformClient();
  const adminId = getCurrentCoursePlatformUserId();
  const approval = (state.adminAgentApprovals || []).find((row) => String(row?.id || "").trim() === String(approvalId || "").trim());
  if (!client || !approval || !isUuidValue(approvalId)) throw new Error("Approval request cannot be updated.");
  if (String(approval.status || "").trim() !== "pending") throw new Error("This request has already been reviewed.");
  const reviewedAt = nowISO();
  if (decision === "approve" && approval.action_key === "request_publish_announcement") {
    const announcementId = String(approval.request_payload?.announcementId || "").trim();
    if (!isUuidValue(announcementId)) throw new Error("This request has no valid announcement draft.");
    await runRelationalQueryWithTimeout(
      client.from("platform_course_announcements").update({ is_published: true }).eq("id", announcementId),
      "Announcement publish timed out.",
    );
    await runRelationalQueryWithTimeout(
      client.from("admin_agent_approval_requests").update({
        status: "executed",
        reviewed_by: isUuidValue(adminId) ? adminId : null,
        reviewed_at: reviewedAt,
      }).eq("id", approvalId),
      "Approval completion timed out.",
    );
  } else {
    await runRelationalQueryWithTimeout(
      client.from("admin_agent_approval_requests").update({
        status: decision === "approve" ? "approved" : "rejected",
        reviewed_by: isUuidValue(adminId) ? adminId : null,
        reviewed_at: reviewedAt,
      }).eq("id", approvalId),
      "Approval review timed out.",
    );
  }
  await loadAdminAgents({ force: true });
}

function renderAdminAgentsSection() {
  if (!state.adminAgentsLoadedAt && !state.adminAgentsLoading) {
    loadAdminAgents().then(() => {
      if (state.route === "admin" && state.adminPage === "ai-agents") {
        state.skipNextRouteAnimation = true;
        render();
      }
    });
  }
  const tokenPanel = state.adminAgentNewToken
    ? `
      <article class="admin-agent-token-card" role="status">
        <b>Token created for ${escapeHtml(state.adminAgentNewToken.name)}</b>
        <p>Show this once to your Hermes configuration. It will not be stored in readable form.</p>
        <code>${escapeHtml(state.adminAgentNewToken.token)}</code>
        <button class="btn ghost admin-btn-sm" type="button" data-action="admin-agent-hide-token">Hide token</button>
      </article>
    `
    : "";
  const hasAssistant = Boolean(getPrimaryAdminAssistant());
  const hasLoadedAssistants = Boolean(state.adminAgentsLoadedAt);
  const agentRows = (state.adminAgents || []).map((agent) => {
    const agentPermissions = getAdminAgentRowsByAgentId(state.adminAgentPermissions, agent.id);
    const hasFullAccess = agentPermissions.some((entry) => entry.permission_key === "full_admin");
    const permissions = agentPermissions
      .map((entry) => getAdminAgentPermissionLabel(entry.permission_key))
      .join(", ");
    const active = agent.status === "active";
    return `
      <tr>
        <td><b>${escapeHtml(agent.name)}</b><small class="subtle admin-agent-detail">${escapeHtml(agent.description || "No description")}</small></td>
        <td><span class="badge ${active ? "good" : "bad"}">${active ? "Active" : "Disabled"}</span></td>
        <td><small>${escapeHtml(permissions || "No permissions")}</small></td>
        <td><small>Ends ...${escapeHtml(agent.token_hint || "")}</small></td>
        <td><small>${agent.last_used_at ? escapeHtml(new Date(agent.last_used_at).toLocaleString()) : "Never"}</small></td>
        <td>
          <div class="stack">
            <button class="btn ${hasFullAccess ? "danger" : "ghost"} admin-btn-sm" type="button" data-action="admin-agent-set-full-access" data-agent-id="${escapeHtml(agent.id)}" data-agent-name="${escapeHtml(agent.name)}" data-enable="${hasFullAccess ? "false" : "true"}">${hasFullAccess ? "Remove full admin" : "Grant full admin"}</button>
            <button class="btn ghost admin-btn-sm" type="button" data-action="admin-agent-rotate-token" data-agent-id="${escapeHtml(agent.id)}" data-agent-name="${escapeHtml(agent.name)}">Rotate token</button>
            <button class="btn ${active ? "danger" : "ghost"} admin-btn-sm" type="button" data-action="admin-agent-set-status" data-agent-id="${escapeHtml(agent.id)}" data-next-status="${active ? "disabled" : "active"}">${active ? "Disable" : "Enable"}</button>
          </div>
        </td>
      </tr>
    `;
  }).join("");
  const approvalRows = (state.adminAgentApprovals || []).map((request) => {
    const agent = (state.adminAgents || []).find((row) => row.id === request.agent_id);
    const pending = request.status === "pending";
    const targetTitle = String(request.request_payload?.title || "").trim();
    const rawTargetBody = String(request.request_payload?.body || "").trim();
    const targetBody = rawTargetBody.length > 180 ? `${rawTargetBody.slice(0, 177)}...` : rawTargetBody;
    const requestReason = String(request.reason || "").trim();
    const requestDetail = [targetTitle, targetBody, requestReason].filter(Boolean).join(" - ");
    return `
      <tr>
        <td>${escapeHtml(agent?.name || "Removed agent")}</td>
        <td>
          ${escapeHtml(request.action_key)}
          ${requestDetail ? `<small class="subtle admin-agent-detail">${escapeHtml(requestDetail)}</small>` : ""}
        </td>
        <td><span class="badge ${pending ? "bad" : "good"}">${escapeHtml(request.status)}</span></td>
        <td><small>${escapeHtml(new Date(request.created_at).toLocaleString())}</small></td>
        <td>
          ${pending ? `
            <div class="stack">
              <button class="btn admin-btn-sm" type="button" data-action="admin-agent-approve-request" data-request-id="${escapeHtml(request.id)}">Approve</button>
              <button class="btn ghost admin-btn-sm" type="button" data-action="admin-agent-reject-request" data-request-id="${escapeHtml(request.id)}">Reject</button>
            </div>
          ` : "-"}
        </td>
      </tr>
    `;
  }).join("");
  const actionRows = (state.adminAgentActions || []).map((action) => {
    const agent = (state.adminAgents || []).find((row) => row.id === action.agent_id);
    return `
      <tr>
        <td><small>${escapeHtml(new Date(action.created_at).toLocaleString())}</small></td>
        <td>${escapeHtml(agent?.name || "Removed agent")}</td>
        <td>${escapeHtml(action.action_key)}</td>
        <td><span class="badge ${action.action_status === "success" ? "good" : "bad"}">${escapeHtml(action.action_status)}</span></td>
      </tr>
    `;
  }).join("");
  return `
    <section class="card admin-section admin-agent-section" id="admin-agents-section">
      <div class="flex-between">
        <div>
          <h3 style="margin:0;">Hermes Assistant</h3>
          <p class="subtle">One permanent administrator connection for Hermes. Set it up once, then rotate its token or disable it when needed.</p>
        </div>
        <button class="btn ghost admin-btn-sm ${state.adminAgentsLoading ? "is-loading" : ""}" type="button" data-action="admin-agents-refresh">${state.adminAgentsLoading ? "Refreshing..." : "Refresh"}</button>
      </div>
      ${state.adminAgentsError ? `<p class="subtle import-status is-error">${escapeHtml(state.adminAgentsError)}</p>` : ""}
      ${tokenPanel}
      ${hasLoadedAssistants && !hasAssistant ? `
        <article class="admin-agent-setup-card">
          <h4>Connect Hermes</h4>
          <p class="subtle">Create the single administrator connection and receive its token once.</p>
          <button class="btn ${state.adminAgentSaving ? "is-loading" : ""}" type="button" data-action="admin-assistant-initialize" ${state.adminAgentSaving ? "disabled" : ""}>${state.adminAgentSaving ? "Setting up..." : "Set up Hermes connection"}</button>
        </article>
      ` : ""}
      <h4>Connected assistant</h4>
      <div class="table-wrap">
        <table>
          <thead><tr><th>Assistant</th><th>Status</th><th>Permissions</th><th>Token</th><th>Last used</th><th>Actions</th></tr></thead>
          <tbody>${agentRows || `<tr><td colspan="6" class="subtle">Hermes has not been connected yet.</td></tr>`}</tbody>
        </table>
      </div>
      <div class="admin-agent-review-grid">
        <div>
          <h4>Approval requests</h4>
          <div class="table-wrap">
            <table>
              <thead><tr><th>Agent</th><th>Action</th><th>Status</th><th>Requested</th><th>Review</th></tr></thead>
              <tbody>${approvalRows || `<tr><td colspan="5" class="subtle">No requests pending.</td></tr>`}</tbody>
            </table>
          </div>
        </div>
        <div>
          <h4>Recent activity</h4>
          <div class="table-wrap">
            <table>
              <thead><tr><th>Time</th><th>Agent</th><th>Action</th><th>Result</th></tr></thead>
              <tbody>${actionRows || `<tr><td colspan="4" class="subtle">No agent activity yet.</td></tr>`}</tbody>
            </table>
          </div>
        </div>
      </div>
    </section>
  `;
}

