function toggleSessionFullscreen() {
  const shell = document.querySelector(".exam-shell-wrap");
  if (!shell) {
    return;
  }

  if (!document.fullscreenElement) {
    shell.requestFullscreen?.();
  } else {
    document.exitFullscreen?.();
  }
}

function applyCalculatorInput(value) {
  if (!value) {
    return;
  }
  if (state.calcExpression === "0" && value !== ".") {
    state.calcExpression = value;
    return;
  }
  state.calcExpression += value;
}

function evaluateCalculator() {
  const expression = String(state.calcExpression || "").trim();
  if (!expression) {
    return;
  }
  if (!/^[0-9+\-*/().% ]+$/.test(expression)) {
    toast("Invalid calculator expression.");
    return;
  }

  try {
    const result = Function(`"use strict"; return (${expression})`)();
    if (Number.isFinite(result)) {
      state.calcExpression = String(result);
    } else {
      toast("Invalid result.");
    }
  } catch {
    toast("Calculation error.");
  }
}

function addCurrentQuestionToFlashcards(userId, questionId) {
  const map = load(STORAGE_KEYS.flashcards, {});
  const deck = new Set(map[userId] || []);
  deck.add(questionId);
  map[userId] = [...deck];
  save(STORAGE_KEYS.flashcards, map);
}

function getNotebookEntries(userId) {
  const sessions = getAcademicTermScopedSessionsForUser(userId);
  const entries = [];
  sessions.forEach((session) => {
    session.questionIds.forEach((qid) => {
      const resolvedQuestionId = resolveSessionQuestionId(qid);
      const note = session.responses[qid]?.notes || session.responses[resolvedQuestionId]?.notes;
      if (note && note.trim()) {
        entries.push({ questionId: resolvedQuestionId || qid, note: note.trim() });
      }
    });
  });
  return entries;
}

function syncSessionTimingDisplays(session) {
  const elapsed = document.getElementById("elapsed-time");
  if (elapsed) {
    elapsed.textContent = formatElapsed(Math.max(0, Number(session?.elapsedSec || 0)));
  }

  const countdown = document.getElementById("countdown");
  if (countdown && String(session?.mode || "").trim() === "timed") {
    countdown.textContent = formatDuration(Math.max(0, Number(session?.timeRemainingSec || 0)));
  }
}

function advanceSessionClock(session, nowMs = Date.now()) {
  if (!session || String(session?.status || "").trim() !== "in_progress") {
    return { changed: false, expired: false, elapsedDeltaSec: 0 };
  }

  const safeNowMs = Number.isFinite(Number(nowMs)) ? Number(nowMs) : Date.now();
  const previousSyncAt = Number(session.lastTimerSyncAt || 0);
  if (!Number.isFinite(previousSyncAt) || previousSyncAt <= 0) {
    session.lastTimerSyncAt = safeNowMs;
    return { changed: true, expired: false, elapsedDeltaSec: 0 };
  }

  if (session.paused) {
    return { changed: false, expired: false, elapsedDeltaSec: 0 };
  }

  const elapsedDeltaSec = Math.max(0, Math.floor((safeNowMs - previousSyncAt) / 1000));
  if (!elapsedDeltaSec) {
    return { changed: false, expired: false, elapsedDeltaSec: 0 };
  }

  session.elapsedSec = Math.max(0, Number(session.elapsedSec || 0) + elapsedDeltaSec);
  if (session.mode === "timed") {
    session.timeRemainingSec = Math.max(0, Number(session.timeRemainingSec || 0) - elapsedDeltaSec);
    const activeQid = String(session.questionIds?.[session.currentIndex] || "").trim();
    const resolvedActiveQid = resolveSessionQuestionId(activeQid);
    const activeResponse = session.responses?.[activeQid] || session.responses?.[resolvedActiveQid];
    if (activeQid && activeResponse) {
      activeResponse.timeSpentSec = Math.max(
        0,
        Number(activeResponse.timeSpentSec || 0) + elapsedDeltaSec,
      );
    }
  }
  session.lastTimerSyncAt = previousSyncAt + (elapsedDeltaSec * 1000);
  return {
    changed: true,
    expired: session.mode === "timed" && Number(session.timeRemainingSec || 0) <= 0,
    elapsedDeltaSec,
  };
}

function syncSessionSnapshot(session, options = {}) {
  if (!session || String(session?.status || "").trim() !== "in_progress") {
    return { changed: false, expired: false, finalized: false };
  }
  const questionStore = options?.questionStore || getQuestionStore();
  normalizeSession(session, { questionStore });
  const clockResult = advanceSessionClock(session, options?.nowMs);
  if (clockResult.expired) {
    finalizeSession(session.id, {
      sessionOverride: session,
      questionStore,
      skipElapsedCapture: true,
    });
    return { ...clockResult, finalized: true };
  }
  if (clockResult.changed && options?.persist !== false) {
    session.updatedAt = nowISO();
    upsertSession(session, options?.persistOptions || {});
  }
  return { ...clockResult, finalized: false };
}

function persistInProgressSessionSnapshot(options = {}) {
  const currentUser = options?.user || getCurrentUser();
  if (!currentUser) {
    return null;
  }
  const session = options?.session || getActiveSession(currentUser.id, state.sessionId);
  if (!session || String(session?.status || "").trim() !== "in_progress") {
    return null;
  }
  const questionStore = options?.questionStore || getQuestionStore();
  normalizeSession(session, { questionStore });
  if (
    options?.syncSelectionFromDom !== false
    && state.route === "session"
    && String(state.sessionId || "").trim() === String(session.id || "").trim()
  ) {
    syncActiveResponseSelectionFromDom(session);
  }
  if (options?.captureElapsed !== false) {
    captureElapsedForCurrentQuestion(session);
  } else {
    const clockState = syncSessionSnapshot(session, {
      questionStore,
      nowMs: options?.nowMs,
      persist: false,
    });
    if (clockState.finalized) {
      if (options?.flush) {
        flushPendingSyncNow({ throwOnRelationalFailure: false }).catch(() => { });
      }
      return session;
    }
  }
  if (session.mode === "timed" && Number(session.timeRemainingSec || 0) <= 0) {
    finalizeSession(session.id, {
      sessionOverride: session,
      questionStore,
      skipElapsedCapture: true,
    });
    if (options?.flush) {
      flushPendingSyncNow({ throwOnRelationalFailure: false }).catch(() => { });
    }
    return session;
  }
  session.updatedAt = nowISO();
  upsertSession(session, { immediate: options?.immediate === true });
  if (options?.flush) {
    flushPendingSyncNow({ throwOnRelationalFailure: false }).catch(() => { });
  }
  return session;
}

function captureElapsedForCurrentQuestion(session) {
  if (!session) {
    return;
  }

  const nowMs = Date.now();
  advanceSessionClock(session, nowMs);

  if (session.mode === "timed") {
    session.lastQuestionAt = nowMs;
    return;
  }

  const previous = session.lastQuestionAt || nowMs;
  const elapsed = Math.max(0, Math.round((nowMs - previous) / 1000));
  const qid = session.questionIds[session.currentIndex];
  const resolvedQuestionId = resolveSessionQuestionId(qid);
  const response = session.responses[qid] || session.responses[resolvedQuestionId];
  if (response) {
    response.timeSpentSec += elapsed;
  }
  session.lastQuestionAt = nowMs;
}

function load(key, fallback) {
  const raw = readStorageKey(key);
  if (!raw) {
    return fallback;
  }
  if (
    key === STORAGE_KEYS.sessions
    && typeof raw === "string"
    && raw.length > SESSION_BROWSER_STORAGE_PARSE_CHAR_LIMIT
    && !inMemoryStorage.has(key)
    && canUseSessionVault()
  ) {
    warnLargeSessionStorageFallback();
    return fallback;
  }

  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(fallback)) {
      return Array.isArray(parsed) ? parsed : fallback;
    }
    if (fallback && typeof fallback === "object" && !Array.isArray(fallback)) {
      return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : fallback;
    }
    return parsed;
  } catch {
    return fallback;
  }
}

function stampAdminProfileWriteTimestamps(users, profileSyncIds) {
  const ids = new Set(
    (Array.isArray(profileSyncIds) ? profileSyncIds : [])
      .map((id) => String(id || "").trim())
      .filter((id) => isUuidValue(id)),
  );
  if (!ids.size || !Array.isArray(users)) {
    return;
  }
  const stamp = nowISO();
  users.forEach((user) => {
    const profileId = String(getUserProfileId(user) || "").trim();
    if (ids.has(profileId)) {
      user.profileUpdatedAt = maxIsoTimestamp(user.profileUpdatedAt, stamp);
    }
  });
}

function save(key, value, options = {}) {
  if (key === STORAGE_KEYS.users) {
    syncPendingEnrollmentScopeOverrides(load(STORAGE_KEYS.users, []), value);
    if (normalizeRelationalUserSyncScope(options?.userSyncScope) === USER_RELATIONAL_SYNC_SCOPE_ADMIN) {
      stampAdminProfileWriteTimestamps(value, options?.profileSyncIds);
    }
  }
  writeStorageKey(key, value);
  invalidateAnalyticsCacheForStorageKey(key);
  if (key === STORAGE_KEYS.sessions) {
    scheduleSessionStateSync(options);
  } else {
    scheduleRelationalWrite(key, value, options);
    if (key === STORAGE_KEYS.users) {
      syncUsersBackupState(value);
    } else if (!RELATIONAL_SYNC_KEY_SET.has(key) || RELATIONAL_BACKUP_SYNC_KEY_SET.has(key)) {
      scheduleSupabaseWrite(key, value);
    }
  }
  appendStorageMutationLog("save", key, value);
}

function readStorageKey(key) {
  if (key === STORAGE_KEYS.sessions && inMemoryStorage.has(key)) {
    return inMemoryStorage.get(key) ?? null;
  }
  try {
    const localValue = localStorage.getItem(key);
    if (localValue != null) {
      return localValue;
    }
  } catch (error) {
    warnStorageFallback(error);
  }
  const sessionValue = readSessionStorageKey(key);
  if (sessionValue != null) {
    return sessionValue;
  }
  return inMemoryStorage.get(key) ?? null;
}

function isSilentStorageQuotaFallbackKey(key) {
  return key === STORAGE_KEYS.questions || key === STORAGE_KEYS.sessions || key === STORAGE_KEYS.users;
}

function warnStorageQuotaFallbackForKey(key) {
  if (key === STORAGE_KEYS.questions) {
    warnLargeQuestionStorageFallback();
  } else if (key === STORAGE_KEYS.sessions) {
    warnLargeSessionStorageFallback();
  }
}

function bumpQuestionsRevisionForStorageKey(key) {
  if (key === STORAGE_KEYS.questions) {
    state.questionsRevision = (state.questionsRevision || 0) + 1;
  }
}

function writeStorageKey(key, value) {
  if (key !== STORAGE_KEYS.sessions) {
    invalidateCollectionRuntimeForStorageKey(key);
  }
  if (key === STORAGE_KEYS.sessions) {
    scheduleSessionVaultPersist(value);
    let browserSerialized = "[]";
    try {
      browserSerialized = JSON.stringify(compactSessionsForBrowserStorage(value));
    } catch (error) {
      console.warn("Could not serialize compact session storage payload.", error?.message || error);
      return;
    }
    if (Array.isArray(value)) {
      sessionStoreRuntime.initialized = true;
      sessionStoreRuntime.list = value;
      sessionStoreRuntime.byId = new Map(value.map((session) => [String(session?.id || "").trim(), session]));
      invalidateSessionStoreVisibleCache();
      invalidateAnalyticsCacheForStorageKey(STORAGE_KEYS.sessions);
    }

    const persistTransientSessionStorageOnly = ({ rememberQuotaOverflow = false } = {}) => {
      inMemoryStorage.delete(key);
      writeSessionStorageKey(key, browserSerialized);
      try {
        localStorage.removeItem(key);
      } catch {
        // Ignore when persistent storage is blocked.
      }
      if (rememberQuotaOverflow) {
        storageQuotaRetryThresholds.set(key, browserSerialized.length);
      }
      bumpQuestionsRevisionForStorageKey(key);
    };

    const knownQuotaOverflowThreshold = Number(storageQuotaRetryThresholds.get(key));
    if (
      Number.isFinite(knownQuotaOverflowThreshold)
      && browserSerialized.length >= knownQuotaOverflowThreshold
    ) {
      warnLargeSessionStorageFallback();
      persistTransientSessionStorageOnly({ rememberQuotaOverflow: true });
      return;
    }

    try {
      localStorage.setItem(key, browserSerialized);
      writeSessionStorageKey(key, browserSerialized);
      inMemoryStorage.delete(key);
      storageQuotaRetryThresholds.delete(key);
    } catch (error) {
      if (isStorageQuotaExceededError(error)) {
        warnLargeSessionStorageFallback();
        persistTransientSessionStorageOnly({ rememberQuotaOverflow: true });
        return;
      }
      warnStorageFallback(error);
      writeSessionStorageKey(key, browserSerialized);
    }
    bumpQuestionsRevisionForStorageKey(key);
    return;
  }

  let serialized = null;
  try {
    serialized = JSON.stringify(value);
  } catch (error) {
    console.warn(`Could not serialize storage key "${key}".`, error);
    return;
  }
  let browserSerialized = serialized;

  const persistTransientStorageOnly = ({ includeSessionStorage = true, rememberQuotaOverflow = false } = {}) => {
    inMemoryStorage.set(key, serialized);
    if (includeSessionStorage) {
      writeSessionStorageKey(key, browserSerialized);
    } else {
      removeSessionStorageKey(key);
    }
    try {
      localStorage.removeItem(key);
    } catch {
      // Ignore when persistent storage is blocked.
    }
    if (rememberQuotaOverflow) {
      storageQuotaRetryThresholds.set(key, serialized.length);
    }
    bumpQuestionsRevisionForStorageKey(key);
  };

  const shouldKeepQuestionsInMemoryOnly = (
    key === STORAGE_KEYS.questions
    && typeof serialized === "string"
    && serialized.length >= LARGE_QUESTION_STORAGE_CHAR_LIMIT
  );
  if (shouldKeepQuestionsInMemoryOnly) {
    warnLargeQuestionStorageFallback();
    persistTransientStorageOnly({ includeSessionStorage: false });
    return;
  }

  const knownQuotaOverflowThreshold = Number(storageQuotaRetryThresholds.get(key));
  if (
    isSilentStorageQuotaFallbackKey(key)
    && Number.isFinite(knownQuotaOverflowThreshold)
    && browserSerialized.length >= knownQuotaOverflowThreshold
  ) {
    warnStorageQuotaFallbackForKey(key);
    persistTransientStorageOnly({
      includeSessionStorage: key !== STORAGE_KEYS.questions,
      rememberQuotaOverflow: true,
    });
    return;
  }

  try {
    localStorage.setItem(key, browserSerialized);
    writeSessionStorageKey(key, browserSerialized);
    inMemoryStorage.delete(key);
    storageQuotaRetryThresholds.delete(key);
  } catch (error) {
    if (isSilentStorageQuotaFallbackKey(key) && isStorageQuotaExceededError(error)) {
      warnStorageQuotaFallbackForKey(key);
      persistTransientStorageOnly({
        includeSessionStorage: key !== STORAGE_KEYS.questions,
        rememberQuotaOverflow: true,
      });
      return;
    }
    warnStorageFallback(error);
    writeSessionStorageKey(key, browserSerialized);
    inMemoryStorage.set(key, serialized);
  }
  bumpQuestionsRevisionForStorageKey(key);
}

function removeStorageKey(key) {
  invalidateCollectionRuntimeForStorageKey(key);
  inMemoryStorage.delete(key);
  storageQuotaRetryThresholds.delete(key);
  removeSessionStorageKey(key);
  try {
    localStorage.removeItem(key);
  } catch (error) {
    warnStorageFallback(error);
  }
  appendStorageMutationLog("remove", key, null);
}

function readSessionStorageKey(key) {
  try {
    return sessionStorage.getItem(key);
  } catch {
    return null;
  }
}

function writeSessionStorageKey(key, value) {
  try {
    sessionStorage.setItem(key, value);
  } catch {
    // Ignore when sessionStorage is blocked.
  }
}

function removeSessionStorageKey(key) {
  try {
    sessionStorage.removeItem(key);
  } catch {
    // Ignore when sessionStorage is blocked.
  }
}

async function loginAsDemo(email, password) {
  if (SUPABASE_CONFIG.enabled && !isLocalDemoAuthEnabled()) {
    toast("Demo accounts are only available on localhost.");
    return;
  }
  const user = getUsers().find((entry) => entry.email === email && entry.password === password);
  if (!user) {
    toast("Demo account unavailable.");
    return;
  }
  const completionRoute = getStudentProfileCompletionRoute(user);
  if (completionRoute) {
    save(STORAGE_KEYS.currentUserId, user.id);
    toast("Complete your profile to continue.");
    navigate(completionRoute);
    return;
  }
  if (!isUserAccessApproved(user)) {
    toast("This account is pending admin approval.");
    return;
  }
  save(STORAGE_KEYS.currentUserId, user.id);
  resetStudentLoginRefreshState(user);
  if (await shouldForceRefreshForUpdates(user)) {
    return;
  }
  state.studentMcqBankEntered = false;
  appendSystemLog("auth.login", `Logged in as ${user.email}`, {
    userId: user.id,
    role: user.role,
    auth: "demo",
  }, { force: true });
  navigate(user.role === "admin" ? "admin" : "app-launcher");
}

async function logout(options = {}) {
  const actor = options?.actor || getCurrentUser();
  const route = options?.route === "login" ? "login" : "landing";
  const notice = typeof options?.message === "string" ? String(options.message || "").trim() : "Logged out.";
  const isAccessRevoked = options?.reason === "access-revoked";
  appendSystemLog(
    isAccessRevoked ? "auth.access_revoked" : "auth.logout",
    `${isAccessRevoked ? "User access revoked" : "User logged out"}: ${String(actor?.email || actor?.id || "unknown")}`,
    {
      userId: String(actor?.id || ""),
      role: String(actor?.role || ""),
    },
    { force: true },
  );
  const shouldFlushBeforeLogout = Boolean(
    sessionSyncRuntime.dirty
    || sessionSyncRuntime.flushing
    || relationalSync.pendingWrites.size
    || relationalSync.flushing
    || supabaseSync.pendingWrites.size
    || supabaseSync.flushing
    || getPendingAdminActionQueue().length
  );
  if (shouldFlushBeforeLogout) {
    await flushPendingSyncNow({ throwOnRelationalFailure: false }).catch((error) => {
      console.warn("Could not flush pending sync work before logout.", error?.message || error);
    });
  }
  const offlinePromise = markCurrentUserOffline().catch(() => { });
  const activityEndPromise = endCurrentUserActivitySession().catch(() => { });
  const authClient = getSupabaseAuthClient();
  if (authClient) {
    suppressSupabaseSignedOutRecovery = true;
  }
  const signOutPromise = authClient
    ? queueSupabaseAuthRequest(authClient, () => authClient.auth.signOut()).catch((error) => {
      console.warn("Supabase sign-out failed.", error?.message || error);
    })
    : Promise.resolve();

  syncPresenceRuntime(null);
  resetSiteActivityRuntime();
  clearSupabaseSessionRecoveryRetry();
  clearNotificationRealtimeSubscription();
  clearSessionRealtimeSubscription();
  clearContentRealtimeSubscription();
  clearStudentRefreshRealtimeSubscription();
  clearProfileAccessRealtimeSubscription();
  resetQuestionImageRuntimeState();
  clearStudentAccessPolling();
  clearStudentBackgroundRefreshPolling();
  clearAdminPresencePolling();
  clearAdminDashboardPolling();
  clearBackgroundSync();
  resetRelationalSyncState();
  resetSupabaseSyncRuntimeState();
  resetPendingAdminActionRuntimeState();
  resetPostAuthWarmupRuntimeState();
  clearPersistedActiveSessionId();
  supabaseAuth.activeUserId = "";
  removeStorageKey(STORAGE_KEYS.currentUserId);
  setGoogleOAuthPendingState(false);
  setPasswordRecoveryPendingState(false);
  state.adminUserEnrollmentDrafts = {};
  state.adminUserEnrollmentSaving = {};
  state.userMenuOpen = false;
  state.notificationMenuOpen = false;
  state.studentMcqBankEntered = false;
  state.sessionId = null;
  state.reviewSessionId = null;
  state.reviewIndex = 0;
  navigate(route);
  if (notice) {
    toast(notice);
  }
  Promise.allSettled([offlinePromise, activityEndPromise, signOutPromise]).catch(() => { });
}

async function logoutDueToAccessRevocation(message = ACCOUNT_DEACTIVATED_SUPPORT_MESSAGE) {
  await logout({
    route: "login",
    message,
    reason: "access-revoked",
  });
}

function selectHtml(name, options, selected) {
  return `
    <select name="${name}">
      <option value="">All</option>
      ${options
      .map((option) => `<option value="${escapeHtml(option)}" ${selected === option ? "selected" : ""}>${escapeHtml(option)}</option>`)
      .join("")}
    </select>
  `;
}

function uniqueValues(values) {
  return [...new Set(values.filter(Boolean))].sort((a, b) => String(a).localeCompare(String(b)));
}

function makeId(prefix) {
  return `${prefix}_${Math.random().toString(36).slice(2, 8)}_${Date.now().toString(36).slice(-4)}`;
}

function nowISO() {
  return new Date().toISOString();
}

function arraysEqual(a, b) {
  return a.length === b.length && a.every((entry, idx) => entry === b[idx]);
}

function getNormalizedQuestionCorrectChoiceIds(question) {
  const choices = normalizeQuestionChoiceEntries(question?.choices);
  if (!choices.length) {
    return [];
  }
  const choiceIds = new Set(choices.map((choice) => choice.id));
  const explicitCorrectIds = [...new Set(
    (Array.isArray(question?.correct) ? question.correct : [])
      .map((entry) => normalizeQuestionChoiceLabel(entry))
      .filter((entry) => choiceIds.has(entry)),
  )].sort();
  if (explicitCorrectIds.length) {
    return explicitCorrectIds;
  }

  return [...new Set(
    (Array.isArray(question?.choices) ? question.choices : [])
      .filter((choice) => Boolean(choice?.correct) || Boolean(choice?.is_correct))
      .map((choice) => normalizeQuestionChoiceLabel(choice?.id || choice?.choice_label || choice?.label))
      .filter((entry) => choiceIds.has(entry)),
  )].sort();
}

function didQuestionCorrectAnswerChange(previousQuestion, nextQuestion) {
  if (!previousQuestion || !nextQuestion) {
    return false;
  }
  const previousCorrect = getNormalizedQuestionCorrectChoiceIds(previousQuestion);
  const nextCorrect = getNormalizedQuestionCorrectChoiceIds(nextQuestion);
  return !arraysEqual(previousCorrect, nextCorrect);
}

function ensureCorrectedQuestionsTopicForCourse(course) {
  const courseName = String(course || "").trim();
  if (!courseName) {
    return CORRECTED_QUESTIONS_TOPIC_NAME;
  }

  const existingTopics = normalizeCourseTopicList(
    COURSE_TOPIC_OVERRIDES[courseName] || QBANK_COURSE_TOPICS[courseName] || [],
    courseName,
  );
  const existingCorrectedTopic = findMatchingTopicNameInList(existingTopics, CORRECTED_QUESTIONS_TOPIC_NAME);
  if (existingCorrectedTopic) {
    return existingCorrectedTopic;
  }

  const previousTopics = [...(QBANK_COURSE_TOPICS[courseName] || existingTopics)];
  COURSE_TOPIC_OVERRIDES[courseName] = normalizeCourseTopicList(
    [...existingTopics, CORRECTED_QUESTIONS_TOPIC_NAME],
    courseName,
  );
  rebuildCurriculumCatalog();
  save(STORAGE_KEYS.courseTopics, COURSE_TOPIC_OVERRIDES);
  syncTopicNewCatalogForCourse(courseName, previousTopics, COURSE_TOPIC_OVERRIDES[courseName] || [], {
    addedBy: "corrected_questions",
  });
  return CORRECTED_QUESTIONS_TOPIC_NAME;
}

function getCorrectedQuestionNotificationRecipients(course, users = null) {
  const courseName = String(course || "").trim();
  if (!courseName) {
    return [];
  }
  const sourceUsers = Array.isArray(users) ? users : getCloudNotificationTargetUsers(getUsers());
  return sourceUsers.filter((entry) => {
    if (String(entry?.role || "").trim().toLowerCase() !== "student" || !isUserAccessApproved(entry)) {
      return false;
    }
    return getAvailableCoursesForUser(entry).some((availableCourse) => doCourseNamesMatch(availableCourse, courseName));
  });
}

function queueCorrectedQuestionNotifications(question, previousQuestion = null) {
  const currentUser = getCurrentUser();
  if (!currentUser || currentUser.role !== "admin") {
    return [];
  }

  const meta = getQbankCourseTopicMeta(question);
  const courseName = String(meta.course || question?.qbankCourse || question?.course || "").trim();
  if (!courseName || String(question?.status || "published").trim().toLowerCase() !== "published") {
    return [];
  }

  const users = getCloudNotificationTargetUsers(getUsers());
  const recipients = getCorrectedQuestionNotificationRecipients(courseName, users);
  if (!recipients.length) {
    return [];
  }

  const previousCorrect = getNormalizedQuestionCorrectChoiceIds(previousQuestion).join(", ") || "previous answer";
  const nextCorrect = getNormalizedQuestionCorrectChoiceIds(question).join(", ") || "updated answer";
  const title = "Corrected question available";
  const body = [
    `A question in ${courseName} was corrected.`,
    `Correct answer changed from ${previousCorrect} to ${nextCorrect}.`,
    `Open Create test, choose ${courseName}, then select ${CORRECTED_QUESTIONS_TOPIC_NAME} to solve it again.`,
  ].join(" ");
  const createdAt = nowISO();
  const createdByName = String(currentUser.name || "Admin").trim() || "Admin";
  const localNotifications = [];

  recipients.forEach((recipient) => {
    const targetUserId = String(getUserProfileId(recipient) || recipient?.id || "").trim();
    if (!isUuidValue(targetUserId)) {
      return;
    }
    const notification = normalizeNotificationRecord({
      id: crypto.randomUUID(),
      targetType: "user",
      targetUserId,
      title,
      body,
      createdAt,
      createdById: String(currentUser.id || "").trim(),
      createdByName,
      readByUserIds: [],
    });
    if (!notification) {
      return;
    }
    localNotifications.push(notification);
    queueNotificationForCloudDelivery(notification);
  });

  if (localNotifications.length) {
    saveNotificationsLocal([...localNotifications, ...getNotifications()]);
  }
  return localNotifications.map((entry) => entry.id);
}

function getNormalizedResponseSelectedChoiceIds(response, allowedChoiceIds = null) {
  const allowed = allowedChoiceIds instanceof Set ? allowedChoiceIds : null;
  return [...new Set(
    (Array.isArray(response?.selected) ? response.selected : [])
      .map((entry) => normalizeQuestionChoiceLabel(entry))
      .filter((entry) => Boolean(entry) && (!allowed || allowed.has(entry))),
  )].sort();
}

function isResponseSelectionCorrect(question, response) {
  if (!question || !response) {
    return false;
  }
  const choiceIds = new Set(normalizeQuestionChoiceEntries(question?.choices).map((choice) => choice.id));
  const correct = getNormalizedQuestionCorrectChoiceIds(question);
  if (!correct.length) {
    return false;
  }
  const selected = getNormalizedResponseSelectedChoiceIds(response, choiceIds);
  if (!selected.length) {
    return false;
  }
  return arraysEqual(selected, correct);
}

function isSubmittedResponseCorrect(question, response) {
  if (!question || !response || !response.submitted) {
    return false;
  }
  return isResponseSelectionCorrect(question, response);
}

function shuffle(list) {
  const arr = [...list];
  for (let i = arr.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function formatDuration(seconds) {
  const safe = Math.max(0, seconds || 0);
  const mm = String(Math.floor(safe / 60)).padStart(2, "0");
  const ss = String(safe % 60).padStart(2, "0");
  return `${mm}:${ss}`;
}

function formatElapsed(seconds) {
  const safe = Math.max(0, seconds || 0);
  const hh = String(Math.floor(safe / 3600)).padStart(2, "0");
  const mm = String(Math.floor((safe % 3600) / 60)).padStart(2, "0");
  const ss = String(safe % 60).padStart(2, "0");
  return `${hh}:${mm}:${ss}`;
}

function escapeHtml(value) {
  return String(value || "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function toast(message) {
  const template = document.getElementById("toast-template");
  const node = template.content.firstElementChild.cloneNode(true);
  node.textContent = message;
  document.body.appendChild(node);
  window.setTimeout(() => {
    node.remove();
  }, 2400);
}

function renderBootstrapFallback() {
  try {
    clearNotificationRealtimeSubscription();
    clearSessionRealtimeSubscription();
    clearContentRealtimeSubscription();
    clearProfileAccessRealtimeSubscription();
    clearStudentAccessPolling();
    clearBackgroundSync();
    setGoogleOAuthPendingState(false);
    clearAdminDashboardPolling();
    document.body.classList.remove("is-routing");
    appEl.classList.remove("route-enter", "route-enter-active", "is-session", "is-admin");
    topbarEl?.classList.remove("hidden", "admin-only-header");
    publicNavEl?.classList.remove("hidden");
    privateNavEl?.classList.add("hidden");
    adminLinkEl?.classList.add("hidden");
    authActionsEl?.classList.remove("hidden");
    if (authActionsEl) {
      authActionsEl.innerHTML = `
        ${renderThemeToggleButton()}
        <button data-nav="login">Login</button>
        <button class="btn" data-nav="signup">Sign up</button>
      `;
    }
    appEl.innerHTML = renderLanding();
  } catch (fallbackError) {
    console.error("Fallback render failed:", fallbackError);
  }
}

