function normalizeCoursePlatformMode(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (normalized === "request") {
    return normalized;
  }
  return "assigned";
}

function normalizeCoursePlatformType(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (normalized === "mcq_only" || normalized === "lessons_only") {
    return normalized;
  }
  return "mcq_and_lessons";
}

function getCoursesPlatformClient() {
  return getRelationalClient();
}

const ADMIN_COURSE_PLATFORM_PROFILE_SELECT = "id,full_name,email,phone,academic_year,academic_semester,role,approved,courses_access_enabled";

function normalizeAdminCoursePlatformProfileRow(profile = {}) {
  const profileId = String(profile?.id || "").trim();
  if (!isUuidValue(profileId)) {
    return null;
  }
  const role = String(profile?.role || "student").trim().toLowerCase() === "admin" ? "admin" : "student";
  return {
    id: profileId,
    full_name: String(profile?.full_name || profile?.name || profile?.email || "Student").trim() || "Student",
    email: String(profile?.email || "").trim().toLowerCase(),
    phone: String(profile?.phone || "").trim(),
    academic_year: role === "student" ? normalizeAcademicYearOrNull(profile?.academic_year ?? profile?.academicYear) : null,
    academic_semester: role === "student" ? normalizeAcademicSemesterOrNull(profile?.academic_semester ?? profile?.academicSemester) : null,
    role,
    approved: role === "admin" ? true : profile?.approved !== false && profile?.isApproved !== false,
    courses_access_enabled: role === "admin" ? true : profile?.courses_access_enabled !== false && profile?.coursesAccessEnabled !== false,
  };
}

function buildAdminCoursePlatformProfileRowsFromLocalUsers(users = null) {
  const list = Array.isArray(users) ? users : getUsers();
  return list
    .filter((user) => hasSupabaseManagedIdentity(user) && !isLegacyDemoUser(user))
    .map((user) => normalizeAdminCoursePlatformProfileRow({
      id: getUserProfileId(user),
      full_name: user?.name,
      email: user?.email,
      phone: user?.phone,
      academic_year: user?.academicYear,
      academic_semester: user?.academicSemester,
      role: user?.role,
      approved: user?.isApproved,
      courses_access_enabled: user?.coursesAccessEnabled,
    }))
    .filter(Boolean);
}

function mergeAdminCoursePlatformProfiles(...profileLists) {
  const byId = new Map();
  profileLists.flat().forEach((profile) => {
    const normalized = normalizeAdminCoursePlatformProfileRow(profile);
    if (!normalized) {
      return;
    }
    const existing = byId.get(normalized.id);
    byId.set(normalized.id, existing ? { ...normalized, ...existing } : normalized);
  });
  return [...byId.values()]
    .sort((left, right) => getAdminPlatformProfileDisplayName(left).localeCompare(getAdminPlatformProfileDisplayName(right)));
}

function patchAdminCoursePlatformCourse(courseId, patch = {}) {
  const targetCourseId = String(courseId || "").trim();
  if (!isUuidValue(targetCourseId) || !patch || typeof patch !== "object") {
    return;
  }
  const courses = Array.isArray(state.adminCoursesPlatformCourses)
    ? state.adminCoursesPlatformCourses
    : [];
  const index = courses.findIndex((course) => String(course?.id || "").trim() === targetCourseId);
  if (index < 0) {
    return;
  }
  state.adminCoursesPlatformCourses = [
    ...courses.slice(0, index),
    {
      ...courses[index],
      ...patch,
      id: targetCourseId,
    },
    ...courses.slice(index + 1),
  ];
}

function resetStudentCoursesPlatformState() {
  if (coursesPlatformRuntime.emptyEnrollmentRetryTimer) {
    window.clearTimeout(coursesPlatformRuntime.emptyEnrollmentRetryTimer);
    coursesPlatformRuntime.emptyEnrollmentRetryTimer = null;
  }
  state.coursesLoadedAt = 0;
  state.coursesLoading = false;
  state.coursesError = "";
  state.coursesCatalog = [];
  state.coursesEnrollments = [];
  state.coursesRequests = [];
  state.coursesProgress = [];
  state.coursesDetail = null;
  state.coursesModules = [];
  state.coursesLessons = [];
  state.coursesResources = [];
  state.coursesAnnouncements = [];
  state.coursesSuggestions = [];
  state.coursesActiveCourseId = "";
  state.coursesActiveLessonId = "";
  state.coursesView = "home";
}

function isCoursesComingSoonEnabled() {
  return Boolean(state.coursesComingSoonEnabled);
}

function isCoursesPlatformTransientCooldownActive(kind) {
  const key = kind === "availability" ? "availabilityTransientFailureAt" : "platformTransientFailureAt";
  const failedAt = Number(coursesPlatformRuntime[key] || 0);
  return failedAt > 0 && (Date.now() - failedAt) < COURSES_PLATFORM_TRANSIENT_FAILURE_COOLDOWN_MS;
}

function recordCoursesPlatformTransientFailure(kind, error) {
  const atKey = kind === "availability" ? "availabilityTransientFailureAt" : "platformTransientFailureAt";
  const messageKey = kind === "availability" ? "availabilityTransientFailureMessage" : "platformTransientFailureMessage";
  if (!error || !isLikelyTransientSupabaseError(error)) {
    coursesPlatformRuntime[atKey] = 0;
    coursesPlatformRuntime[messageKey] = "";
    return false;
  }
  coursesPlatformRuntime[atKey] = Date.now();
  coursesPlatformRuntime[messageKey] = getErrorMessage(error, "Video Courses are temporarily unavailable.");
  return true;
}

function clearCoursesPlatformTransientFailure(kind) {
  const atKey = kind === "availability" ? "availabilityTransientFailureAt" : "platformTransientFailureAt";
  const messageKey = kind === "availability" ? "availabilityTransientFailureMessage" : "platformTransientFailureMessage";
  coursesPlatformRuntime[atKey] = 0;
  coursesPlatformRuntime[messageKey] = "";
}

function shouldBlockStudentCoursesPortal(user = getCurrentUser()) {
  return Boolean(getStudentCoursesPortalBlockReason(user));
}

function getStudentCoursesPortalBlockReason(user = getCurrentUser()) {
  if (user?.role !== "student") {
    return "";
  }
  if (!isUserCoursesAccessEnabled(user)) {
    return "courses_access_disabled";
  }
  if (isCoursesComingSoonEnabled()) {
    return "courses_coming_soon";
  }
  return "";
}

function applyCoursesComingSoonFlag(enabled) {
  const nextEnabled = Boolean(enabled);
  const changed = state.coursesComingSoonEnabled !== nextEnabled;
  state.coursesComingSoonEnabled = nextEnabled;
  state.coursesComingSoonLoadedAt = Date.now();
  state.coursesComingSoonError = "";
  if (nextEnabled && getCurrentUser()?.role === "student") {
    resetStudentCoursesPlatformState();
  }
  return changed;
}

async function loadCoursesComingSoonFlag(options = {}) {
  const force = Boolean(options?.force);
  if (state.coursesComingSoonLoading && !force) {
    return !state.coursesComingSoonError;
  }
  if (!force && isCoursesPlatformTransientCooldownActive("availability")) {
    if (!state.coursesComingSoonLoadedAt) {
      state.coursesComingSoonLoadedAt = Date.now();
    }
    return true;
  }
  if (!force && state.coursesComingSoonLoadedAt && Date.now() - state.coursesComingSoonLoadedAt < STUDENT_DATA_REFRESH_MS) {
    return true;
  }
  const client = getCoursesPlatformClient();
  if (!client) {
    return false;
  }
  state.coursesComingSoonLoading = true;
  let missingFeatureFlagTable = false;
  try {
    const row = await runRelationalQueryWithTimeout(
      client
        .from("app_feature_flags")
        .select("feature_key,enabled,updated_at")
        .eq("feature_key", COURSES_COMING_SOON_FEATURE_KEY)
        .maybeSingle(),
      "Video Courses availability check timed out.",
    ).catch((error) => {
      if (isMissingRelationError(error)) {
        missingFeatureFlagTable = true;
        return null;
      }
      throw error;
    });
    const changed = applyCoursesComingSoonFlag(Boolean(row?.enabled));
    if (missingFeatureFlagTable) {
      state.coursesComingSoonError = COURSES_COMING_SOON_MIGRATION_REQUIRED_MESSAGE;
      if (changed) {
        resetStudentCoursesPlatformState();
      }
    } else {
      state.coursesComingSoonError = "";
    }
    clearCoursesPlatformTransientFailure("availability");
    return true;
  } catch (error) {
    if (recordCoursesPlatformTransientFailure("availability", error)) {
      if (!state.coursesComingSoonLoadedAt) {
        state.coursesComingSoonLoadedAt = Date.now();
      }
      state.coursesComingSoonError = "";
      return true;
    }
    console.warn("Could not load Video Courses availability flag.", error?.message || error);
    state.coursesComingSoonError = getErrorMessage(error, "Could not check Courses availability.");
    return false;
  } finally {
    state.coursesComingSoonLoading = false;
  }
}

async function saveCoursesComingSoonFlag(enabled) {
  const client = getCoursesPlatformClient();
  const currentUser = getCurrentUser();
  if (!client || currentUser?.role !== "admin") {
    throw new Error("Only admins can update Video Courses availability.");
  }
  const payload = {
    feature_key: COURSES_COMING_SOON_FEATURE_KEY,
    enabled: Boolean(enabled),
    description: "When enabled, students see Coming soon instead of the Video Courses portal.",
    updated_by: isUuidValue(getUserProfileId(currentUser)) ? getUserProfileId(currentUser) : null,
  };
  state.coursesComingSoonSaving = true;
  try {
    await runRelationalQueryWithTimeout(
      client.from("app_feature_flags").upsert(payload, { onConflict: "feature_key", defaultToNull: false }),
      "Video Courses availability update timed out.",
    ).catch((error) => {
      if (isMissingRelationError(error)) {
        state.coursesComingSoonError = COURSES_COMING_SOON_MIGRATION_REQUIRED_MESSAGE;
        throw new Error(COURSES_COMING_SOON_MIGRATION_REQUIRED_MESSAGE);
      }
      throw error;
    });
    applyCoursesComingSoonFlag(Boolean(enabled));
    return true;
  } finally {
    state.coursesComingSoonSaving = false;
  }
}

function isLocalDemoCoursePlatformUser(user = getCurrentUser()) {
  return isLocalDemoAuthEnabled()
    && isLegacyDemoUser(user)
    && String(user?.role || "").trim() === "student";
}

function getCurrentCoursePlatformUserId() {
  const user = getCurrentUser();
  if (isLocalDemoCoursePlatformUser(user)) {
    return String(user?.id || "").trim();
  }
  return String(getCurrentSessionProfileId(user) || getUserProfileId(user) || "").trim();
}

function getCoursePlatformCacheKeys(user = getCurrentUser()) {
  return [
    getCurrentCoursePlatformUserId(),
    getCurrentSessionProfileId(user),
    getUserProfileId(user),
    user?.id,
    user?.supabaseAuthId,
  ]
    .map((entry) => String(entry || "").trim())
    .filter((entry, index, entries) => entry && entries.indexOf(entry) === index);
}

function normalizeStudentCoursesPlatformPayload(payload) {
  const source = payload && typeof payload === "object" && !Array.isArray(payload) ? payload : {};
  return {
    courses: Array.isArray(source.courses) ? source.courses : [],
    enrollments: Array.isArray(source.enrollments) ? source.enrollments : [],
    requests: Array.isArray(source.requests) ? source.requests : [],
    progress: Array.isArray(source.progress) ? source.progress : [],
    lessons: Array.isArray(source.lessons) ? source.lessons : [],
    modules: Array.isArray(source.modules) ? source.modules : [],
    resources: Array.isArray(source.resources) ? source.resources : [],
    announcements: Array.isArray(source.announcements) ? source.announcements : [],
    suggestions: Array.isArray(source.suggestions) ? source.suggestions : [],
    loadedAt: Number(source.loadedAt || source.cachedAt || 0) || 0,
  };
}

function applyStudentCoursesPlatformPayload(payload, options = {}) {
  const data = normalizeStudentCoursesPlatformPayload(payload);
  state.coursesCatalog = data.courses;
  state.coursesEnrollments = data.enrollments;
  state.coursesRequests = data.requests;
  state.coursesProgress = data.progress;
  state.coursesLessons = data.lessons;
  state.coursesModules = data.modules;
  state.coursesResources = data.resources;
  state.coursesAnnouncements = data.announcements;
  state.coursesSuggestions = data.suggestions;
  state.coursesLoadedAt = Number(options.loadedAt || data.loadedAt || Date.now()) || Date.now();
  state.coursesError = "";
  return data;
}

function readStudentCoursesPlatformCache(user = getCurrentUser()) {
  const cache = load(STORAGE_KEYS.coursePlatformCache, {});
  const keys = getCoursePlatformCacheKeys(user);
  const now = Date.now();
  for (const key of keys) {
    const entry = cache?.[key];
    const data = normalizeStudentCoursesPlatformPayload(entry?.data || entry);
    const cachedAt = Number(entry?.cachedAt || data.loadedAt || 0);
    if (!cachedAt || now - cachedAt > COURSES_PLATFORM_CACHE_MAX_AGE_MS) {
      continue;
    }
    if (
      data.courses.length
      || data.enrollments.length
      || data.requests.length
      || data.suggestions.length
    ) {
      return { ...data, loadedAt: cachedAt };
    }
  }
  return null;
}

function applyCachedStudentCoursesPlatformPayload(user = getCurrentUser()) {
  const cached = readStudentCoursesPlatformCache(user);
  if (!cached) {
    return false;
  }
  applyStudentCoursesPlatformPayload(cached, { loadedAt: cached.loadedAt });
  return true;
}

function persistStudentCoursesPlatformCache(user = getCurrentUser()) {
  const keys = getCoursePlatformCacheKeys(user);
  if (!keys.length) {
    return;
  }
  const cachedAt = Date.now();
  const cache = load(STORAGE_KEYS.coursePlatformCache, {});
  const entry = {
    cachedAt,
    appVersion: APP_VERSION,
    data: normalizeStudentCoursesPlatformPayload({
      courses: state.coursesCatalog,
      enrollments: state.coursesEnrollments,
      requests: state.coursesRequests,
      progress: state.coursesProgress,
      lessons: state.coursesLessons,
      modules: state.coursesModules,
      resources: state.coursesResources,
      announcements: state.coursesAnnouncements,
      suggestions: state.coursesSuggestions,
      loadedAt: state.coursesLoadedAt || cachedAt,
    }),
  };
  keys.forEach((key) => {
    cache[key] = entry;
  });
  saveLocalOnly(STORAGE_KEYS.coursePlatformCache, cache, { audit: false });
}

function scheduleStudentCoursesEmptyEnrollmentRetry() {
  if (coursesPlatformRuntime.emptyEnrollmentRetryTimer) {
    return;
  }
  coursesPlatformRuntime.emptyEnrollmentRetryTimer = window.setTimeout(() => {
    coursesPlatformRuntime.emptyEnrollmentRetryTimer = null;
    if (state.route !== "video-courses") {
      return;
    }
    loadStudentCoursesWithProgress({ force: true })
      .then(() => {
        if (state.route === "video-courses") {
          state.skipNextRouteAnimation = true;
          render();
        }
      })
      .catch(() => { });
  }, 1200);
}

function getCoursePlatformCourseTitle(course) {
  return String(course?.course_name || course?.title || "Course").trim() || "Course";
}

async function loadAdminNotificationVideoCourseOptions(options = {}) {
  if (state.adminNotificationVideoCoursesLoading && !options.force) {
    return false;
  }
  if ((state.adminNotificationVideoCourses || []).length && !options.force) {
    state.adminNotificationVideoCoursesLoadedAt = state.adminNotificationVideoCoursesLoadedAt || Date.now();
    return true;
  }
  if ((state.adminCoursesPlatformCourses || []).length && !options.force) {
    state.adminNotificationVideoCourses = [...state.adminCoursesPlatformCourses];
    state.adminNotificationVideoCoursesLoadedAt = Date.now();
    return true;
  }
  const client = getCoursesPlatformClient();
  if (!client) {
    state.adminNotificationVideoCoursesError = "No active Supabase admin session.";
    return false;
  }
  state.adminNotificationVideoCoursesLoading = true;
  state.adminNotificationVideoCoursesError = "";
  try {
    const courses = await runRelationalQueryWithTimeout(
      client
        .from("platform_courses")
        .select("id,course_name,academic_year,academic_semester,is_active,is_published")
        .order("academic_year", { ascending: true })
        .order("academic_semester", { ascending: true })
        .order("course_name", { ascending: true }),
      "Video Course options query timed out.",
    );
    state.adminNotificationVideoCourses = Array.isArray(courses) ? courses : [];
    state.adminNotificationVideoCoursesLoadedAt = Date.now();
    return true;
  } catch (error) {
    state.adminNotificationVideoCoursesError = getErrorMessage(error, "Could not load Video Course options.");
    return false;
  } finally {
    state.adminNotificationVideoCoursesLoading = false;
  }
}

function getCoursePlatformCoverUrl(course) {
  const entered = String(course?.cover_image_url || "").trim();
  const renderableUploadedCover = getRenderableQuestionImageUrl(entered);
  if (renderableUploadedCover && entered !== "Assets/branding/web-logo-hero.png") {
    return renderableUploadedCover;
  }
  if (entered.startsWith("Assets/") && entered !== "Assets/branding/web-logo-hero.png") {
    return entered;
  }
  return "";
}

function renderCourseCoverHtml(course, extraClass = "") {
  const title = getCoursePlatformCourseTitle(course);
  const coverUrl = getCoursePlatformCoverUrl(course);
  const hasCover = !!coverUrl;

  // Extract clean initials (ignore prefixes like "Anatomy of", "Intro to", etc.)
  let cleanTitle = title.replace(/^(anatomy\s+of|intro\s+to|introduction\s+to|principles\s+of|essentials\s+of|applied\s+)\s+/i, "");
  const words = cleanTitle.split(/\s+/).filter(w => w.trim().length > 0);
  let initials = "";
  if (words.length >= 2) {
    initials = (words[0][0] + words[1][0]).toUpperCase();
  } else if (words.length === 1 && words[0].length >= 2) {
    initials = words[0].slice(0, 2).toUpperCase();
  } else if (words.length === 1) {
    initials = words[0].slice(0, 1).toUpperCase();
  } else {
    initials = "CO";
  }

  // Hash title for stable gradient index
  let hash = 0;
  for (let i = 0; i < title.length; i++) {
    hash = title.charCodeAt(i) + ((hash << 5) - hash);
  }
  
  // Vibrant gradients
  const gradients = [
    { from: "#0f766e", to: "#0d9488" }, // Teal
    { from: "#1d4ed8", to: "#3b82f6" }, // Royal Blue
    { from: "#6d28d9", to: "#8b5cf6" }, // Violet/Purple
    { from: "#b45309", to: "#f59e0b" }, // Warm Amber
    { from: "#047857", to: "#10b981" }, // Emerald Green
    { from: "#be185d", to: "#ec4899" }, // Rose Pink
    { from: "#c2410c", to: "#f97316" }  // Burnt Orange
  ];
  const idx = Math.abs(hash) % gradients.length;
  const g = gradients[idx];

  const placeholderHtml = `
    <div class="course-cover-placeholder" style="background: linear-gradient(135deg, ${g.from}, ${g.to});">
      <div class="course-cover-pattern"></div>
      <span class="course-cover-initials">${escapeHtml(initials)}</span>
    </div>
  `;

  if (hasCover) {
    return `
      <div class="course-cover-container ${extraClass}">
        ${placeholderHtml}
        <img src="${escapeHtml(coverUrl)}" alt="${escapeHtml(title)}" loading="lazy" class="course-cover-image" onerror="this.style.display='none';" />
      </div>
    `;
  }

  return `
    <div class="course-cover-container ${extraClass}">
      ${placeholderHtml}
    </div>
  `;
}

function formatCourseDurationLabel(seconds, fallback = "") {
  const safeSeconds = Math.max(0, Number(seconds) || 0);
  if (!safeSeconds) {
    return String(fallback || "").trim();
  }
  const minutes = Math.ceil(safeSeconds / 60);
  if (minutes < 60) {
    return `${minutes} min`;
  }
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  return rest ? `${hours}h ${rest}m` : `${hours}h`;
}

function readVideoFileDurationSeconds(file, options = {}) {
  if (
    !(typeof File !== "undefined" && file instanceof File)
    || typeof document === "undefined"
    || typeof URL === "undefined"
    || typeof URL.createObjectURL !== "function"
  ) {
    return Promise.resolve(0);
  }
  return new Promise((resolve) => {
    const video = document.createElement("video");
    const timeoutMs = Math.max(1000, Number(options?.timeoutMs) || 10000);
    let objectUrl = "";
    let settled = false;
    const finish = (seconds) => {
      if (settled) return;
      settled = true;
      window.clearTimeout(timeoutId);
      video.removeAttribute("src");
      video.load();
      if (objectUrl) {
        URL.revokeObjectURL(objectUrl);
      }
      const safeSeconds = Math.max(0, Math.round(Number(seconds) || 0));
      resolve(Number.isFinite(safeSeconds) ? safeSeconds : 0);
    };
    const timeoutId = window.setTimeout(() => finish(0), timeoutMs);
    video.preload = "metadata";
    video.muted = true;
    video.onloadedmetadata = () => finish(video.duration);
    video.onerror = () => finish(0);
    try {
      objectUrl = URL.createObjectURL(file);
      video.src = objectUrl;
    } catch {
      finish(0);
    }
  });
}

function getCourseEnrollmentState(course, enrollments = state.coursesEnrollments, requests = state.coursesRequests) {
  const courseId = String(course?.id || course || "").trim();
  const isEnrolled = (Array.isArray(enrollments) ? enrollments : []).some((row) => String(row?.course_id || "").trim() === courseId);
  const request = (Array.isArray(requests) ? requests : []).find((row) => String(row?.course_id || "").trim() === courseId) || null;
  return {
    isEnrolled,
    request,
    requestStatus: String(request?.status || "").trim().toLowerCase(),
    mode: normalizeCoursePlatformMode(course?.enrollment_mode),
  };
}

function getCoursePlatformLessonsForCourse(courseId, lessons = state.coursesLessons) {
  const target = String(courseId || "").trim();
  return (Array.isArray(lessons) ? lessons : [])
    .filter((lesson) => String(lesson?.course_id || "").trim() === target)
    .sort((a, b) => (Number(a?.position) || 0) - (Number(b?.position) || 0));
}

function getCoursePlatformProgressPercent(courseId, lessons = state.coursesLessons, progressRows = state.coursesProgress) {
  const courseLessons = getCoursePlatformLessonsForCourse(courseId, lessons).filter((lesson) => lesson?.is_published !== false);
  if (!courseLessons.length) {
    return 0;
  }
  const completed = new Set(
    (Array.isArray(progressRows) ? progressRows : [])
      .filter((row) => String(row?.course_id || "").trim() === String(courseId || "").trim())
      .filter((row) => String(row?.status || "").trim() === "completed" || Number(row?.progress_percent) >= 100)
      .map((row) => String(row?.lesson_id || "").trim())
      .filter(Boolean),
  );
  return Math.round((completed.size / courseLessons.length) * 100);
}

function getLastOpenedCourseLesson(courseId, lessons = state.coursesLessons, progressRows = state.coursesProgress) {
  const lessonIds = new Set(getCoursePlatformLessonsForCourse(courseId, lessons).map((lesson) => String(lesson?.id || "").trim()));
  const latest = (Array.isArray(progressRows) ? progressRows : [])
    .filter((row) => lessonIds.has(String(row?.lesson_id || "").trim()))
    .sort((a, b) => parseSyncTimestampMs(b?.last_opened_at) - parseSyncTimestampMs(a?.last_opened_at))[0];
  if (!latest) {
    return null;
  }
  return getCoursePlatformLessonsForCourse(courseId, lessons).find((lesson) => String(lesson?.id || "").trim() === String(latest.lesson_id || "").trim()) || null;
}

function getCoursePlatformTopicById(topicId) {
  const target = String(topicId || "").trim();
  if (!target) return null;
  return [...(state.coursesTopics || []), ...(state.adminCoursesPlatformTopics || [])]
    .find((topic) => String(topic?.id || "").trim() === target) || null;
}

function buildCoursePlatformTopicLabel(topicId) {
  const topic = getCoursePlatformTopicById(topicId);
  return String(topic?.topic_name || "").trim();
}

function setCoursesPlatformError(error, fallback = "Courses could not be loaded.") {
  const message = getErrorMessage(error, fallback);
  state.coursesError = message;
  if (isMissingRelationError(error)) {
    state.coursesError = "Courses platform tables are not available yet. Run the latest Supabase migration first.";
  }
}

