async function adminDeleteModule(moduleId) {
  const client = getCoursesPlatformClient();
  if (!client || !isUuidValue(moduleId)) throw new Error("Module cannot be deleted.");
  await runRelationalQueryWithTimeout(client.from("platform_course_modules").delete().eq("id", moduleId), "Module delete timed out.");
  await loadAdminCoursesPlatform({ force: true });
  return true;
}

async function adminMoveModule(moduleId, direction) {
  const client = getCoursesPlatformClient();
  if (!client || !isUuidValue(moduleId)) throw new Error("Module cannot be moved.");
  const courseId = state.adminCourseBuilderCourseId;
  if (!isUuidValue(courseId)) throw new Error("No active course selected.");
  
  const rows = getAdminCourseBuilderCourseRows(courseId);
  const modules = rows.modules;
  const currentIndex = modules.findIndex((m) => String(m.id) === String(moduleId));
  if (currentIndex === -1) throw new Error("Module not found.");
  
  const targetIndex = direction === "up" ? currentIndex - 1 : currentIndex + 1;
  if (targetIndex < 0 || targetIndex >= modules.length) {
    return false;
  }
  
  const promises = [];
  modules.forEach((mod, idx) => {
    let newPos = idx;
    if (idx === currentIndex) {
      newPos = targetIndex;
    } else if (idx === targetIndex) {
      newPos = currentIndex;
    }
    if (Number(mod.position) !== newPos) {
      promises.push(
        client.from("platform_course_modules").update({
          position: newPos,
          updated_at: nowISO()
        }).eq("id", mod.id)
      );
    }
  });
  
  if (promises.length > 0) {
    await Promise.all(promises);
  }
  await loadAdminCoursesPlatform({ force: true });
  return true;
}

async function adminMoveLesson(lessonId, direction) {
  const client = getCoursesPlatformClient();
  if (!client || !isUuidValue(lessonId)) throw new Error("Lesson cannot be moved.");
  
  const lesson = (state.adminCoursesPlatformLessons || []).find((l) => String(l.id) === String(lessonId));
  if (!lesson) throw new Error("Lesson not found.");
  
  const moduleId = lesson.module_id;
  const courseId = state.adminCourseBuilderCourseId;
  if (!isUuidValue(courseId)) throw new Error("No active course selected.");
  
  const rows = getAdminCourseBuilderCourseRows(courseId);
  const lessons = rows.lessons.filter((l) => String(l.module_id) === String(moduleId));
  const currentIndex = lessons.findIndex((l) => String(l.id) === String(lessonId));
  if (currentIndex === -1) throw new Error("Lesson not found.");
  
  const targetIndex = direction === "up" ? currentIndex - 1 : currentIndex + 1;
  if (targetIndex < 0 || targetIndex >= lessons.length) {
    return false;
  }
  
  const promises = [];
  lessons.forEach((less, idx) => {
    let newPos = idx;
    if (idx === currentIndex) {
      newPos = targetIndex;
    } else if (idx === targetIndex) {
      newPos = currentIndex;
    }
    if (Number(less.position) !== newPos) {
      promises.push(
        client.from("platform_course_lessons").update({
          position: newPos,
          updated_at: nowISO()
        }).eq("id", less.id)
      );
    }
  });
  
  if (promises.length > 0) {
    await Promise.all(promises);
  }
  await loadAdminCoursesPlatform({ force: true });
  return true;
}

function getCourseVideoUploadFile(data) {
  const file = data?.video_file;
  if (typeof File !== "undefined" && file instanceof File && Number(file.size || 0) > 0) {
    return file;
  }
  return null;
}

async function resolveAdminLessonDurationSeconds(data, fallbackSeconds = 0) {
  const uploadFile = getCourseVideoUploadFile(data);
  if (uploadFile) {
    const detectedSeconds = await readVideoFileDurationSeconds(uploadFile);
    if (detectedSeconds > 0) {
      return detectedSeconds;
    }
  }
  return Math.max(0, Number(data?.duration_seconds ?? fallbackSeconds) || 0);
}

function getAdminCourseUploadProgress(draftKey) {
  const key = String(draftKey || "").trim();
  return key && state.adminCourseUploadProgress ? state.adminCourseUploadProgress[key] || null : null;
}

function setAdminCourseUploadProgress(draftKey, patch = {}) {
  const key = String(draftKey || "").trim();
  if (!key) return;
  if (!state.adminCourseUploadProgress) {
    state.adminCourseUploadProgress = {};
  }
  const previous = state.adminCourseUploadProgress[key] || {};
  const next = {
    status: "uploading",
    percent: 0,
    message: "Uploading video...",
    ...previous,
    ...patch,
  };
  next.percent = Math.max(0, Math.min(100, Math.round(Number(next.percent) || 0)));
  state.adminCourseUploadProgress[key] = next;
  updateAdminCourseUploadProgressElement(key, next);
}

function clearAdminCourseUploadProgress(draftKey) {
  const key = String(draftKey || "").trim();
  if (!key || !state.adminCourseUploadProgress) return;
  delete state.adminCourseUploadProgress[key];
  updateAdminCourseUploadProgressElement(key, { status: "idle", percent: 0, message: "" });
}

function updateAdminCourseUploadProgressElement(draftKey, progress = {}) {
  const key = String(draftKey || "").trim();
  if (!key || typeof document === "undefined") return;
  const progressEl = [...document.querySelectorAll("[data-upload-progress]")]
    .find((entry) => String(entry.getAttribute("data-upload-progress") || "") === key);
  if (!progressEl) return;
  const status = String(progress?.status || "").trim();
  const visible = status && status !== "idle";
  const percent = Math.max(0, Math.min(100, Math.round(Number(progress?.percent) || 0)));
  const message = String(progress?.message || "").trim()
    || (status === "done" ? "Upload complete" : status === "saving" ? "Saving lesson..." : "Uploading video...");
  progressEl.classList.toggle("is-visible", Boolean(visible));
  ["is-starting", "is-uploading", "is-saving", "is-done", "is-error"].forEach((className) => {
    progressEl.classList.remove(className);
  });
  if (/^[a-z-]+$/.test(status)) {
    progressEl.classList.add(`is-${status}`);
  }
  const labelEl = progressEl.querySelector(".course-upload-progress-label");
  const percentEl = progressEl.querySelector(".course-upload-progress-percent");
  const barEl = progressEl.querySelector(".course-upload-progress-track span");
  if (labelEl) labelEl.textContent = message;
  if (percentEl) percentEl.textContent = `${percent}%`;
  if (barEl) barEl.style.width = `${percent}%`;
  progressEl.setAttribute("aria-label", `${message} ${percent}%`);
}

function getAdminCourseStorageUploadSession(client) {
  if (!client?.auth?.getSession) {
    return Promise.resolve(null);
  }
  return runWithTimeoutResult(
    client.auth.getSession(),
    SUPABASE_SESSION_TIMEOUT_MS,
    "Supabase session lookup timed out.",
  ).then((result) => {
    if (result?.error) {
      throw result.error;
    }
    return result?.data?.session || null;
  });
}

function formatUploadSizeLabel(bytes) {
  const safeBytes = Math.max(0, Number(bytes) || 0);
  if (safeBytes >= 1024 * 1024 * 1024) {
    return `${(safeBytes / (1024 * 1024 * 1024)).toFixed(1)} GB`;
  }
  if (safeBytes >= 1024 * 1024) {
    return `${(safeBytes / (1024 * 1024)).toFixed(1)} MB`;
  }
  if (safeBytes >= 1024) {
    return `${(safeBytes / 1024).toFixed(1)} KB`;
  }
  return `${safeBytes} bytes`;
}

function isSupabaseStorageSizeLimitError(error) {
  const message = getErrorMessage(error, "").toLowerCase();
  const code = String(error?.code || error?.payload?.code || error?.payload?.error || "").trim().toLowerCase();
  return message.includes("exceeded the maximum allowed size")
    || message.includes("maximum allowed size")
    || code.includes("entitytoolarge")
    || code.includes("payload too large");
}

function getCourseVideoStorageSizeLimitMessage(bucket, file, maxVideoBytes) {
  const selectedSize = formatUploadSizeLabel(file?.size || 0);
  const configuredSize = formatUploadSizeLabel(maxVideoBytes);
  const freeSize = formatUploadSizeLabel(SUPABASE_FREE_STORAGE_UPLOAD_MAX_BYTES);
  return `Supabase rejected this ${selectedSize} video because the live Storage limit for "${bucket}" is lower than the selected file. Increase the Supabase Storage global file size limit and the "${bucket}" bucket limit to at least ${configuredSize}, or enable Cloudflare Stream for large lecture videos. Free Supabase projects are capped at ${freeSize}.`;
}

function getSupabaseStorageProjectId() {
  try {
    const url = new URL(normalizeApiBaseUrl(SUPABASE_CONFIG.url || ""));
    const match = url.hostname.match(/^([a-z0-9-]+)\.supabase\.co$/i);
    return String(match?.[1] || "").trim();
  } catch {
    return "";
  }
}

function getSupabaseStorageResumableEndpoint() {
  const projectId = getSupabaseStorageProjectId();
  if (projectId) {
    return `https://${projectId}.storage.supabase.co/storage/v1/upload/resumable`;
  }
  const baseUrl = normalizeApiBaseUrl(SUPABASE_CONFIG.url || "");
  return baseUrl ? `${baseUrl}/storage/v1/upload/resumable` : "";
}

function buildStableCourseVideoObjectPath(courseId, file, normalizedType) {
  const targetCourseId = String(courseId || "").trim();
  const currentUser = getCurrentUser();
  const userScope = sanitizeStoragePathSegment(currentUser?.supabaseAuthId || currentUser?.id || "admin", "admin");
  const extension = resolveVideoFileExtension(file.name, normalizedType);
  const baseName = sanitizeStoragePathSegment(
    String(file.name || "lesson-video").replace(/\.[a-z0-9]+$/i, ""),
    "lesson-video",
  );
  const sizePart = Math.max(0, Number(file.size || 0));
  const modifiedPart = Math.max(0, Number(file.lastModified || 0));
  return `courses/${targetCourseId}/${userScope}/resumable/${sizePart}-${modifiedPart}-${baseName}.${extension}`;
}

function splitSupabaseStorageObjectPath(filePath) {
  const normalized = String(filePath || "").trim().replace(/^\/+|\/+$/g, "");
  if (!normalized) {
    return { directory: "", name: "" };
  }
  const parts = normalized.split("/").filter(Boolean);
  const name = parts.pop() || "";
  return { directory: parts.join("/"), name };
}

async function findSupabaseStorageObject(client, bucket, filePath, options = {}) {
  const { directory, name } = splitSupabaseStorageObjectPath(filePath);
  if (!client?.storage || !bucket || !name) {
    return { exists: false, object: null, error: null };
  }
  const expectedSize = Math.max(0, Number(options?.expectedSize) || 0);
  const { data, error } = await runWithTimeoutResult(
    client.storage
      .from(bucket)
      .list(directory, {
        limit: 20,
        search: name,
        sortBy: { column: "updated_at", order: "desc" },
      }),
    Math.max(SUPABASE_QUERY_TIMEOUT_MS, 15000),
    "Video upload verification timed out.",
  );
  if (error) {
    return { exists: false, object: null, error };
  }
  const matched = (Array.isArray(data) ? data : []).find((entry) => String(entry?.name || "") === name) || null;
  if (!matched) {
    return { exists: false, object: null, error: null };
  }
  const actualSize = Math.max(0, Number(matched?.metadata?.size ?? matched?.metadata?.contentLength ?? matched?.size) || 0);
  const sizeMatches = !expectedSize || !actualSize || Math.abs(actualSize - expectedSize) <= 1;
  return { exists: sizeMatches, object: matched, error: null };
}

async function isCompletedSupabaseStorageObject(client, bucket, filePath, file) {
  const result = await findSupabaseStorageObject(client, bucket, filePath, {
    expectedSize: file?.size || 0,
  });
  if (result.error && !isMissingRelationError(result.error) && !isTimeoutResultError(result.error)) {
    console.warn("Could not verify course video upload.", result.error?.message || result.error);
  }
  return Boolean(result.exists);
}

async function uploadSupabaseStorageObjectResumable(bucket, filePath, file, options = {}) {
  const tusClient = await getTusClient();
  const endpoint = getSupabaseStorageResumableEndpoint();
  const token = String(options?.accessToken || "").trim();
  if (!tusClient?.Upload || !endpoint || !bucket || !filePath || !token) {
    throw new Error("Resumable video upload needs an active Supabase session.");
  }

  return new Promise((resolve, reject) => {
    let lastLoaded = 0;
    let lastPercent = 0;
    const emitProgress = (progress = {}) => {
      if (typeof options?.onProgress !== "function") return;
      const loaded = Math.max(lastLoaded, Number(progress.loaded) || 0);
      const total = Math.max(0, Number(progress.total) || Number(file?.size) || 0);
      const rawPercent = Number(progress.percent);
      const computedPercent = total > 0 && loaded > 0
        ? Math.round((loaded / total) * 100)
        : rawPercent;
      const percent = Math.max(lastPercent, Math.max(1, Math.min(99, Math.round(Number(computedPercent) || 1))));
      lastLoaded = loaded;
      lastPercent = percent;
      options.onProgress({
        ...progress,
        loaded,
        total,
        percent,
      });
    };
    const upload = new tusClient.Upload(file, {
      endpoint,
      chunkSize: SUPABASE_TUS_CHUNK_SIZE,
      retryDelays: SUPABASE_TUS_RETRY_DELAYS,
      uploadDataDuringCreation: true,
      removeFingerprintOnSuccess: true,
      headers: {
        authorization: `Bearer ${token}`,
        apikey: String(SUPABASE_CONFIG.anonKey || SUPABASE_CONFIG.legacyAnonKey || "").trim(),
        "x-upsert": options?.upsert ? "true" : "false",
      },
      metadata: {
        bucketName: bucket,
        objectName: filePath,
        contentType: String(options?.contentType || file.type || "video/mp4"),
        cacheControl: String(options?.cacheControl || "3600"),
      },
      onError(error) {
        reject(error);
      },
      onProgress(bytesUploaded, bytesTotal) {
        if (typeof options?.onProgress !== "function") return;
        const percent = bytesTotal > 0
          ? Math.max(1, Math.min(99, Math.round((bytesUploaded / bytesTotal) * 100)))
          : 1;
        emitProgress({ percent, loaded: bytesUploaded, total: bytesTotal });
      },
      onSuccess() {
        resolve({ data: { path: filePath }, error: null });
      },
    });

    upload.findPreviousUploads()
      .then((previousUploads) => {
        if (previousUploads.length) {
          if (typeof options?.onProgress === "function") {
            emitProgress({ percent: lastPercent || 1, loaded: lastLoaded, total: file.size, message: "Resuming video upload..." });
          }
          upload.resumeFromPreviousUpload(previousUploads[0]);
        }
        upload.start();
      })
      .catch(() => {
        upload.start();
      });
  });
}

function uploadSupabaseStorageObjectWithProgress(client, bucket, filePath, file, options = {}) {
  return new Promise((resolve, reject) => {
    if (typeof XMLHttpRequest === "undefined") {
      reject(new Error("This browser cannot report upload progress."));
      return;
    }

    const baseUrl = normalizeApiBaseUrl(SUPABASE_CONFIG.url || "");
    const token = String(options?.accessToken || "").trim();
    const anonKey = String(SUPABASE_CONFIG.anonKey || SUPABASE_CONFIG.legacyAnonKey || "").trim();
    const encodedPath = encodeSupabaseStorageObjectPath(filePath);
    if (!client?.storage || !baseUrl || !bucket || !encodedPath || !token || !anonKey) {
      reject(new Error("Video upload needs an active Supabase session."));
      return;
    }

    const xhr = new XMLHttpRequest();
    xhr.open("POST", `${baseUrl}/storage/v1/object/${encodeURIComponent(bucket)}/${encodedPath}`, true);
    xhr.timeout = 0;
    xhr.setRequestHeader("Authorization", `Bearer ${token}`);
    xhr.setRequestHeader("apikey", anonKey);
    xhr.setRequestHeader("x-upsert", options?.upsert ? "true" : "false");
    xhr.setRequestHeader("cache-control", String(options?.cacheControl || "3600"));
    if (options?.contentType) {
      xhr.setRequestHeader("content-type", String(options.contentType));
    }

    xhr.upload.onprogress = (event) => {
      if (!event.lengthComputable || typeof options?.onProgress !== "function") return;
      options.onProgress({
        loaded: event.loaded,
        total: event.total,
        percent: Math.max(1, Math.min(99, Math.round((event.loaded / event.total) * 100))),
      });
    };

    xhr.onload = () => {
      let responsePayload = null;
      try {
        responsePayload = xhr.responseText ? JSON.parse(xhr.responseText) : null;
      } catch {
        responsePayload = null;
      }
      if (xhr.status >= 200 && xhr.status < 300) {
        resolve({ data: responsePayload || { path: filePath }, error: null });
        return;
      }
      const message = String(responsePayload?.message || responsePayload?.error || xhr.statusText || "Could not upload course video.");
      const error = new Error(message);
      error.status = xhr.status;
      error.statusCode = xhr.status;
      error.payload = responsePayload;
      reject(error);
    };
    xhr.onerror = () => reject(new Error("Network error while uploading course video."));
    xhr.ontimeout = () => reject(new Error("Video upload timed out."));
    xhr.onabort = () => reject(new Error("Video upload was cancelled."));
    xhr.send(file);
  });
}

async function getTusClient() {
  if (window.tus?.Upload) {
    return window.tus;
  }
  if (cloudflareStreamRuntime.tusClientPromise) {
    return cloudflareStreamRuntime.tusClientPromise;
  }
  cloudflareStreamRuntime.tusClientPromise = loadExternalScriptWithFallback(TUS_CLIENT_SCRIPT_SOURCES, { timeoutMs: 20000 })
    .then(() => {
      if (!window.tus?.Upload) {
        throw new Error("Video uploader could not start.");
      }
      return window.tus;
    })
    .finally(() => {
      cloudflareStreamRuntime.tusClientPromise = null;
    });
  return cloudflareStreamRuntime.tusClientPromise;
}

function extractCloudflareStreamUidFromUploadUrl(uploadUrl) {
  const raw = String(uploadUrl || "").trim();
  if (!raw) return "";
  try {
    const parsed = new URL(raw);
    const segments = parsed.pathname.split("/").filter(Boolean);
    const candidate = segments[segments.length - 1] || parsed.hostname;
    return String(candidate || "").trim();
  } catch {
    const match = raw.match(/\/([a-zA-Z0-9_-]{16,})(?:$|\?)/);
    return String(match?.[1] || "").trim();
  }
}

async function uploadCourseLessonVideoToCloudflareStream(courseId, file, options = {}) {
  const client = getCoursesPlatformClient();
  if (!client?.auth || !SUPABASE_CONFIG.url || !SUPABASE_CONFIG.legacyAnonKey) {
    throw new Error("Cloudflare video upload needs an active Supabase session.");
  }
  const tokenResult = await getValidSupabaseAccessToken(client);
  if (!tokenResult.ok) {
    throw new Error(tokenResult.message || "Could not verify upload permission.");
  }
  const tusClient = await getTusClient();
  const uploadEndpoint = `${SUPABASE_CONFIG.url}/functions/v1/cloudflare-stream-tus-upload`;
  const maxDurationSeconds = Math.max(60, Math.min(36000, Number(options?.maxDurationSeconds) || CLOUDFLARE_STREAM_MAX_DURATION_SECONDS));
  const expiry = new Date(Date.now() + 6 * 60 * 60 * 1000).toISOString();
  const targetCourseId = String(courseId || "").trim();

  if (typeof options?.onProgress === "function") {
    options.onProgress({ percent: 1, loaded: 0, total: file.size });
  }

  return new Promise((resolve, reject) => {
    const upload = new tusClient.Upload(file, {
      endpoint: uploadEndpoint,
      chunkSize: CLOUDFLARE_STREAM_TUS_CHUNK_SIZE,
      retryDelays: [0, 3000, 5000, 10000, 20000],
      removeFingerprintOnSuccess: true,
      headers: {
        Authorization: `Bearer ${tokenResult.token}`,
        apikey: SUPABASE_CONFIG.legacyAnonKey,
      },
      metadata: {
        name: String(file.name || "course-video"),
        filetype: String(file.type || "video/mp4"),
        maxDurationSeconds: String(maxDurationSeconds),
        expiry,
        requiresignedurls: "true",
        courseId: targetCourseId,
      },
      onError(error) {
        reject(new Error(getErrorMessage(error, "Cloudflare video upload failed.")));
      },
      onProgress(bytesUploaded, bytesTotal) {
        if (typeof options?.onProgress !== "function") return;
        const percent = bytesTotal > 0
          ? Math.max(1, Math.min(99, Math.round((bytesUploaded / bytesTotal) * 100)))
          : 1;
        options.onProgress({ percent, loaded: bytesUploaded, total: bytesTotal });
      },
      onSuccess() {
        const videoUid = extractCloudflareStreamUidFromUploadUrl(upload.url);
        if (!videoUid) {
          reject(new Error("Cloudflare upload finished, but the video ID was not returned."));
          return;
        }
        if (typeof options?.onProgress === "function") {
          options.onProgress({ percent: 100, loaded: file.size, total: file.size });
        }
        resolve(`cloudflare-stream://${videoUid}`);
      },
    });

    upload.findPreviousUploads()
      .then((previousUploads) => {
        if (previousUploads.length) {
          upload.resumeFromPreviousUpload(previousUploads[0]);
        }
        upload.start();
      })
      .catch(() => {
        upload.start();
      });
  });
}

async function uploadCourseLessonVideo(courseId, file, options = {}) {
  const client = getCoursesPlatformClient();
  const bucket = String(SUPABASE_CONFIG.courseVideoBucket || "").trim();
  const targetCourseId = String(courseId || "").trim();
  if (!client?.storage || !isUuidValue(targetCourseId)) {
    throw new Error("Video upload needs an active Supabase session.");
  }
  if (!bucket) {
    throw new Error("Course video bucket is not configured.");
  }
  if (!(file instanceof File) || Number(file.size || 0) <= 0) {
    return "";
  }
  const maxVideoBytes = SUPABASE_CONFIG.cloudflareStreamEnabled ? CLOUDFLARE_STREAM_UPLOAD_MAX_BYTES : COURSE_VIDEO_UPLOAD_MAX_BYTES;
  if (file.size > maxVideoBytes) {
    throw new Error(SUPABASE_CONFIG.cloudflareStreamEnabled
      ? "Video is too large. Cloudflare Stream accepts files up to 30 GB."
      : "Video is too large. Maximum upload size is 500 MB.");
  }
  const normalizedType = String(file.type || "").trim().toLowerCase();
  if (normalizedType && !COURSE_VIDEO_ALLOWED_MIME_TYPES.has(normalizedType)) {
    throw new Error("Unsupported video type. Use MP4, WebM, OGG, MOV, or M4V.");
  }
  if (SUPABASE_CONFIG.cloudflareStreamEnabled) {
    return uploadCourseLessonVideoToCloudflareStream(targetCourseId, file, options);
  }
  const filePath = buildStableCourseVideoObjectPath(targetCourseId, file, normalizedType);
  if (typeof options?.onProgress === "function") {
    options.onProgress({ percent: 1, loaded: 0, total: file.size });
  }
  const session = await getAdminCourseStorageUploadSession(client);
  const accessToken = String(session?.access_token || "").trim();
  if (accessToken && await isCompletedSupabaseStorageObject(client, bucket, filePath, file)) {
    if (typeof options?.onProgress === "function") {
      options.onProgress({
        percent: 100,
        loaded: file.size,
        total: file.size,
        message: "Video already uploaded. Saving lesson...",
      });
    }
    return `supabase-storage://${bucket}/${filePath}`;
  }
  const uploadResult = accessToken
    ? await uploadSupabaseStorageObjectResumable(bucket, filePath, file, {
        accessToken,
        cacheControl: "3600",
        upsert: true,
        contentType: normalizedType || undefined,
        onProgress: options?.onProgress,
      }).catch(async (resumableError) => {
        if (await isCompletedSupabaseStorageObject(client, bucket, filePath, file)) {
          return { data: { path: filePath, verifiedAfterError: true }, error: null };
        }
        console.warn("Resumable course video upload failed.", resumableError?.message || resumableError);
        return { data: null, error: resumableError };
      })
    : await client.storage
      .from(bucket)
      .upload(filePath, file, {
        cacheControl: "3600",
        upsert: true,
        contentType: normalizedType || undefined,
      });
  if (typeof options?.onProgress === "function" && !uploadResult?.error) {
    options.onProgress({ percent: 100, loaded: file.size, total: file.size });
  }
  const uploadError = uploadResult?.error || null;
  if (uploadError) {
    const bucketMissing = isStorageBucketMissingError(uploadError);
    const sizeLimitExceeded = isSupabaseStorageSizeLimitError(uploadError);
    throw new Error(
      bucketMissing
        ? `Storage bucket "${bucket}" was not found. Run the latest Supabase migration, then retry.`
        : sizeLimitExceeded
          ? getCourseVideoStorageSizeLimitMessage(bucket, file, maxVideoBytes)
        : getErrorMessage(uploadError, "Could not upload course video."),
    );
  }
  return `supabase-storage://${bucket}/${filePath}`;
}

async function resolveAdminLessonVideoUrl(courseId, data) {
  const uploadFile = getCourseVideoUploadFile(data);
  if (uploadFile) {
    return uploadCourseLessonVideo(courseId, uploadFile, {
      onProgress: typeof data?._uploadProgress === "function" ? data._uploadProgress : null,
    });
  }
  return String(data.video_url || "").trim() || null;
}

async function adminCreateLesson(courseId, moduleId, data) {
  const client = getCoursesPlatformClient();
  if (!client || !isUuidValue(courseId) || !isUuidValue(moduleId)) throw new Error("Lesson cannot be created.");
  const durationSeconds = await resolveAdminLessonDurationSeconds(data, 0);
  const videoUrl = await resolveAdminLessonVideoUrl(courseId, data);
  await runRelationalQueryWithTimeout(
    client.from("platform_course_lessons").insert({
      course_id: courseId,
      module_id: moduleId,
      title: String(data.title || "").trim(),
      description: String(data.description || "").trim() || null,
      lesson_type: String(data.lesson_type || "video").trim() || "video",
      video_url: videoUrl,
      video_provider: String(data.video_provider || "").trim() || null,
      duration_seconds: durationSeconds,
      content_html: String(data.content_html || "").trim() || null,
      position: Number(data.position) || 0,
      is_free_preview: Boolean(data.is_free_preview),
      is_published: Boolean(data.is_published),
    }),
    "Lesson create timed out.",
  );
  await loadAdminCoursesPlatform({ force: true });
  return true;
}

async function adminUpdateLesson(lessonId, data) {
  const client = getCoursesPlatformClient();
  if (!client || !isUuidValue(lessonId)) throw new Error("Lesson cannot be updated.");
  const lesson = (state.adminCoursesPlatformLessons || []).find((entry) => String(entry?.id || "").trim() === String(lessonId || "").trim());
  const durationSeconds = await resolveAdminLessonDurationSeconds(data, lesson?.duration_seconds || 0);
  const videoUrl = await resolveAdminLessonVideoUrl(lesson?.course_id || state.adminCourseBuilderCourseId, data);
  await runRelationalQueryWithTimeout(
    client.from("platform_course_lessons").update({
      title: String(data.title || "").trim(),
      description: String(data.description || "").trim() || null,
      lesson_type: String(data.lesson_type || "video").trim() || "video",
      video_url: videoUrl,
      video_provider: String(data.video_provider || "").trim() || null,
      duration_seconds: durationSeconds,
      content_html: String(data.content_html || "").trim() || null,
      position: Number(data.position) || 0,
      is_free_preview: Boolean(data.is_free_preview),
      is_published: Boolean(data.is_published),
      updated_at: nowISO(),
    }).eq("id", lessonId),
    "Lesson update timed out.",
  );
  await loadAdminCoursesPlatform({ force: true });
  return true;
}

async function adminDeleteLesson(lessonId) {
  const client = getCoursesPlatformClient();
  if (!client || !isUuidValue(lessonId)) throw new Error("Lesson cannot be deleted.");
  await runRelationalQueryWithTimeout(client.from("platform_course_lessons").delete().eq("id", lessonId), "Lesson delete timed out.");
  await loadAdminCoursesPlatform({ force: true });
  return true;
}

function getCourseMaterialUploadFile(data) {
  const file = data?.material_file;
  if (typeof File !== "undefined" && file instanceof File && Number(file.size || 0) > 0) {
    return file;
  }
  return null;
}

async function uploadCourseLessonMaterial(lesson, file) {
  const client = getCoursesPlatformClient();
  const bucket = String(SUPABASE_CONFIG.courseMaterialBucket || "").trim();
  const courseId = String(lesson?.course_id || "").trim();
  const lessonId = String(lesson?.id || "").trim();
  if (!client?.storage || !isUuidValue(courseId) || !isUuidValue(lessonId)) {
    throw new Error("Material upload needs an active Supabase session.");
  }
  if (!bucket) {
    throw new Error("Course material bucket is not configured.");
  }
  if (!(file instanceof File) || Number(file.size || 0) <= 0) {
    return "";
  }
  if (file.size > COURSE_MATERIAL_UPLOAD_MAX_BYTES) {
    throw new Error("Material is too large. Maximum upload size is 100 MB.");
  }
  const normalizedType = String(file.type || "").trim().toLowerCase();
  if (normalizedType && !COURSE_MATERIAL_ALLOWED_MIME_TYPES.has(normalizedType)) {
    throw new Error("Unsupported material type. Use PDF, Office files, text/CSV, images, or ZIP.");
  }
  const currentUser = getCurrentUser();
  const userScope = sanitizeStoragePathSegment(currentUser?.supabaseAuthId || currentUser?.id || "admin", "admin");
  const extension = resolveMaterialFileExtension(file.name, normalizedType);
  const fileId = sanitizeStoragePathSegment(makeId("lesson-material"), "lesson-material");
  const filePath = `courses/${courseId}/lessons/${lessonId}/${userScope}/${Date.now()}-${fileId}.${extension}`;
  const uploadResult = await runWithTimeoutResult(
    client.storage
      .from(bucket)
      .upload(filePath, file, {
        cacheControl: "3600",
        upsert: false,
        contentType: normalizedType || undefined,
      }),
    Math.max(SUPABASE_QUERY_TIMEOUT_MS, 60000),
    "Material upload timed out.",
  );
  const uploadError = uploadResult?.error || null;
  if (uploadError) {
    const bucketMissing = isStorageBucketMissingError(uploadError);
    throw new Error(
      bucketMissing
        ? `Storage bucket "${bucket}" was not found. Run the latest Supabase migration, then retry.`
        : getErrorMessage(uploadError, "Could not upload lesson material."),
    );
  }
  return `supabase-storage://${bucket}/${filePath}`;
}

async function adminCreateResource(lessonId, data) {
  const client = getCoursesPlatformClient();
  const lesson = (state.adminCoursesPlatformLessons || []).find((entry) => String(entry?.id || "").trim() === String(lessonId || "").trim());
  if (!client || !lesson) throw new Error("Resource cannot be created.");
  const uploadFile = getCourseMaterialUploadFile(data);
  const uploadedMaterialUrl = uploadFile ? await uploadCourseLessonMaterial(lesson, uploadFile) : "";
  await runRelationalQueryWithTimeout(
    client.from("platform_course_resources").insert({
      course_id: lesson.course_id,
      module_id: lesson.module_id,
      lesson_id: lesson.id,
      title: String(data.title || "").trim() || String(uploadFile?.name || "").trim() || "Lesson material",
      resource_type: String(data.resource_type || (uploadFile ? "material" : "file")).trim() || "file",
      file_url: uploadedMaterialUrl || String(data.file_url || "").trim() || null,
      external_url: String(data.external_url || "").trim() || null,
      description: String(data.description || "").trim() || null,
      position: Number(data.position) || 0,
      is_published: Boolean(data.is_published ?? true),
    }),
    "Resource create timed out.",
  );
  await loadAdminCoursesPlatform({ force: true });
  return true;
}

