function formatDateTimeLocalValue(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return "";
  const pad = (entry) => String(entry).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

function adminRenderSuggestionSettings(courseId) {
  const suggestions = adminLoadCourseSuggestions(courseId);
  const activeSuggestion = suggestions[0] || null;
  const activeSuggestionFeatured = Boolean(activeSuggestion?.is_active)
    && !normalizeAcademicYearOrNull(activeSuggestion?.target_academic_year)
    && !normalizeAcademicSemesterOrNull(activeSuggestion?.target_semester)
    && Number(activeSuggestion?.priority || 0) >= 1000;
  return `
    <form id="admin-course-suggestion-form" class="course-builder-form">
      <h4>Suggestion Settings</h4>
      <input type="hidden" name="suggestion_id" value="${escapeHtml(activeSuggestion?.id || "")}" />
      <label class="course-builder-check"><input type="checkbox" name="show_as_suggested" ${activeSuggestion ? "checked" : ""} /> Show as suggested course</label>
      <label class="course-builder-check"><input type="checkbox" name="featured_for_all" ${activeSuggestionFeatured ? "checked" : ""} /> Featured for all students</label>
      <div class="course-builder-grid">
        <label>Target academic year
          <select name="target_academic_year">
            <option value="" ${activeSuggestion?.target_academic_year ? "" : "selected"}>All years</option>
            ${[1, 2, 3, 4, 5].map((year) => `<option value="${year}" ${Number(activeSuggestion?.target_academic_year) === year ? "selected" : ""}>Year ${year}</option>`).join("")}
          </select>
        </label>
        <label>Target semester
          <select name="target_semester">
            <option value="" ${activeSuggestion?.target_semester ? "" : "selected"}>All semesters</option>
            <option value="1" ${Number(activeSuggestion?.target_semester) === 1 ? "selected" : ""}>Semester 1</option>
            <option value="2" ${Number(activeSuggestion?.target_semester) === 2 ? "selected" : ""}>Semester 2</option>
          </select>
        </label>
        <label>Suggested title<input name="title" value="${escapeHtml(activeSuggestion?.title || "")}" /></label>
        <label>Priority<input name="priority" type="number" value="${escapeHtml(activeSuggestion?.priority || 0)}" /></label>
        <label>Starts at<input name="starts_at" type="datetime-local" value="${escapeHtml(formatDateTimeLocalValue(activeSuggestion?.starts_at))}" /></label>
        <label>Ends at<input name="ends_at" type="datetime-local" value="${escapeHtml(formatDateTimeLocalValue(activeSuggestion?.ends_at))}" /></label>
        <label class="course-builder-check"><input type="checkbox" name="is_active" ${activeSuggestion?.is_active !== false ? "checked" : ""} /> Active</label>
        <label class="course-builder-wide">Suggested reason<textarea name="reason" rows="3">${escapeHtml(activeSuggestion?.reason || "")}</textarea></label>
      </div>
      <div class="stack">
        <button class="btn admin-btn-sm" type="submit">Save suggestion</button>
        ${activeSuggestion ? `<button class="btn danger admin-btn-sm" type="button" data-action="admin-delete-course-suggestion" data-suggestion-id="${escapeHtml(activeSuggestion.id)}">Delete suggestion</button>` : ""}
      </div>
      <div class="course-builder-list">
        <h5>Active suggestions for this course</h5>
        ${suggestions.length ? suggestions.map((suggestion) => `
          <div class="course-request-row">
            <span>
              <b>${escapeHtml(suggestion.title || "Suggested course")}</b>
              <small>${escapeHtml(suggestion.is_active ? "Active" : "Inactive")} • ${Number(suggestion.priority || 0) >= 1000 && !suggestion.target_academic_year && !suggestion.target_semester ? "Featured for all students" : `${suggestion.target_academic_year ? `Year ${escapeHtml(suggestion.target_academic_year)}` : "All years"} • ${suggestion.target_semester ? `Semester ${escapeHtml(suggestion.target_semester)}` : "All semesters"}`} • Priority ${escapeHtml(suggestion.priority || 0)}</small>
            </span>
            <button class="btn danger admin-btn-sm" type="button" data-action="admin-delete-course-suggestion" data-suggestion-id="${escapeHtml(suggestion.id)}">Delete</button>
          </div>
        `).join("") : `<p class="subtle">No suggestions configured for this course.</p>`}
      </div>
    </form>
  `;
}

function getAdminCoursesPlatformAggregates() {
  const courses = state.adminCoursesPlatformCourses || [];
  const enrollments = state.adminCoursesPlatformEnrollments || [];
  const requests = state.adminCoursesPlatformRequests || [];
  return {
    totalCourses: courses.length,
    publishedCourses: courses.filter((course) => course.is_published).length,
    totalEnrollments: enrollments.length,
    totalPendingRequests: requests.filter((request) => String(request?.status || "").trim() === "pending").length,
  };
}

function getAdminCourseTableRowStats(courseId) {
  const rows = getAdminCourseBuilderCourseRows(courseId);
  const pendingRequests = (state.adminCoursesPlatformRequests || []).filter(
    (request) => String(request?.course_id || "").trim() === String(courseId || "").trim()
      && String(request?.status || "").trim() === "pending",
  ).length;
  return {
    modules: rows.modules.length,
    lessons: rows.lessons.length,
    enrollments: rows.enrollments.length,
    pendingRequests,
  };
}

function filterAdminCoursesForTable(courses) {
  const search = String(state.adminCourseTableSearch || "").trim().toLowerCase();
  const yearFilter = String(state.adminCourseTableFilterYear || "").trim();
  const semesterFilter = String(state.adminCourseTableFilterSemester || "").trim();
  const statusFilter = String(state.adminCourseTableFilterStatus || "all").trim().toLowerCase();
  return (courses || []).filter((course) => {
    if (yearFilter && Number(course.academic_year) !== Number(yearFilter)) return false;
    if (semesterFilter && Number(course.academic_semester) !== Number(semesterFilter)) return false;
    if (statusFilter === "published" && !course.is_published) return false;
    if (statusFilter === "draft" && course.is_published) return false;
    if (!search) return true;
    const haystack = [
      getCoursePlatformCourseTitle(course),
      course.course_code,
      course.instructor_name,
    ].map((value) => String(value || "").toLowerCase()).join(" ");
    return haystack.includes(search);
  });
}

function renderAdminCourseStatsCards(aggregates) {
  const stats = aggregates || getAdminCoursesPlatformAggregates();
  return `
    <div class="admin-course-table-stats">
      <div class="admin-course-stat-card"><span class="admin-course-stat-label">Total courses</span><b>${stats.totalCourses}</b></div>
      <div class="admin-course-stat-card"><span class="admin-course-stat-label">Published</span><b>${stats.publishedCourses}</b></div>
      <div class="admin-course-stat-card"><span class="admin-course-stat-label">Total enrollments</span><b>${stats.totalEnrollments}</b></div>
      <div class="admin-course-stat-card"><span class="admin-course-stat-label">Pending requests</span><b>${stats.totalPendingRequests}</b></div>
    </div>
  `;
}

function renderAdminCourseTableToolbar() {
  const yearFilter = String(state.adminCourseTableFilterYear || "");
  const semesterFilter = String(state.adminCourseTableFilterSemester || "");
  const statusFilter = String(state.adminCourseTableFilterStatus || "all");
  return `
    <div class="admin-course-table-toolbar">
      <input class="admin-course-search-input" type="search" id="admin-course-table-search" placeholder="Search courses, codes, instructors..." value="${escapeHtml(state.adminCourseTableSearch || "")}" />
      <div class="admin-course-filter-row">
        <label>Year
          <select id="admin-course-table-filter-year" data-action="admin-course-table-filter">
            <option value="" ${!yearFilter ? "selected" : ""}>All years</option>
            ${[1, 2, 3, 4, 5].map((year) => `<option value="${year}" ${yearFilter === String(year) ? "selected" : ""}>Year ${year}</option>`).join("")}
          </select>
        </label>
        <label>Semester
          <select id="admin-course-table-filter-semester" data-action="admin-course-table-filter">
            <option value="" ${!semesterFilter ? "selected" : ""}>All semesters</option>
            <option value="1" ${semesterFilter === "1" ? "selected" : ""}>Semester 1</option>
            <option value="2" ${semesterFilter === "2" ? "selected" : ""}>Semester 2</option>
          </select>
        </label>
        <label>Status
          <select id="admin-course-table-filter-status" data-action="admin-course-table-filter">
            <option value="all" ${statusFilter === "all" ? "selected" : ""}>All</option>
            <option value="published" ${statusFilter === "published" ? "selected" : ""}>Published</option>
            <option value="draft" ${statusFilter === "draft" ? "selected" : ""}>Draft</option>
          </select>
        </label>
      </div>
    </div>
  `;
}

function renderAdminCourseTable(courses, selectedCourseId, options = {}) {
  const filteredCourses = filterAdminCoursesForTable(courses);
  const showToolbar = options.showToolbar !== false;
  const compact = Boolean(options.compact);
  const aggregates = getAdminCoursesPlatformAggregates();
  return `
    ${options.showStats ? renderAdminCourseStatsCards(aggregates) : ""}
    <div class="admin-course-table-wrap ${compact ? "is-compact" : ""}">
      ${showToolbar ? renderAdminCourseTableToolbar() : ""}
      <div class="admin-course-table-scroll">
        <table class="admin-course-table">
          <thead>
            <tr>
              <th>Course</th>
              <th>Year / Sem</th>
              <th>Status</th>
              <th>Enrollment</th>
              <th>Modules</th>
              <th>Lessons</th>
              <th>Enrolled</th>
              <th>Pending</th>
            </tr>
          </thead>
          <tbody>
            ${filteredCourses.length ? filteredCourses.map((course) => {
              const courseId = String(course.id || "").trim();
              const stats = getAdminCourseTableRowStats(courseId);
              const isActive = courseId === String(selectedCourseId || "").trim();
              return `
                <tr class="${isActive ? "is-active" : ""}" data-action="admin-select-course-platform-course" data-course-id="${escapeHtml(courseId)}" role="button" tabindex="0">
                  <td>
                    <b>${escapeHtml(getCoursePlatformCourseTitle(course))}</b>
                    ${course.course_code ? `<small>${escapeHtml(course.course_code)}</small>` : ""}
                  </td>
                  <td>Y${escapeHtml(course.academic_year || "")} S${escapeHtml(course.academic_semester || "")}</td>
                  <td><span class="${course.is_published ? "admin-badge-published" : "admin-badge-draft"}">${course.is_published ? "Published" : "Draft"}</span></td>
                  <td>${escapeHtml(normalizeCoursePlatformMode(course.enrollment_mode) === "assigned" ? "Assigned" : "Request")}</td>
                  <td>${stats.modules}</td>
                  <td>${stats.lessons}</td>
                  <td>${stats.enrollments}</td>
                  <td>${stats.pendingRequests || "-"}</td>
                </tr>
              `;
            }).join("") : `<tr><td colspan="8" class="subtle">No courses match your filters.</td></tr>`}
          </tbody>
        </table>
      </div>
      <p class="subtle admin-course-table-foot">${escapeHtml(filteredCourses.length)} of ${escapeHtml(courses.length)} course${courses.length === 1 ? "" : "s"} shown</p>
    </div>
  `;
}

function renderAdminCourseSelector(courses, selectedCourseId, rows, pendingRequestCount) {
  const profileCount = rows.enrollments.length;
  const pills = `
    <div class="admin-course-selector-pills">
      <span class="admin-course-meta-pill"><b>${rows.modules.length}</b><small>Modules</small></span>
      <span class="admin-course-meta-pill"><b>${rows.lessons.length}</b><small>Lessons</small></span>
      <span class="admin-course-meta-pill"><b>${profileCount}</b><small>Enrollments</small></span>
      <span class="admin-course-meta-pill"><b>${pendingRequestCount}</b><small>Pending requests</small></span>
    </div>
  `;
  if (courses.length <= 3) {
    return `
      <div class="courses-builder-selector">
        <label>Selected Course
          <select id="admin-course-builder-course-select">
            ${courses.map((course) => `<option value="${escapeHtml(course.id)}" ${course.id === selectedCourseId ? "selected" : ""}>${escapeHtml(getCoursePlatformCourseTitle(course))} • Y${escapeHtml(course.academic_year)} S${escapeHtml(course.academic_semester)}</option>`).join("")}
          </select>
        </label>
        ${pills}
      </div>
    `;
  }
  return `
    <div class="admin-course-selector-table">
      ${renderAdminCourseTable(courses, selectedCourseId, { compact: true })}
      ${pills}
    </div>
  `;
}

function renderAdminGlobalSuggestions() {
  const courses = state.adminCoursesPlatformCourses || [];
  const suggestions = [...(state.adminCoursesPlatformSuggestions || [])].sort((left, right) => {
    const courseCompare = getAdminCourseBuilderCourseLabel(left?.course_id).localeCompare(getAdminCourseBuilderCourseLabel(right?.course_id));
    if (courseCompare) return courseCompare;
    return (Number(right?.priority) || 0) - (Number(left?.priority) || 0);
  });
  return `
    <div class="course-builder-form">
      <h4>All course suggestions</h4>
      <p class="subtle">Suggestions across every platform course. Select a course below to edit its settings.</p>
      <div class="course-builder-list">
        ${suggestions.length ? suggestions.map((suggestion) => {
          const course = courses.find((entry) => String(entry?.id || "") === String(suggestion?.course_id || ""));
          const statusLabel = suggestion.is_active ? "Active" : "Inactive";
          const featured = Number(suggestion.priority || 0) >= 1000 && !suggestion.target_academic_year && !suggestion.target_semester;
          return `
            <div class="course-request-row">
              <span>
                <b>${escapeHtml(suggestion.title || getCoursePlatformCourseTitle(course) || "Suggested course")}</b>
                <small>${escapeHtml(getAdminCourseBuilderCourseLabel(suggestion.course_id))}</small>
                <small>${escapeHtml(statusLabel)}${featured ? " • Featured for all" : ""} • Priority ${escapeHtml(suggestion.priority || 0)}</small>
              </span>
              <span class="${suggestion.is_active ? "admin-badge-published" : "admin-badge-draft"}">${escapeHtml(statusLabel)}</span>
            </div>
          `;
        }).join("") : `<p class="subtle">No suggestions configured yet.</p>`}
      </div>
    </div>
  `;
}

function renderAdminAnnouncementsSection(courses, selectedCourseId, rows) {
  const filterCourseId = String(state.adminAnnouncementCourseFilter || "all").trim();
  const allAnnouncements = [...(state.adminCoursesPlatformAnnouncements || [])].sort(
    (left, right) => parseSyncTimestampMs(right?.created_at) - parseSyncTimestampMs(left?.created_at),
  );
  const filteredAnnouncements = filterCourseId === "all"
    ? allAnnouncements
    : allAnnouncements.filter((item) => String(item?.course_id || "").trim() === filterCourseId);
  const dk = `admin-course-announcement-form_${selectedCourseId}`;
  return `
    <form id="admin-course-announcement-form" class="course-builder-form">
      <h4>Announcements</h4>
      <p class="subtle">Post to the selected course. Browse announcements from all courses below.</p>
      <label>Title<input name="title" value="${escapeHtml(getAdminCourseBuilderFieldValue(dk, "title", ""))}" required /></label>
      <label>Body<textarea name="body" rows="3" required>${escapeHtml(getAdminCourseBuilderFieldValue(dk, "body", ""))}</textarea></label>
      <label class="course-builder-check"><input type="checkbox" name="is_published" ${getAdminCourseBuilderCheckboxState(dk, "is_published", true)} /> Published</label>
      <button class="btn admin-btn-sm" type="submit">Post announcement</button>
    </form>
    <div class="course-builder-form" style="margin-top: 1rem;">
      <div class="admin-course-filter-row">
        <label>Filter by course
          <select id="admin-announcement-course-filter">
            <option value="all" ${filterCourseId === "all" ? "selected" : ""}>All courses</option>
            ${courses.map((course) => `<option value="${escapeHtml(course.id)}" ${filterCourseId === String(course.id || "") ? "selected" : ""}>${escapeHtml(getCoursePlatformCourseTitle(course))}</option>`).join("")}
          </select>
        </label>
      </div>
      <div class="course-builder-list admin-announcement-feed">
        ${filteredAnnouncements.length ? filteredAnnouncements.map((item) => `
          <div class="admin-announcement-card">
            <div>
              <b>${escapeHtml(item.title)}</b>
              <small class="admin-announcement-course">${escapeHtml(getAdminCourseBuilderCourseLabel(item.course_id))}</small>
              <p class="subtle">${escapeHtml(item.body || "")}</p>
              <small class="admin-announcement-date">${escapeHtml(formatReportDateTime(item.created_at || ""))}</small>
            </div>
            <div class="stack">
              <span class="${item.is_published ? "admin-badge-published" : "admin-badge-draft"}">${item.is_published ? "Published" : "Draft"}</span>
              <button class="btn danger admin-btn-sm" type="button" data-action="admin-delete-announcement" data-announcement-id="${escapeHtml(item.id)}">Delete</button>
            </div>
          </div>
        `).join("") : `<p class="subtle">No announcements yet.</p>`}
      </div>
    </div>
  `;
}

function renderAdminRequestsSection(courses) {
  const statusFilter = String(state.adminRequestFilterStatus || "all").trim().toLowerCase();
  const allRequests = [...(state.adminCoursesPlatformRequests || [])].sort(
    (left, right) => parseSyncTimestampMs(right?.created_at) - parseSyncTimestampMs(left?.created_at),
  );
  const filteredRequests = statusFilter === "all"
    ? allRequests
    : allRequests.filter((request) => String(request?.status || "").trim() === statusFilter);
  const globalPendingCount = allRequests.filter((request) => String(request?.status || "").trim() === "pending").length;
  const requestsByCourse = new Map();
  filteredRequests.forEach((request) => {
    const courseId = String(request?.course_id || "").trim() || "unknown";
    if (!requestsByCourse.has(courseId)) requestsByCourse.set(courseId, []);
    requestsByCourse.get(courseId).push(request);
  });
  const courseGroups = [...requestsByCourse.entries()].sort((left, right) => {
    const leftPending = left[1].filter((request) => String(request?.status || "").trim() === "pending").length;
    const rightPending = right[1].filter((request) => String(request?.status || "").trim() === "pending").length;
    if (leftPending !== rightPending) return rightPending - leftPending;
    return getAdminCourseBuilderCourseLabel(left[0]).localeCompare(getAdminCourseBuilderCourseLabel(right[0]));
  });
  const filterTabs = [
    ["all", "All"],
    ["pending", "Pending"],
    ["approved", "Approved"],
    ["rejected", "Rejected"],
  ];
  return `
    <div class="course-builder-form">
      <div class="admin-requests-head">
        <h4>Enrollment requests</h4>
        ${globalPendingCount ? `<button class="btn admin-btn-sm" type="button" data-action="admin-approve-all-pending-global" ${state.adminApproveAllPendingRunning ? "disabled" : ""}>${state.adminApproveAllPendingRunning ? "Approving..." : `Approve all pending (${globalPendingCount})`}</button>` : ""}
      </div>
      <div class="admin-request-filter-tabs">
        ${filterTabs.map(([value, label]) => `
          <button class="btn ghost admin-btn-sm ${statusFilter === value ? "is-active" : ""}" type="button" data-action="admin-request-filter" data-status="${escapeHtml(value)}">${escapeHtml(label)}</button>
        `).join("")}
      </div>
      ${courseGroups.length ? courseGroups.map(([courseId, courseRequests]) => {
        const pendingCount = courseRequests.filter((request) => String(request?.status || "").trim() === "pending").length;
        const collapsed = Boolean(state.adminRequestGroupCollapsed?.[courseId]);
        return `
          <section class="admin-request-group ${collapsed ? "is-collapsed" : ""}">
            <div class="admin-request-group-header">
              <button class="admin-request-group-toggle" type="button" data-action="admin-toggle-request-group" data-course-id="${escapeHtml(courseId)}">
                <span>
                  <b>${escapeHtml(getAdminCourseBuilderCourseLabel(courseId))}</b>
                  <small>${escapeHtml(courseRequests.length)} request${courseRequests.length === 1 ? "" : "s"}</small>
                </span>
                ${pendingCount ? `<span class="nav-badge">${pendingCount}</span>` : ""}
              </button>
              ${pendingCount ? `<button class="btn ghost admin-btn-sm" type="button" data-action="admin-approve-all-pending-course" data-course-id="${escapeHtml(courseId)}">Approve all pending</button>` : ""}
            </div>
            <div class="admin-request-group-body" style="display: flex; flex-direction: column; gap: 0.5rem; padding: 0.75rem 0.85rem;">
              ${courseRequests.map((request) => {
                const label = getAdminCourseBuilderProfileLabel(request.user_id);
                const status = String(request.status || "pending").toLowerCase();
                let statusBadge = "";
                let actionsHtml = "";

                if (status === "approved") {
                  statusBadge = `<span class="status-badge is-approved">Approved</span>`;
                  actionsHtml = `<button class="btn danger admin-btn-sm ghost" type="button" data-action="admin-reject-course-request" data-request-id="${escapeHtml(request.id)}">Reject</button>`;
                } else if (status === "rejected") {
                  statusBadge = `<span class="status-badge is-rejected">Rejected</span>`;
                  actionsHtml = `<button class="btn good admin-btn-sm ghost" type="button" data-action="admin-approve-course-request" data-request-id="${escapeHtml(request.id)}">Approve</button>`;
                } else {
                  statusBadge = `<span class="status-badge is-pending">Pending</span>`;
                  actionsHtml = `
                    <button class="btn good admin-btn-sm" type="button" data-action="admin-approve-course-request" data-request-id="${escapeHtml(request.id)}">Approve</button>
                    <button class="btn danger admin-btn-sm outline" type="button" data-action="admin-reject-course-request" data-request-id="${escapeHtml(request.id)}">Reject</button>
                  `;
                }

                return `
                  <div class="course-request-row">
                    <div style="display: flex; align-items: center; gap: 0.75rem;">
                      ${renderAdminAvatarBubble(request.user_id)}
                      <span style="display: flex; flex-direction: column; gap: 0.15rem;">
                        <b style="font-size: 0.92rem;">${escapeHtml(label)}</b>
                        <small style="color: var(--muted); font-size: 0.75rem;">Requested on ${escapeHtml(formatReportDateTime(request.created_at || ""))}</small>
                        <div style="margin-top: 0.25rem;">${statusBadge}</div>
                      </span>
                    </div>
                    <div class="stack" style="gap: 0.45rem;">
                      ${actionsHtml}
                    </div>
                  </div>
                `;
              }).join("")}
            </div>
          </section>
        `;
      }).join("") : `<p class="subtle">No enrollment requests match this filter.</p>`}
    </div>
  `;
}

function getAdminPlatformProfileDisplayName(profile) {
  return String(profile?.full_name || profile?.email || "Student").trim() || "Student";
}

function getAdminPlatformProfileMeta(profile) {
  const pieces = [];
  const email = String(profile?.email || "").trim();
  const phone = String(profile?.phone || "").trim();
  const year = normalizeAcademicYearOrNull(profile?.academic_year);
  const semester = normalizeAcademicSemesterOrNull(profile?.academic_semester);
  if (email) pieces.push(email);
  if (phone) pieces.push(phone);
  if (year !== null && semester !== null) pieces.push(`Y${year} S${semester}`);
  if (profile && profile.approved === false) pieces.push("Pending account");
  return pieces.join(" • ");
}

function getAdminPlatformProfileSearchText(profile) {
  const phone = normalizeNotificationTargetPhoneSearchText(profile?.phone);
  const phoneVariants = new Set([phone].filter(Boolean));
  if (phone.startsWith("20")) {
    phoneVariants.add(`0${phone.slice(2)}`);
  } else if (phone.startsWith("0")) {
    phoneVariants.add(`20${phone.slice(1)}`);
  }
  return normalizeNotificationTargetSearchText([
    profile?.id,
    profile?.full_name,
    profile?.email,
    profile?.phone,
    normalizeAcademicYearOrNull(profile?.academic_year) !== null ? `year ${profile.academic_year}` : "",
    normalizeAcademicSemesterOrNull(profile?.academic_semester) !== null ? `semester ${profile.academic_semester}` : "",
    [...phoneVariants].join(" "),
  ].join(" "));
}

function matchesAdminCourseEnrollmentQuery(profile, query) {
  const normalizedQuery = normalizeNotificationTargetSearchText(query);
  if (!normalizedQuery) return true;
  const haystack = getAdminPlatformProfileSearchText(profile);
  return normalizedQuery
    .split(/\s+/)
    .filter(Boolean)
    .every((term) => haystack.includes(term));
}

function getAdminCourseEnrollmentProfileRows(courseId) {
  const targetCourseId = String(courseId || "").trim();
  const enrollments = (state.adminCoursesPlatformEnrollments || [])
    .filter((row) => String(row?.course_id || "").trim() === targetCourseId);
  return enrollments
    .map((enrollment) => ({
      enrollment,
      profile: getAdminCourseBuilderProfile(enrollment.user_id),
    }))
    .sort((left, right) => {
      const leftName = getAdminPlatformProfileDisplayName(left.profile);
      const rightName = getAdminPlatformProfileDisplayName(right.profile);
      return leftName.localeCompare(rightName);
    });
}

function getAdminCourseEnrollmentCandidateProfiles(courseId) {
  const targetCourseId = String(courseId || "").trim();
  const enrolledUserIds = new Set(
    (state.adminCoursesPlatformEnrollments || [])
      .filter((row) => String(row?.course_id || "").trim() === targetCourseId)
      .map((row) => String(row?.user_id || "").trim())
      .filter(Boolean),
  );
  return (state.adminCoursesPlatformProfiles || [])
    .filter((profile) => {
      const profileId = String(profile?.id || "").trim();
      if (!isUuidValue(profileId) || enrolledUserIds.has(profileId)) return false;
      return true;
    })
    .sort((left, right) => getAdminPlatformProfileDisplayName(left).localeCompare(getAdminPlatformProfileDisplayName(right)));
}

function renderAdminCourseEnrollmentProfileRow(profile, options = {}) {
  const profileId = String(profile?.id || options.userId || "").trim();
  const name = getAdminPlatformProfileDisplayName(profile);
  const meta = profile ? getAdminPlatformProfileMeta(profile) : "Profile details unavailable";
  const action = String(options.action || "").trim();
  const buttonHtml = action === "add"
    ? `<button class="btn admin-btn-sm" type="button" data-action="admin-enroll-course-user" data-user-id="${escapeHtml(profileId)}">Enroll</button>`
    : action === "remove"
      ? `<button class="btn danger ghost admin-btn-sm" type="button" data-action="admin-remove-course-user" data-user-id="${escapeHtml(profileId)}">Remove</button>`
      : "";
  const dateLabel = options.assignedAt
    ? `<small>Enrolled ${escapeHtml(formatReportDateTime(options.assignedAt))}</small>`
    : "";
  const statusBadge = profile?.approved === false
    ? `<span class="status-badge is-pending">Pending account</span>`
    : `<span class="status-badge is-approved">Approved</span>`;
  return `
    <div class="course-request-row admin-course-enrollment-row">
      <div class="admin-course-enrollment-user">
        ${renderAdminAvatarBubble(profileId)}
        <span>
          <b>${escapeHtml(name)}</b>
          <small>${escapeHtml(meta)}</small>
          ${dateLabel}
        </span>
      </div>
      <div class="stack">
        ${profile ? statusBadge : `<span class="status-badge is-rejected">Missing profile</span>`}
        ${buttonHtml}
      </div>
    </div>
  `;
}

function getAdminCourseEnrollmentPickerSelectedIds(courseId) {
  const targetCourseId = String(courseId || "").trim();
  const selected = state.adminCourseEnrollmentPickerSelected || {};
  const rawIds = selected[targetCourseId];
  return new Set(Array.isArray(rawIds) ? rawIds.map((id) => String(id || "").trim()).filter(isUuidValue) : []);
}

function setAdminCourseEnrollmentPickerSelectedIds(courseId, selectedIds) {
  const targetCourseId = String(courseId || "").trim();
  if (!targetCourseId) return;
  if (!state.adminCourseEnrollmentPickerSelected || typeof state.adminCourseEnrollmentPickerSelected !== "object") {
    state.adminCourseEnrollmentPickerSelected = {};
  }
  state.adminCourseEnrollmentPickerSelected[targetCourseId] = Array.from(selectedIds || []).map((id) => String(id || "").trim()).filter(isUuidValue);
}

function renderAdminCourseEnrollmentPickerRow(profile, selectedIds) {
  const profileId = String(profile?.id || "").trim();
  const isSelected = selectedIds.has(profileId);
  const role = String(profile?.role || "student").trim();
  const accessEnabled = role === "admin" || profile?.courses_access_enabled !== false;
  const statusBadges = [
    `<span class="status-badge ${profile?.approved === false ? "is-pending" : "is-approved"}">${profile?.approved === false ? "Pending account" : "Approved"}</span>`,
    `<span class="status-badge ${accessEnabled ? "is-approved" : "is-rejected"}">Courses ${accessEnabled ? "on" : "off"}</span>`,
  ];
  if (role === "admin") {
    statusBadges.push(`<span class="status-badge is-approved">Admin</span>`);
  }
  return `
    <label class="admin-enrollment-picker-row ${isSelected ? "is-selected" : ""}">
      <input type="checkbox" data-action="admin-course-enrollment-pick-user" value="${escapeHtml(profileId)}" ${isSelected ? "checked" : ""} />
      <span class="admin-enrollment-picker-user">
        ${renderAdminAvatarBubble(profileId)}
        <span>
          <b>${escapeHtml(getAdminPlatformProfileDisplayName(profile))}</b>
          <small>${escapeHtml(getAdminPlatformProfileMeta(profile) || "No contact details")}</small>
        </span>
      </span>
      <span class="admin-enrollment-picker-badges">${statusBadges.join("")}</span>
    </label>
  `;
}

function renderAdminCourseEnrollmentPickerModal(selectedCourseId) {
  if (!state.adminCourseEnrollmentPickerOpen) {
    return "";
  }
  const addSearch = String(state.adminCourseEnrollmentAddSearch || "");
  const selectedIds = getAdminCourseEnrollmentPickerSelectedIds(selectedCourseId);
  const candidateProfiles = getAdminCourseEnrollmentCandidateProfiles(selectedCourseId)
    .filter((profile) => matchesAdminCourseEnrollmentQuery(profile, addSearch));
  const selectedCount = selectedIds.size;
  return `
    <div class="admin-enrollment-picker-modal" data-admin-course-enrollment-picker-portal="true">
      <button class="admin-enrollment-picker-backdrop" type="button" data-action="admin-close-course-enrollment-picker" aria-label="Close user enrollment picker"></button>
      <section class="admin-enrollment-picker-card" role="dialog" aria-modal="true" aria-label="Enroll users">
        <div class="admin-enrollment-picker-head">
          <div>
            <h4>Add users to course</h4>
            <p class="subtle">Search by phone, email, or name, then select one or more users to enroll.</p>
          </div>
          <button class="icon-btn" type="button" data-action="admin-close-course-enrollment-picker" aria-label="Close user enrollment picker">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <line x1="18" y1="6" x2="6" y2="18"></line>
              <line x1="6" y1="6" x2="18" y2="18"></line>
            </svg>
          </button>
        </div>
        <div class="admin-enrollment-picker-toolbar">
          <input id="admin-course-enrollment-add-search" type="search" value="${escapeHtml(addSearch)}" placeholder="Search by phone, email, or name..." autocomplete="off" />
          <span class="admin-enrollment-count-badge"><b>${selectedCount}</b> selected</span>
        </div>
        <div class="admin-enrollment-picker-list">
          ${candidateProfiles.length
            ? candidateProfiles.map((profile) => renderAdminCourseEnrollmentPickerRow(profile, selectedIds)).join("")
            : `<p class="subtle">No available users match this search.</p>`}
        </div>
        <div class="admin-enrollment-picker-actions">
          <button class="btn ghost admin-btn-sm" type="button" data-action="admin-clear-course-enrollment-selection" ${selectedCount ? "" : "disabled"}>Clear selection</button>
          <button class="btn admin-btn-sm" type="button" data-action="admin-enroll-selected-course-users" ${selectedCount ? "" : "disabled"}>
            Enroll selected${selectedCount ? ` (${selectedCount})` : ""}
          </button>
        </div>
      </section>
    </div>
  `;
}

function getAdminCourseEnrollmentPickerPortalCourseId() {
  if (
    state.route !== "admin"
    || state.adminPage !== ADMIN_COURSES_PLATFORM_PAGE
    || getAdminCoursePlatformSection() !== "enrollments"
  ) {
    return "";
  }
  const selectedCourseId = String(state.adminCourseBuilderCourseId || "").trim();
  return isUuidValue(selectedCourseId) ? selectedCourseId : "";
}

function removeAdminCourseEnrollmentPickerPortal() {
  document.querySelectorAll("[data-admin-course-enrollment-picker-portal='true']").forEach((node) => node.remove());
  document.body.classList.remove("is-admin-course-enrollment-picker-open");
}

function syncAdminCourseEnrollmentPickerPortal(options = {}) {
  removeAdminCourseEnrollmentPickerPortal();
  const selectedCourseId = getAdminCourseEnrollmentPickerPortalCourseId();
  if (!selectedCourseId) {
    state.adminCourseEnrollmentPickerOpen = false;
    return;
  }
  if (!state.adminCourseEnrollmentPickerOpen) {
    return;
  }
  const holder = document.createElement("div");
  holder.innerHTML = renderAdminCourseEnrollmentPickerModal(selectedCourseId).trim();
  const modal = holder.firstElementChild;
  if (!modal) return;
  document.body.appendChild(modal);
  document.body.classList.add("is-admin-course-enrollment-picker-open");
  wireAdminCourseEnrollmentPickerPortal(modal);
  if (options.focusSearch) {
    window.requestAnimationFrame(() => {
      const input = document.getElementById("admin-course-enrollment-add-search");
      if (!input) return;
      input.focus({ preventScroll: true });
      if (typeof input.setSelectionRange === "function") {
        const start = Number.isFinite(options.selectionStart) ? options.selectionStart : input.value.length;
        const end = Number.isFinite(options.selectionEnd) ? options.selectionEnd : start;
        input.setSelectionRange(start, end);
      }
    });
  }
}

function closeAdminCourseEnrollmentPickerPortal() {
  state.adminCourseEnrollmentPickerOpen = false;
  state.adminCourseEnrollmentAddSearch = "";
  setAdminCourseEnrollmentPickerSelectedIds(state.adminCourseBuilderCourseId, new Set());
  removeAdminCourseEnrollmentPickerPortal();
}

function wireAdminCourseEnrollmentPickerPortal(modal) {
  modal.addEventListener("input", (event) => {
    const target = event.target;
    if (!target || target.id !== "admin-course-enrollment-add-search") return;
    const selectionStart = typeof target.selectionStart === "number" ? target.selectionStart : null;
    const selectionEnd = typeof target.selectionEnd === "number" ? target.selectionEnd : selectionStart;
    state.adminCourseEnrollmentAddSearch = String(target.value || "");
    syncAdminCourseEnrollmentPickerPortal({
      focusSearch: true,
      selectionStart,
      selectionEnd,
    });
  });

  modal.addEventListener("change", (event) => {
    const target = event.target;
    if (!target || target.getAttribute("data-action") !== "admin-course-enrollment-pick-user") return;
    const userId = String(target.value || "").trim();
    if (!isUuidValue(userId)) return;
    const selectedIds = getAdminCourseEnrollmentPickerSelectedIds(state.adminCourseBuilderCourseId);
    if (target.checked) {
      selectedIds.add(userId);
    } else {
      selectedIds.delete(userId);
    }
    setAdminCourseEnrollmentPickerSelectedIds(state.adminCourseBuilderCourseId, selectedIds);
    syncAdminCourseEnrollmentPickerPortal();
  });

  modal.addEventListener("click", (event) => {
    const button = event.target.closest("[data-action]");
    if (!button || !modal.contains(button)) return;
    const action = button.getAttribute("data-action") || "";
    if (action === "admin-close-course-enrollment-picker") {
      closeAdminCourseEnrollmentPickerPortal();
    } else if (action === "admin-clear-course-enrollment-selection") {
      setAdminCourseEnrollmentPickerSelectedIds(state.adminCourseBuilderCourseId, new Set());
      syncAdminCourseEnrollmentPickerPortal();
    } else if (action === "admin-enroll-selected-course-users") {
      const selectedIds = Array.from(getAdminCourseEnrollmentPickerSelectedIds(state.adminCourseBuilderCourseId));
      if (!selectedIds.length) {
        toast("Select at least one user to enroll.");
        return;
      }
      button.disabled = true;
      button.classList.add("is-loading");
      button.textContent = "Enrolling...";
      adminEnrollPlatformCourseUsers(state.adminCourseBuilderCourseId, selectedIds).then(() => {
        closeAdminCourseEnrollmentPickerPortal();
        toast(`Enrolled ${selectedIds.length} user${selectedIds.length === 1 ? "" : "s"}.`);
        state.skipNextRouteAnimation = true;
        render();
      }).catch((error) => {
        console.warn("Courses platform admin action failed.", error?.message || error);
        toast(getErrorMessage(error, "Action failed."));
        syncAdminCourseEnrollmentPickerPortal();
      });
    }
  });
}

function renderAdminCourseEnrollmentsSection(courses, selectedCourseId, rows) {
  const enrolledSearch = String(state.adminCourseEnrollmentSearch || "");
  const enrollmentRows = getAdminCourseEnrollmentProfileRows(selectedCourseId)
    .filter(({ profile, enrollment }) => {
      if (profile) return matchesAdminCourseEnrollmentQuery(profile, enrolledSearch);
      return !String(enrolledSearch || "").trim() || String(enrollment?.user_id || "").includes(String(enrolledSearch || "").trim());
    });
  const selectedCourse = getAdminCourseBuilderCourse(selectedCourseId);
  return `
    <div class="course-builder-form admin-course-enrollments-panel">
      <div class="admin-requests-head">
        <div>
          <h4>Enrolled users</h4>
          <p class="subtle">Selected course: ${escapeHtml(getCoursePlatformCourseTitle(selectedCourse))}</p>
        </div>
        <div class="admin-enrollment-head-actions">
          <button class="admin-enrollment-add-btn" type="button" data-action="admin-open-course-enrollment-picker" aria-label="Add users to this course" title="Add users to this course">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <line x1="12" y1="5" x2="12" y2="19"></line>
              <line x1="5" y1="12" x2="19" y2="12"></line>
            </svg>
          </button>
          <span class="admin-enrollment-count-badge"><b>${rows.enrollments.length}</b> enrolled</span>
        </div>
      </div>
      <div class="admin-enrollment-search">
        <input id="admin-course-enrollment-search" type="search" value="${escapeHtml(enrolledSearch)}" placeholder="Search enrolled users..." autocomplete="off" />
      </div>
      <div class="course-builder-list">
        ${enrollmentRows.length
          ? enrollmentRows.map(({ enrollment, profile }) => renderAdminCourseEnrollmentProfileRow(profile, {
            action: "remove",
            userId: enrollment.user_id,
            assignedAt: enrollment.assigned_at,
          })).join("")
          : `<p class="subtle">No enrolled users match this course and search.</p>`}
      </div>
    </div>
  `;
}

function getAdminCoursePlatformSection() {
  const section = String(state.adminCoursePlatformSection || "").trim();
  return ADMIN_COURSES_PLATFORM_SECTIONS.has(section) ? section : "builder";
}

function renderSyllabusOutline(selectedCourse, rows) {
  if (!selectedCourse) {
    return `
      <div class="course-builder-outline">
        <div class="course-builder-outline-title">
          <span>Syllabus Outline</span>
        </div>
        <div class="outline-empty-state">
          No course selected or created yet.
        </div>
      </div>
    `;
  }
  const activeType = state.adminCourseBuilderActiveType;
  const activeId = state.adminCourseBuilderActiveId;
  const collapsedState = state.adminCourseBuilderModuleCollapsed || {};

  const modulesHtml = rows.modules.map((module, mIdx) => {
    const isModuleActive = activeType === "module-edit" && String(activeId) === String(module.id);
    const isCollapsed = Boolean(collapsedState[module.id]);
    const moduleLessons = rows.lessons.filter((lesson) => String(lesson.module_id || "") === String(module.id || ""));
    
    const lessonsListHtml = moduleLessons.map((lesson, lIdx) => {
      const isLessonActive = activeType === "lesson-edit" && String(activeId) === String(lesson.id);
      return `
        <div class="outline-lesson-item ${isLessonActive ? "is-active" : ""}">
          <div class="outline-lesson-info" data-action="admin-select-builder-active" data-active-type="lesson-edit" data-active-id="${escapeHtml(lesson.id)}">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="color: var(--brand-strong); flex-shrink: 0;">
              ${lesson.lesson_type === "video" 
                ? '<polygon points="23 7 16 12 23 17 23 7"></polygon><rect x="1" y="5" width="15" height="14" rx="2" ry="2"></rect>' 
                : '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline>'}
            </svg>
            <span class="outline-lesson-title" title="${escapeHtml(lesson.title)}">${escapeHtml(lesson.title)}</span>
          </div>
          <div class="outline-actions">
            <button class="outline-btn active-hover" type="button" data-action="admin-move-lesson" data-lesson-id="${escapeHtml(lesson.id)}" data-direction="up" ${lIdx === 0 ? "disabled" : ""} title="Move Up">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="18 15 12 9 6 15"/></svg>
            </button>
            <button class="outline-btn active-hover" type="button" data-action="admin-move-lesson" data-lesson-id="${escapeHtml(lesson.id)}" data-direction="down" ${lIdx === moduleLessons.length - 1 ? "disabled" : ""} title="Move Down">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>
            </button>
            <button class="outline-btn danger-hover" type="button" data-action="admin-delete-lesson" data-lesson-id="${escapeHtml(lesson.id)}" title="Delete Lesson">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
            </button>
          </div>
        </div>
      `;
    }).join("") || `<div class="outline-empty-state">No lessons in this module yet.</div>`;

    return `
      <div class="outline-module-card ${isCollapsed ? "is-collapsed" : ""} ${isModuleActive ? "is-active" : ""}" data-module-id="${escapeHtml(module.id)}">
        <div class="outline-module-header">
          <div class="outline-module-info" data-action="admin-select-builder-active" data-active-type="module-edit" data-active-id="${escapeHtml(module.id)}">
            <button class="outline-btn" style="width: 20px; height: 20px;" type="button" data-action="admin-toggle-module-collapse" data-module-id="${escapeHtml(module.id)}">
              <svg class="outline-module-toggle-caret" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>
            </button>
            <span class="outline-module-title" title="${escapeHtml(module.title)}">${escapeHtml(module.title)}</span>
          </div>
          <div class="outline-actions">
            <button class="outline-btn active-hover" type="button" data-action="admin-move-module" data-module-id="${escapeHtml(module.id)}" data-direction="up" ${mIdx === 0 ? "disabled" : ""} title="Move Up">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="18 15 12 9 6 15"/></svg>
            </button>
            <button class="outline-btn active-hover" type="button" data-action="admin-move-module" data-module-id="${escapeHtml(module.id)}" data-direction="down" ${mIdx === rows.modules.length - 1 ? "disabled" : ""} title="Move Down">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>
            </button>
            <button class="outline-btn active-hover" type="button" data-action="admin-select-builder-active" data-active-type="lesson-create" data-active-parent-id="${escapeHtml(module.id)}" title="Add Lesson">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            </button>
            <button class="outline-btn danger-hover" type="button" data-action="admin-delete-module" data-module-id="${escapeHtml(module.id)}" title="Delete Module">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
            </button>
          </div>
        </div>
        <div class="outline-lessons-list">
          ${lessonsListHtml}
        </div>
      </div>
    `;
  }).join("") || `<div class="outline-empty-state">No modules yet. Click "+ Add Module" below to start.</div>`;

  return `
    <div class="course-builder-outline">
      <div class="course-builder-outline-title">
        <span>Syllabus Outline</span>
        <button class="btn ghost admin-btn-sm" type="button" data-action="admin-select-builder-active" data-active-type="metadata" style="padding: 0.15rem 0.5rem; font-size: 0.75rem;">
          Edit Course Info
        </button>
      </div>
      <div class="course-builder-outline-scroll">
        ${modulesHtml}
      </div>
      <div class="course-builder-outline-footer">
        <button class="btn admin-btn-sm" style="width: 100%; justify-content: center;" type="button" data-action="admin-select-builder-active" data-active-type="module-create">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="margin-right: 0.25rem; vertical-align: middle;">
            <line x1="12" y1="5" x2="12" y2="19"></line>
            <line x1="5" y1="12" x2="19" y2="12"></line>
          </svg>
          Add Module
        </button>
      </div>
    </div>
  `;
}

